// Dados gerados automaticamente - SEFAZ-CE 2026
// Resumos (arrays de strings) e Questoes (10+ por topico)

export const R = {
"LP-1":["CONCORDANCIA VERBAL - Casos especiais cobrados pela FCC:","* HAVER (existir), FAZER (tempo/clima), SER (hora/data) = IMPESSOAL (singular)","  Correto: Houve irregularidades (NUNCA houveram)","  Correto: Faz 10 anos que... (NUNCA fazem)","* MAIORIA DE + plural -> singular (padrao FCC)","* Sujeito composto posposto -> pode concordar com o mais proximo","* Coletivo + de + plural -> verbo no singular ou plural","","REGENCIA VERBAL - Os mais cobrados:","* Aspirar (almejar) -> rege A: aspirava AO cargo","* Visar (objetivar) -> rege A: visando A evitar","* Assistir (ver/presenciar) -> rege A: assistiu AO julgamento","* Preferir -> regencia A (nunca 'do que'): prefiro X A Y","* Informar -> informou ALGUEM DE algo / informou algo A alguem","* Obedecer/desobedecer -> rege A","* Esquecer (pronominal) -> esquecer-se DE","","CRASE - Regras essenciais:","* OBRIGATORIA: antes de substantivo feminino com preposicao A","* PROIBIDA: antes de masculino, verbo, pronome pessoal, palavra repetida","* FACULTATIVA: antes de possessivo feminino, nome proprio feminino, ate/apos","* Locucoes: a vista, as pressas, a noite (sempre com crase)","","MORFOSSINTAXE:","* Processos de formacao: derivacao (prefixal, sufixal) e composicao","* Pronomes relativos: que, quem, cujo, onde, o qual","* Vozes do verbo: ativa, passiva (analitica e sintetica), reflexiva","","DICA FCC: Quando ver HAVER ou FAZER em concordancia, suspeite do uso impessoal (singular). A FCC adora pegadinhas com esses verbos."],
"LP-2":["INTERPRETACAO DE TEXTO - 22% das questoes de Portugues:","* FCC pede INFERENCIA: o que o texto PERMITE concluir, nao o explicito","* Cuidado com alternativas que EXAGERAM ou GENERALIZAM","* Relacao do texto com o contexto historico de producao","* Tema x tese x argumento: distinguir os tres","","COESAO TEXTUAL:","* REFERENCIAL: pronomes, sinonimos, hiperonimos que retomam (anafora)","  ou antecipam (catafora) elementos","* SEQUENCIAL (conectivos):","  - Causa: porque, pois, visto que, ja que","  - Concessao: embora, ainda que, apesar de, mesmo que","  - Condicao: se, caso, desde que, contanto que","  - Oposicao: mas, porem, contudo, todavia, ao passo que","  - Conclusao: logo, portanto, assim, por conseguinte","  - Finalidade: para que, a fim de que","","DENOTACAO E CONOTACAO:","* Denotacao: sentido literal, objetivo, do dicionario","* Conotacao: sentido figurado, subjetivo, expressivo","","DISCURSO:","* Direto: fala literal entre aspas/travessao","* Indireto: narrador relata a fala (verbo + que)","* Indireto livre: mistura, sem marca clara","","FIGURAS DE LINGUAGEM:","* Metafora, metonimia, hiperbole, ironia, eufemismo, antitese","","FUNCOES DA LINGUAGEM:","* Referencial (informacao), Emotiva (emissor), Conativa (receptor),","  Fatica (canal), Metalinguistica (codigo), Poetica (mensagem)","","PONTUACAO:","* Oracao adjetiva EXPLICATIVA = entre virgulas","* NUNCA virgula entre sujeito e verbo","* Ponto e virgula: coordenadas longas e enumeracoes","","DICA FCC: Em interpretacao, a resposta esta SEMPRE ancorada no texto. Desconfie de alternativas que trazem informacoes externas ou opinioes radicais."],
"MAT-1":["JUROS SIMPLES: J = C x i x n | M = C x (1 + i x n)","* Rendimento LINEAR (mesma quantia a cada periodo)","* Ex: C=10.000, i=2% a.m., n=3 -> J=600 -> M=10.600","","JUROS COMPOSTOS: M = C x (1 + i)^n","* Rendimento EXPONENCIAL (juros sobre juros)","* FCC sempre fornece o fator (ex: 1,02^3 = 1,0612)","* Ex: M = 10.000 x 1,0612 = 10.612","","TAXAS:","* EQUIVALENTES (compostos): mesma rentabilidade em prazos diferentes","* NOMINAL x EFETIVA: nominal nao considera capitalizacao; efetiva sim","* REAL: descontada a inflacao -> (1+i nominal)=(1+i real)(1+inflacao)","","DESCONTOS:","* RACIONAL (por dentro): sobre o valor atual","* COMERCIAL (por fora): sobre o valor nominal (mais comum, maior desconto)","","SISTEMA SAC (Amortizacao Constante):","* Amortizacao = PV / n (CONSTANTE)","* Juros = saldo devedor x i (DECRESCENTES)","* Prestacao DECRESCENTE","  Ex PV=60.000, n=3, i=10%:","  1a: J=6.000+A=20.000=26.000 (SD=40.000)","  2a: J=4.000+A=20.000=24.000 (SD=20.000)","  3a: J=2.000+A=20.000=22.000","","SISTEMA PRICE (Frances):","* Prestacoes CONSTANTES","* Juros decrescentes + amortizacao crescente","* Custo total MAIOR que o SAC","","FLUXO DE CAIXA:","* Valor Presente (VP): traz valores futuros para hoje","* Taxa Interna de Retorno (TIR): taxa que zera o VPL","","DICA FCC: Em SAC monte a tabela linha por linha. Em juros compostos, use sempre o fator fornecido pela banca."],
"MAT-2":["ESTATISTICA DESCRITIVA - Medidas de Posicao:","* MEDIA aritmetica: soma / n","* MEDIANA: valor central apos ORDENAR (n impar=central; n par=media dos 2 centrais)","* MODA: valor mais frequente (pode ser amodal, bimodal)","* QUARTIS: dividem em 4 partes (Q1=25%, Q2=mediana, Q3=75%)","","MEDIDAS DE DISPERSAO:","* AMPLITUDE: maximo - minimo","* VARIANCIA: media dos quadrados dos desvios","* DESVIO-PADRAO: raiz quadrada da variancia (mesma unidade dos dados)","* COEFICIENTE DE VARIACAO: desvio-padrao / media (compara dispersoes)","","PROBABILIDADE:","* P(A) = casos favoraveis / casos possiveis","* P(A ou B) = P(A) + P(B) - P(A e B) [adicao]","* P(A e B) = P(A) x P(B|A) [multiplicacao]","* Independentes: P(A e B) = P(A) x P(B)","* Complementar: P(A') = 1 - P(A)","","DISTRIBUICOES:","* Discretas: Bernoulli, Binomial, Poisson","* Continuas: Normal, t-Student, Qui-quadrado, F-Snedecor","","ANALISE COMBINATORIA:","* Combinacao C(n,k)=n!/[k!(n-k)!] (ordem NAO importa)","* Arranjo A(n,k)=n!/(n-k)! (ordem importa)","* Permutacao P(n)=n!","","RACIOCINIO LOGICO:","* Conectivos: E (conjuncao), OU (disjuncao), SE-ENTAO (condicional)","* MODUS PONENS: P->Q, P, logo Q","* MODUS TOLLENS: P->Q, nao-Q, logo nao-P (MAIS COBRADO)","* SILOGISMO HIPOTETICO: P->Q, Q->R, logo P->R","* Contrapositiva: P->Q equivale a nao-Q -> nao-P","* De Morgan: nao(P e Q)=nao-P ou nao-Q","* Negacao de 'todo': 'algum nao'; negacao de 'algum': 'nenhum'","","DICA FCC: Mediana SEMPRE exige ordenar os dados antes. Modus Tollens e a forma de argumento mais cobrada."],
"ADM-1":["GOVERNANCA PUBLICA:","* Conceito: sistema de direcionar, monitorar e avaliar a gestao","* Principios: capacidade de resposta, integridade, confiabilidade,","  transparencia, prestacao de contas (accountability)","* Instancias: estrategica, tatica e operacional","* Teoria da Agencia: principal (sociedade) x agente (gestor)","","MODELO DAS 3 LINHAS (IIA 2020):","* 1a LINHA: gestao operacional (donos do risco no dia a dia)","* 2a LINHA: funcoes de suporte (compliance, gestao de riscos, controles)","* 3a LINHA: AUDITORIA INTERNA (asseguracao INDEPENDENTE)","* Acima: orgao de governanca + partes externas (TCU, auditoria externa)","","GESTAO DE RISCOS (ISO 31000 / COSO):","* Risco = efeito da incerteza nos objetivos","* Processo: identificar -> analisar -> avaliar -> tratar -> monitorar","* Tratamento: evitar, reduzir, transferir, aceitar","* Apetite ao risco: nivel que a organizacao aceita assumir","","INTEGRIDADE (CE):","* Programa de Integridade do Poder Executivo do CE","* Codigo de Etica e Conduta da Adm. Publica Estadual do CE","* Sancoes eticas e disciplinares; PAD; TAC","* Assedio moral: Convencao OIT 190/2019","","LEI DE ACESSO A INFORMACAO (Lei 12.527/2011):","* Prazo: 20 dias + 10 dias (com justificativa)","* Sigilo: Reservado=5 anos, Secreto=15 anos, Ultra-secreto=25 anos","* Transparencia ATIVA (proativa) e PASSIVA (sob demanda)","","DICA FCC: Distinguir os papeis das 3 linhas e crucial. Auditoria interna (3a linha) NUNCA se confunde com gestao de riscos (2a linha)."],
"ADM-2":["NOVA LEI DE LICITACOES (Lei 14.133/2021) - Modalidades:","* PREGAO: bens e servicos comuns (criterio: menor preco/maior desconto)","* CONCORRENCIA: obras, servicos especiais, criterios variados","* CONCURSO: trabalho tecnico, cientifico ou artistico","* LEILAO: alienacao de bens (maior lance)","* DIALOGO COMPETITIVO: inovacao tecnologica ou solucao inexistente","  no mercado -> Adm. DIALOGA com licitantes antes de definir o objeto","","CRITERIOS DE JULGAMENTO:","* Menor preco, maior desconto, melhor tecnica, tecnica e preco,","  maior lance, maior retorno economico","","FASES (Lei 14.133):","* Preparatoria -> divulgacao do edital -> apresentacao de propostas","  -> julgamento -> habilitacao -> recursal -> homologacao","  (Inversao de fases: habilitacao APOS julgamento, como no pregao)","","CONTRATACAO DIRETA:","* DISPENSA (art. 75): valor baixo, emergencia, etc.","* INEXIGIBILIDADE (art. 74): inviabilidade de competicao","","IMPROBIDADE ADMINISTRATIVA (Lei 8.429/92 + 14.230/2021):","* Exige DOLO ESPECIFICO (culpa foi EXCLUIDA)","* Legitimidade ativa: EXCLUSIVA do MP","* Prescricao: 8 anos do fato ou 4 anos apos fim do vinculo","* Modalidades: enriquecimento ilicito, lesao ao erario, contra principios","","LEI ANTICORRUPCAO (Lei 12.846/2013):","* Responsabilidade OBJETIVA das pessoas juridicas","* Acordo de Leniencia reduz sancoes","","DICA FCC: O dialogo competitivo (modalidade nova) e cobrado em quase toda prova desde 2022. Improbidade agora exige DOLO; culpa nao basta mais."],
"ECO-1":["MICROECONOMIA - Oferta e Demanda:","* Lei da demanda: preco sobe -> quantidade demandada cai","* Lei da oferta: preco sobe -> quantidade ofertada sobe","* Equilibrio: ponto onde oferta = demanda","","ELASTICIDADES:","* ELASTICA: |Ed| > 1 (quantidade varia MAIS que o preco)","* INELASTICA: |Ed| < 1 (quantidade varia MENOS que o preco)","* UNITARIA: |Ed| = 1","* Bem inelastico: tributar aumenta receita (consumo pouco muda)","* Determinantes: substitutos, essencialidade, prazo, % da renda","","ECONOMIA DA TRIBUTACAO:","* PESO MORTO (perda de bem-estar): maior quanto mais elasticos os lados","* REGRA DE RAMSEY: tributar mais bens INELASTICOS minimiza ineficiencia","* CURVA DE LAFFER: ha aliquota otima; acima dela, arrecadacao CAI","* INCIDENCIA ECONOMICA: recai mais sobre o lado MENOS elastico","* Imposto Ad Valorem (%) x Especifico (valor fixo) x sobre Valor Adicionado","","ESTRUTURAS DE MERCADO:","* Concorrencia Perfeita: muitos, produto homogeneo, lucro zero no LP","* Monopolio: um ofertante, poder de preco, peso morto","* Oligopolio: poucos, interdependencia estrategica","* Concorrencia Monopolistica: muitos, produtos diferenciados","","DICA FCC: A Regra de Ramsey conflita com EQUIDADE, pois bens inelasticos sao essenciais (mais consumidos pelos pobres). Esse trade-off cai sempre."],
"ECO-2":["MACROECONOMIA - PIB pelas 3 oticas (mesmo resultado):","* DEMANDA: C + I + G + (X - M)","  C=consumo familias, I=investimento, G=gasto governo, X-M=exportacao liquida","* RENDA: Salarios + Lucros + Juros + Alugueis + Tributos indiretos","* PRODUCAO: soma dos Valores Adicionados (evita dupla contagem)","","AGREGADOS:","* PIB: producao no territorio nacional","* PNB: producao por residentes (PIB - renda enviada + renda recebida)","* PIB real x nominal -> Deflator do PIB = (PIB nom / PIB real) x 100","","MODELO IS-LM:","* IS (mercado de bens): juros altos -> investimento cai -> PIB cai","  Politica FISCAL desloca IS (aumento de G -> IS para direita)","* LM (mercado monetario): politica MONETARIA desloca LM","","INFLACAO:","* IPCA: indice oficial (IBGE), 1 a 40 salarios minimos","* IGP-M: FGV, usado em contratos/alugueis","* Valor real = valor nominal / (1 + inflacao)","","POLITICAS ECONOMICAS:","* FISCAL: gastos e tributos (expansionista combate recessao)","* MONETARIA: taxa de juros (Selic), reservas, open market","* CAMBIAL: regimes fixo, flutuante, bandas","","BALANCO DE PAGAMENTOS:","* Conta corrente (bens, servicos, rendas, transferencias)","* Conta capital e financeira","","DICA FCC: Multiplicador keynesiano = 1/(propensao marginal a poupar). Politica fiscal expansionista (aumento de G ou reducao de tributos) desloca a IS para a direita."],
"DCO-1":["CONTROLE DE CONSTITUCIONALIDADE - CONCENTRADO (STF):","* ADI: lei/ato federal ou estadual vs CF","* ADC: lei federal - confirma constitucionalidade","* ADPF: viola preceito fundamental (inclui leis pre-1988)","* ADO: omissao inconstitucional do legislador","* Efeitos: ERGA OMNES + EX TUNC + VINCULANTE","* Legitimados (art. 103): Presidente, Mesas, Governadores, PGR,","  Conselho Federal OAB, partidos com representacao, confederacoes","","CONTROLE DIFUSO (qualquer juizo):","* Qualquer juiz/tribunal pode afastar norma inconstitucional","* Efeitos: INTER PARTES + EX TUNC","* Senado pode suspender (art. 52, X) -> erga omnes + ex nunc","","SUMULA VINCULANTE (art. 103-A):","* Aprovada por 2/3 do STF (8 ministros)","* Vincula: todo Judiciario + Adm. Publica direta e indireta","* NAO vincula: o proprio STF e o Legislativo (funcao tipica)","","APLICABILIDADE DAS NORMAS:","* Eficacia PLENA: aplicacao imediata, sem restricao","* Eficacia CONTIDA: plena, mas pode ser restringida por lei","* Eficacia LIMITADA: depende de lei (programaticas)","","DIREITOS FUNDAMENTAIS:","* Art. 5 par. 1: aplicacao IMEDIATA","* Individuais, coletivos, sociais, nacionalidade, politicos","* Clausulas petreas (art. 60 par.4): forma federativa, voto direto,","  separacao dos poderes, direitos e garantias individuais","","DICA FCC: Decore os efeitos: DIFUSO=inter partes+ex tunc; CONCENTRADO=erga omnes+ex tunc+vinculante."],
"DAD-1":["PRINCIPIOS DA ADMINISTRACAO (art. 37 CF) - LIMPE:","* Legalidade, Impessoalidade, Moralidade, Publicidade, Eficiencia","* Implicitos: razoabilidade, proporcionalidade, autotutela, continuidade","","ATOS ADMINISTRATIVOS - Requisitos (COFIFOMOB):","* COmpetencia, FInalidade, FOrma, MOtivo, OBjeto","* Vicios em competencia/forma -> sanaveis (convalidacao)","* Vicios em finalidade/motivo/objeto -> insanaveis (anulacao)","","ATRIBUTOS:","* Presuncao de legitimidade (relativa)","* Imperatividade","* Autoexecutoriedade","* Tipicidade","","EXTINCAO:","* ANULACAO: ilegalidade -> EX TUNC (Sumula 473 STF)","* REVOGACAO: conveniencia/oportunidade -> EX NUNC (so a Adm.)","* CASSACAO: descumprimento de condicoes pelo beneficiario","* CONVALIDACAO: sana vicio sanavel","","PODERES DA ADMINISTRACAO:","* Vinculado, discricionario, hierarquico, disciplinar, regulamentar,","  de policia (preventivo e repressivo)","","RESPONSABILIDADE CIVIL (art. 37 par. 6):","* OBJETIVA (teoria do risco administrativo) para atos COMISSIVOS","* Conduta + dano + nexo causal (sem necessidade de culpa)","* Excludentes: fato da vitima, caso fortuito, fato de terceiro","* Direito de REGRESSO contra agente com dolo ou culpa","","ORGANIZACAO ADMINISTRATIVA:","* DESCONCENTRACAO: dentro da mesma PJ (orgaos), com hierarquia","* DESCENTRALIZACAO: para outra PJ (autarquias, fundacoes, EP, SEM),","  com vinculacao/supervisao (sem hierarquia)","","DICA FCC: Anulacao=ilegalidade+ex tunc. Revogacao=merito+ex nunc. Responsabilidade objetiva NAO exige culpa do Estado."],
"DCI-1":["CRIMES CONTRA A ORDEM TRIBUTARIA (Lei 8.137/1990):","* Art. 1 (PARTICULAR): crimes MATERIAIS","  SUMULA VINCULANTE 24: so se tipifica APOS lancamento DEFINITIVO","  Condutas: omitir informacao, fraudar documentos, negar nota fiscal","* Art. 2: crimes FORMAIS (consumam com a conduta)","* Mero inadimplemento do tributo declarado NAO e crime","","CRIMES CONTRA A ADMINISTRACAO PUBLICA:","* Por funcionario: peculato, concussao, corrupcao passiva, prevaricacao","* Por particular: corrupcao ativa, descaminho, contrabando","","LAVAGEM DE DINHEIRO (Lei 9.613/1998):","* Ocultar/dissimular origem de bens de INFRACAO PENAL","* Modelo ALL CRIMES (Lei 12.683/2012): qualquer crime antecedente","* 3 fases: Colocacao -> Dissimulacao (layering) -> Integracao","* Pena: 3 a 10 anos + multa","","CRIME ORGANIZADO (Lei 12.850/2013):","* 4+ pessoas, estrutura ordenada, divisao de tarefas","* Colaboracao premiada, infiltracao, acao controlada","","LEI ANTICORRUPCAO (Lei 12.846/2013):","* Responsabilidade OBJETIVA das pessoas juridicas","","DIREITO CIVIL:","* PRESCRICAO: extingue a PRETENSAO (acao). Pode ser renunciada/interrompida","* DECADENCIA: extingue o DIREITO potestativo. Legal=irrenunciavel","* LINDB: vigencia, aplicacao, conflito de leis no tempo/espaco","* Negocio juridico: existencia -> validade -> eficacia","","DICA FCC: A SV 24 e o ponto mais cobrado. Crimes do art. 1 (materiais) exigem lancamento definitivo; art. 2 (formais), nao."],
"DFI-1":["LRF (LC 101/2000) - Limites de despesa com pessoal (% da RCL):","                  GLOBAL    EXECUTIVO","* ESTADOS:         60%        49%   (Leg+TC=3%, Jud=6%, MP=2%)","* UNIAO:           50%        40,9%","* MUNICIPIOS:      60%        54%   (Camara=6%)","* Limite prudencial: 95% do limite -> vedacoes preventivas","","MECANISMOS DE CONTROLE:","* Art. 9 - LIMITACAO DE EMPENHO (contingenciamento):","  acionado BIMESTRALMENTE quando receita nao comporta metas","  nao se aplica a despesas constitucionalmente obrigatorias","* Art. 42 - VEDACAO nos 2 ultimos quadrimestres do mandato:","  proibido deixar restos a pagar sem disponibilidade de caixa","","PLANEJAMENTO:","* PPA (4 anos), LDO (metas e riscos fiscais), LOA (autoriza despesas)","* Anexo de Metas Fiscais e Anexo de Riscos Fiscais (na LDO)","","RESULTADO FISCAL:","* PRIMARIO: receitas nao financeiras - despesas nao financeiras (sem juros)","  Mede o ESFORCO FISCAL antes do servico da divida","* NOMINAL: Primario - Juros nominais (variacao total da divida)","","DIVIDA E ENDIVIDAMENTO:","* Operacao de credito por antecipacao de receita (ARO)","* Regra de ouro: vedado credito que supere despesas de capital","","RELATORIOS:","* RREO (Execucao Orcamentaria): BIMESTRAL","* RGF (Gestao Fiscal): QUADRIMESTRAL","","DICA FCC: Memorize os limites: ESTADOS=60/49; UNIAO=50/40,9; MUNICIPIOS=60/54. A FCC cobra os tres com frequencia."],
"DFI-2":["ORCAMENTO PUBLICO - Ciclo: PPA -> LDO -> LOA -> Execucao -> Controle","","INSTRUMENTOS (art. 165 CF):","* PPA (4 anos): diretrizes, objetivos e metas regionalizadas","* LDO: orienta a LOA, metas fiscais, alteracoes tributarias","* LOA: orcamento fiscal, seguridade social, investimento das estatais","","PRINCIPIOS ORCAMENTARIOS:","* UNIVERSALIDADE: todas as receitas e despesas no orcamento","* ANUALIDADE: vigencia de 1 ano (exercicio financeiro)","* UNIDADE: orcamento unico por ente","* EXCLUSIVIDADE: LOA so contem materia orcamentaria","* ORCAMENTO BRUTO: valores totais, sem deducoes","* LEGALIDADE: orcamento aprovado por lei","* NAO AFETACAO/NAO VINCULACAO da receita de impostos (com excecoes)","","CREDITOS ADICIONAIS (art. 41 Lei 4.320):","* SUPLEMENTARES: reforco de dotacao existente (LOA pode autorizar)","* ESPECIAIS: nova dotacao (autorizacao legislativa + fonte)","* EXTRAORDINARIOS: urgentes/improvistos (guerra, calamidade)","  -> DECRETO do Executivo, sem indicacao previa de fonte","","RECEITAS E DESPESAS:","* CORRENTES: tributaria, patrimonial, pessoal, custeio, juros","* CAPITAL: operacoes de credito, alienacao de bens, investimentos","","RESTOS A PAGAR e Despesas de Exercicios Anteriores (DEA)","","DICA FCC: Creditos EXTRAORDINARIOS sao os unicos abertos por DECRETO sem indicacao previa de fonte. Sempre cobrado para distinguir dos demais."],
"CGP-1":["CONTABILIDADE PUBLICA - Estagios da RECEITA (MCASP 11a ed.):","1. PREVISAO (na LOA)","2. LANCAMENTO (individualiza o credito - art. 53 Lei 4.320)","3. ARRECADACAO (contribuinte paga ao agente arrecadador/banco)","4. RECOLHIMENTO (entrega ao Tesouro - conta unica)","","Estagios da DESPESA:","1. FIXACAO (na LOA)","2. EMPENHO (art. 58: cria obrigacao de pagar)","   Modalidades: ORDINARIO, ESTIMATIVO, GLOBAL","3. LIQUIDACAO (art. 63: verifica o direito do credor)","4. PAGAMENTO (art. 64: entrega ao credor)","","RESTOS A PAGAR:","* PROCESSADOS: empenho + LIQUIDACAO feitos (Estado DEVE pagar)","* NAO PROCESSADOS: so empenho (liquidacao pendente)","* Cancelamento: apos 2 exercicios (regra geral)","","PCASP (Plano de Contas Aplicado ao Setor Publico):","* Classes: 1-Ativo, 2-Passivo, 3-VPD, 4-VPA, 5-Controles devedores,","  6-Controles credores, 7 e 8-Controles especificos","","NBC TSP - Caracteristicas qualitativas:","* FUNDAMENTAIS: Relevancia + Representacao Fidedigna","* DE MELHORIA: Comparabilidade, Verificabilidade, Tempestividade,","  Compreensibilidade","","DEMONSTRACOES (Lei 4.320 + MCASP):","* Balanco Orcamentario, Financeiro, Patrimonial, Demonstracao das","  Variacoes Patrimoniais (DVP)","","DICA FCC: RP PROCESSADOS (ja liquidados = Estado deve) vs NAO PROCESSADOS (liquidacao pendente). Cai em toda prova de contabilidade publica."],
"CGP-2":["CONTABILIDADE GERAL - Caracteristicas qualitativas (CPC 00):","* Fundamentais: relevancia e representacao fidedigna","* De melhoria: comparabilidade, verificabilidade, tempestividade,","  compreensibilidade","","ESTOQUES (CPC 16):","* Custo: aquisicao + transformacao + outros para deixar pronto","* PEPS: estoque final a precos mais RECENTES","* Media Ponderada Movel (MPM): recalcula a cada entrada","* CMV = Estoque Inicial + Compras - Estoque Final","* Mensuracao: menor valor entre custo e valor realizavel liquido","","ATIVO IMOBILIZADO (CPC 27):","* Reconhecimento: beneficio futuro provavel + custo confiavel","* Depreciacao: linha reta, saldos decrescentes, unidades produzidas","* Valor residual e vida util revisados periodicamente","","ATIVO INTANGIVEL (CPC 04):","* Identificavel, sem substancia fisica, controlado","* Goodwill gerado internamente NAO e reconhecido","","IMPAIRMENT (CPC 01):","* Reducao ao valor recuperavel quando valor contabil > recuperavel","","PROVISOES (CPC 25):","* Reconhecer: obrigacao presente + saida provavel + estimativa confiavel","* Passivo contingente possivel: notas explicativas","* Remoto: nada divulga","","DEMONSTRACOES CONTABEIS:","* BP (Ativo=Passivo+PL), DRE, DRA, DMPL, DFC (direto/indireto), DVA","","DICA FCC: PEPS deixa o estoque final a precos mais recentes (mais caro em inflacao). Saiba calcular CMV passo a passo."],
"COA-1":["VALOR JUSTO (CPC 46 / IFRS 13) - Hierarquia:","* NIVEL 1: precos cotados em mercado ATIVO para ativos IDENTICOS","* NIVEL 2: dados OBSERVAVEIS distintos (ativos similares, taxas)","* NIVEL 3: dados NAO OBSERVAVEIS (premissas internas)","* Regra: MAXIMIZAR dados observaveis; mais disclosure no nivel 3","","AJUSTE A VALOR PRESENTE (AVP):","* Operacoes de longo prazo trazidas a valor presente","","INSTRUMENTOS FINANCEIROS (CPC 48 / IFRS 9):","* Categorias: custo amortizado, valor justo por ORA, valor justo por resultado","* Perdas esperadas (modelo de impairment)","","ARRENDAMENTO (CPC 06 R2 / IFRS 16):","* Arrendatario reconhece: ATIVO DE DIREITO DE USO + PASSIVO","* Excecoes: prazo <= 12 meses e baixo valor","* Extingue distincao operacional vs financeiro para o arrendatario","","PROPRIEDADE PARA INVESTIMENTO (CPC 28):","* Mantida para renda/valorizacao; mensuracao a custo ou valor justo","","COMBINACAO DE NEGOCIOS (CPC 15 / IFRS 3):","* Goodwill = (Contraprestacao + PNC + interesse previo) - VJ liquido","* Positivo = GOODWILL (intangivel, nao amortizavel, impairment anual)","* Negativo = COMPRA VANTAJOSA (ganho no resultado imediatamente)","","MEP (CPC 18 / IAS 28):","* Coligadas (influencia significativa >= 20% votante) e controladas","* Investimento atualizado pelo % do PL da investida","","SUBVENCAO GOVERNAMENTAL (CPC 07):","* Reconhecida no resultado na base sistematica (Lei 14.789/2023)","","DICA FCC: Goodwill = Contraprestacao + PNC + interesse previo - VJ liquido. Positivo=goodwill; negativo=compra vantajosa (vai pro resultado)."],
"COA-2":["CONTABILIDADE DE CUSTOS - Classificacoes:","* DIRETOS x INDIRETOS (identificaveis ou nao ao produto)","* FIXOS x VARIAVEIS (independem ou variam com a producao)","  Custo fixo UNITARIO diminui com mais producao (diluicao)","  Custo variavel TOTAL aumenta, unitario constante","","MARGEM DE CONTRIBUICAO:","* MC unitaria = PV - CV unitario","* Indice de MC = MC / PV","","PONTOS DE EQUILIBRIO:","* CONTABIL (PEC) = CF / MCu (cobre custos contabeis, inclui depreciacao)","* ECONOMICO (PEE) = (CF + custo de oportunidade) / MCu","* FINANCEIRO (PEF) = (CF - depreciacao) / MCu (so saidas de caixa)","","METODOS DE CUSTEIO:","* ABSORCAO: rateia TODOS os custos (exigido pelo fisco/societario)","* VARIAVEL (direto): so custos variaveis no produto; fixos = despesa","  do periodo. Melhor para DECISAO gerencial","* ABC (Activity-Based Costing): custos por ATIVIDADES, maior precisao","","DEPARTAMENTALIZACAO:","* Centros produtivos e auxiliares; rateio por criterios tecnicos","","CUSTO PADRAO:","* Comparacao padrao x real -> analise de variacoes","","PRODUCAO:","* Por ordem, continua e conjunta (coprodutos, subprodutos)","","DICA FCC: PEC = CF/MCu. Questao classica: dar CF, PV e CV e pedir os 3 pontos de equilibrio. No PEF subtrai-se a depreciacao do CF."],
"DTR-1":["CTN - OBRIGACAO TRIBUTARIA (arts. 113-138):","* PRINCIPAL: pagar tributo ou penalidade pecuniaria","* ACESSORIA: fazer, nao fazer ou tolerar (descumprir -> vira principal)","* Fato Gerador: situacao NECESSARIA E SUFICIENTE prevista em lei","* Sujeito ativo (credor) e passivo (contribuinte ou responsavel)","","RESPONSABILIDADE TRIBUTARIA:","* Por SUBSTITUICAO: desde a origem (ex: ICMS-ST)","* Por TRANSFERENCIA: evento posterior (sucessao, terceiros)","* Art. 135: dolo -> responsabilidade PESSOAL dos socios-gerentes","* Solidariedade: NAO comporta beneficio de ordem (art. 124 PU)","","LANCAMENTO:","* DE OFICIO: Fisco age sozinho (IPTU, IPVA)","* POR DECLARACAO: contribuinte declara, Fisco lanca","* POR HOMOLOGACAO: contribuinte antecipa SEM previo exame","  Prazo decadencial: 5 anos do FG (art. 150 par.4)","","SUSPENSAO (art. 151) - MDRRLP:","* Moratoria, Deposito integral, Reclamacoes/Recursos, Liminar/Tutela,","  Parcelamento","","EXTINCAO (art. 156) - 11 modalidades:","* Pagamento, compensacao, transacao, remissao, prescricao, decadencia,","  conversao de deposito, consignacao, decisao admin/judicial, dacao em pagamento","","EXCLUSAO:","* ISENCAO (exclui o tributo) e ANISTIA (exclui a multa)","","DECADENCIA x PRESCRICAO:","* Decadencia (art. 173): extingue o direito de LANCAR (5 anos)","* Prescricao (art. 174): extingue a acao de COBRAR (5 anos da constituicao)","","DICA FCC: Diferenciar SUSPENSAO (MDRRLP), EXTINCAO (art. 156) e EXCLUSAO (isencao/anistia) e obrigatorio. A banca mistura as modalidades."],
"DTR-2":["REFORMA TRIBUTARIA - EC 132/2023 + LC 214/2025:","","IBS (Imposto sobre Bens e Servicos):","* Substitui: ICMS + ISS","* Competencia: COMPARTILHADA (Estados/DF/Municipios)","* Administracao: COMITE GESTOR do IBS (art. 156-B CF)","* Nao-cumulatividade PLENA (credito amplo)","* Principio do DESTINO: imposto devido no LOCAL DE CONSUMO","* Aliquota: cada ente define a sua (referencia)","","CBS (Contribuicao sobre Bens e Servicos):","* Substitui: PIS + COFINS","* Competencia: FEDERAL (Uniao)","* Administracao: Receita Federal","","IS (Imposto Seletivo):","* Art. 153, VIII CF: bens/servicos PREJUDICIAIS a saude/meio ambiente","* Competencia: FEDERAL","* NAO integra a base do IBS e CBS","","PERIODO DE TRANSICAO:","* 2026: aliquota teste 0,1%","* 2027-2028: CBS plena, IBS gradual","* 2029-2032: reducao gradual do ICMS/ISS","* 2033: sistema novo COMPLETO","","CARACTERISTICAS DO IVA DUAL BRASILEIRO:","* IBS (subnacional) + CBS (federal) = modelo de IVA dual","* Cashback para baixa renda; cesta basica com aliquota zero","","DICA FCC: IBS (estados/municipios, Comite Gestor) vs CBS (federal, Receita Federal). Principio do DESTINO = imposto no local de consumo, reduzindo a guerra fiscal."],
"DTR-3":["LC 87/1996 - LEI KANDIR (ICMS Nacional):","* NAO-CUMULATIVIDADE: credito do imposto das etapas anteriores","* Isencao/nao-incidencia NAO gera credito (salvo disposicao contraria)","* ATIVO PERMANENTE: credito a razao de 1/48 por mes (4 anos)","* USO E CONSUMO: credito VEDADO ate 2033 (art. 33)","* Aliquotas interestaduais: 7% ou 12% conforme regiao","* DIFAL (EC 87/2015): diferencial nas vendas a consumidor final","","LC 24/1975 - CONFAZ:","* Beneficios fiscais de ICMS exigem CONVENIO","* Aprovacao: UNANIMIDADE dos presentes (minimo 4/5 dos estados)","* Um estado pode VETAR","* LC 160/2017: remissao de beneficios concedidos sem convenio","","LC 123/2006 - SIMPLES NACIONAL:","* MEI (ate 81 mil/ano), ME (ate 360 mil), EPP (ate 4,8 milhoes)","* DAS: guia unica reunindo tributos","* ICMS-ST NAO entra no DAS (recolhido separadamente)","* Vedacoes do art. 17","","LC 116/2003 - ISSQN:","* Competencia MUNICIPAL","* Lista anexa define o que e servico (ISS) e o que e ICMS","","LC 105/2001: sigilo bancario e seu compartilhamento com o Fisco","LC 192/2022: ICMS monofasico sobre combustiveis","","DICA FCC: Convenio CONFAZ exige UNANIMIDADE. ICMS-ST fora do DAS e questao classica do Simples Nacional."],
"LTE-1":["ICMS-CE (Lei 18.665/2023 + Decreto 33.327/2019 - RICMS):","* Fato gerador: circulacao de mercadorias + transporte interestadual/","  intermunicipal + comunicacao","* Contribuinte: quem realiza operacoes com habitualidade","","ICMS POR DENTRO (calculo interno):","* O imposto integra a propria base de calculo","* Formula: BC = valor sem ICMS / (1 - aliquota)","* Ex: produto 82, aliquota 18% -> BC = 82/0,82 = 100 -> ICMS = 18","* Aliquota efetiva (21,95%) MAIOR que a nominal (18%)","","SUBSTITUICAO TRIBUTARIA NO CE:","* PROGRESSIVA (para frente): fabricante/importador recolhe o ICMS das","  etapas futuras com base em MVA ou pauta fiscal","  Se o FG presumido NAO ocorrer -> RESTITUICAO (STF RE 593.849)","* REGRESSIVA (diferimento): posterga o recolhimento","","NAO-CUMULATIVIDADE NO CE:","* Uso e consumo: credito VEDADO ate 2033","* Ativo permanente: 1/48 por mes","","ITCD-CE (Lei 15.812/2015):","* Causa mortis + doacao de quaisquer bens","* Aliquotas PROGRESSIVAS; maxima de 8% (Resolucao Senado 9/1992)","","IPVA-CE (Lei 12.023/1992):","* Fato gerador: propriedade de veiculo em 1 de janeiro","* Base: valor venal","","FECOP (LC 37/2003):","* Adicional de ate 2% no ICMS sobre produtos superfluos","* Vinculado ao combate a pobreza (art. 82 ADCT)","","DICA FCC: O ICMS-CE segue a Lei Kandir (LC 87/96) como norma nacional. As questoes verificam se voce aplica corretamente a regra nacional ao contexto cearense."],
"FLD-1":["FLUENCIA DE DADOS - SQL (ordem de execucao):","FROM -> JOIN -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY -> LIMIT","","WHERE x HAVING:","* WHERE: filtra LINHAS antes do agrupamento (sem funcoes de agregacao)","* HAVING: filtra GRUPOS apos GROUP BY (usa SUM, COUNT, AVG, MAX, MIN)","","TIPOS DE JOIN:","* INNER: so registros com correspondencia em ambas as tabelas","* LEFT: todos da esquerda + correspondentes da direita (NULL se nao houver)","* RIGHT: inverso do LEFT","* FULL OUTER: todos de ambas","* CROSS: produto cartesiano","","ARQUITETURA DE DADOS:","* Data Warehouse: dados curados, schema-on-write, otimizado para BI","* Data Lake: dados brutos, schema-on-read, barato e flexivel","* Data Lakehouse: combina os dois (ACID + analitica)","* Data Mart: subconjunto do DW por area","","TIPOS DE DADOS:","* Estruturados (tabelas), nao estruturados (texto/imagem), semiestruturados (JSON/XML)","","ETL x ELT:","* ETL: Extract -> Transform -> Load (tradicional)","* ELT: Extract -> Load -> Transform (cloud/big data)","","METODOLOGIA CRISP-DM:","* Negocio -> Dados -> Preparacao -> Modelagem -> Avaliacao -> Implantacao","","MACHINE LEARNING:","* Supervisionado, nao supervisionado, semi-supervisionado","* Deep Learning, NLP, IA generativa","","LGPD (Lei 13.709/2018):","* Base legal do Fisco: cumprimento de obrigacao legal (art. 7, II)","* Controlador, operador, encarregado (DPO), titular","* Sigilo fiscal: CTN arts. 198-199","","SEGURANCA: CIA (Confidencialidade, Integridade, Disponibilidade)","","DICA FCC: HAVING vs WHERE e a questao mais cobrada de SQL. HAVING filtra grupos (apos agrupamento) e pode usar SUM/COUNT/AVG."],
"FPB-1":["FINANCAS PUBLICAS - Funcoes do Governo (Musgrave, 1959):","1. ALOCATIVA: corrigir FALHAS DE MERCADO","   bens publicos, externalidades, monopolios naturais, assimetria","2. DISTRIBUTIVA: reduzir DESIGUALDADE","   impostos progressivos, transferencias, subsidios","3. ESTABILIZADORA: emprego, precos, crescimento","   politica fiscal anticiclica","","FALHAS DE MERCADO:","* Bens publicos PUROS: NAO RIVAL + NAO EXCLUDENTE -> FREE RIDER","  Ex: defesa nacional, iluminacao publica, farol maritimo","* Externalidade NEGATIVA (poluicao): custo social > privado","  -> producao acima do otimo -> IMPOSTO PIGOUVIANO","* Externalidade POSITIVA (vacinacao): beneficio social > privado","  -> producao abaixo do otimo -> SUBSIDIO","* Monopolio natural: custos decrescentes -> regulacao","","TRIBUTACAO:","* Capacidade contributiva x criterio do beneficio","* Progressivo, regressivo, proporcional","* Trade-off eficiencia x equidade","","RESULTADO FISCAL:","* PRIMARIO: receitas nao financeiras - despesas nao financeiras (sem juros)","* NOMINAL: Primario - Juros nominais","* NFSP: -Resultado Primario + Juros nominais (variacao da divida liquida)","","DEFICIT PUBLICO E FINANCIAMENTO:","* Emissao de moeda, divida interna/externa, venda de ativos","","DICA FCC: Free rider justifica a provisao estatal de bens publicos. Superavit primario NAO significa que a divida caiu (se os juros forem maiores, ela cresce)."],
};

export const Q = {
"LP-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Assinale a alternativa com concordancia verbal CORRETA:",o:["A) Houveram muitas irregularidades.","B) Fazem dois anos que nao declara.","C) Os dados e o relatorio foram encaminhados.","D) A maioria dos auditores aprovaram.","E) E necessario maiores esclarecimentos."],g:"C",c:"Sujeito composto -> plural. A: HAVER impessoal=Houve. B: FAZER tempo=Faz. D: maioria de+plural=singular. E: sujeito 'maiores esclarecimentos'=Sao necessarios."},
{a:2022,r:"FCC/Fiscal-2022",q:"A regencia verbal CORRETA esta em:",o:["A) Aspirava o cargo ha anos.","B) Preferiu de oficio do que homologacao.","C) Informou os auditores da legislacao.","D) Assistiu o procedimento.","E) Pagou o tributo visando a evitar a execucao."],g:"E",c:"'visar a'=objetivo. A: aspirar AO cargo. B: preferir nunca 'do que'. C: informar SOBRE. D: assistir (ver)=AO."},
{a:2021,r:"FCC/PGE-2021",q:"Quanto ao emprego da crase, e CORRETO:",o:["A) Entregou os documentos a ele.","B) Encaminhou a Receita a documentacao.","C) Referiu-se a multa aplicada.","D) Decisao contraria a implementar.","E) Prazo a ser cumprido."],g:"C",c:"Crase antes de substantivo feminino. A: pronome pessoal=PROIBIDA. D/E: infinitivo=PROIBIDA."},
{a:2020,r:"FCC/TRF-2020",q:"A coesao REFERENCIAL e realizada por:",o:["A) Conjuncoes logico-semanticas.","B) Pronomes, sinonimos que retomam elementos.","C) Progressao tematica.","D) Adverbios de modo.","E) Artigos definidos."],g:"B",c:"Coesao REFERENCIAL: retomada (anafora) ou antecipacao (catafora) - pronomes, sinonimos. Diferente da SEQUENCIAL (conectivos)."},
{a:2019,r:"FCC/ISS-2019",q:"'Se tivesse pago, nao teria sido autuado' expressa:",o:["A) Concessao","B) Finalidade","C) Condicao contrafactual","D) Causa no presente","E) Temporalidade"],g:"C",c:"CONDICIONAL contrafactual: 'tivesse pago'+'teria sido'=hipotese NAO realizada no passado."},
{a:2023,r:"FCC/TRT-2023",q:"A concordancia nominal CORRETA esta em:",o:["A) Anexo seguem os documentos.","B) E proibido entrada de estranhos.","C) Os funcionarios ficaram alerta.","D) Bastantes pessoas compareceram.","E) Menas burocracia no processo."],g:"D",c:"'Bastante' como pronome adjetivo concorda: bastantes pessoas. A: anexoS. B: proibidA entrada (com artigo). C: alertaS (adjetivo). E: 'menas' nao existe -> menos."},
{a:2022,r:"FCC/TCE-2022",q:"Em 'Vossa Excelencia ___ os documentos', completa-se com:",o:["A) trouxestes","B) trouxe","C) trouxeram","D) trazeis","E) trouxeste"],g:"B",c:"Pronome de tratamento (Vossa Excelencia) concorda em 3a pessoa do singular: trouxe."},
{a:2021,r:"FCC/Fiscal-2021",q:"O 'que' funciona como conjuncao integrante em:",o:["A) O livro que comprei e bom.","B) Espero que voce venha.","C) A casa, que e velha, caiu.","D) Que dia lindo!","E) Ele e mais alto que voce."],g:"B",c:"Conjuncao integrante introduz oracao substantiva (espero ISSO). A/C: pronome relativo. D: interjeicao. E: comparativo."},
{a:2020,r:"FCC/PGE-2020",q:"Na regencia nominal, esta CORRETO:",o:["A) Ansioso de ver o resultado.","B) Apto para o cargo.","C) Compativel a norma.","D) Preferivel que o outro.","E) Habil de negociar."],g:"B",c:"'Apto para/a'=correto. A: ansioso POR. C: compativel COM. D: preferivel A. E: habil EM."},
{a:2019,r:"FCC/TRF-2019",q:"O pronome 'cujo':",o:["A) Pode ser substituido por 'que'.","B) Indica posse e concorda com o termo seguinte.","C) Retoma o termo anterior.","D) E pronome demonstrativo.","E) E invariavel."],g:"B",c:"'Cujo'=relativo POSSESSIVO, concorda com o substantivo que o SEGUE. Nao admite artigo antes nem depois."},
{a:2023,r:"FCC/Adm-2023",q:"A virgula esta empregada CORRETAMENTE em:",o:["A) O auditor, verificou os livros.","B) Sao Paulo, 10 de maio de 2026.","C) Comprou livros, canetas e, lapis.","D) Quem estuda, passa.","E) O ICMS imposto estadual incide."],g:"B",c:"Virgula separa local e data. A: entre sujeito e verbo=erro. C: antes de 'e' em enumeracao=erro. D: entre sujeito e verbo. E: aposto sem virgula."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Assinale a frase com regencia nominal CORRETA:",o:["A) Tenho preferencia por cafe do que cha","B) Ele e respeitoso para com os colegas","C) Estou ansioso de viajar","D) E imune de criticas","E) Apto de exercer o cargo"],g:"B",c:"'Respeitoso para com' e correto. A: preferencia POR X A Y (nunca 'do que'). C: ansioso POR. D: imune A. E: apto A/PARA."},
{a:2023,r:"FCC/Fiscal-2023",q:"Em 'Fazem cinco anos que ele trabalha aqui', o erro e:",o:["A) Nenhum","B) 'Fazem' deveria ser 'Faz' (verbo fazer indicando tempo e impessoal)","C) 'trabalha' deveria ser plural","D) Falta virgula","E) 'anos' deveria ser singular"],g:"B",c:"Verbo FAZER indicando tempo decorrido e impessoal: fica no singular. Correto: 'Faz cinco anos'."},
{a:2022,r:"FCC/PGE-2022",q:"Na frase 'Ela mesma resolveu a questao', 'mesma' e:",o:["A) Adverbio","B) Pronome de reforco que concorda com 'ela'","C) Substantivo","D) Conjuncao","E) Preposicao"],g:"B",c:"'Mesmo/mesma', como pronome demonstrativo de reforco, CONCORDA com o termo a que se refere: ela mesma, eles mesmos."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O acento indicativo de crase e OBRIGATORIO em:",o:["A) Refiro-me a ele","B) Vou a Bahia","C) Chegou a pe","D) Estudo de manha a noite (a=preposicao+artigo)","E) Entreguei a todos"],g:"D",c:"'Da manha a noite': crase obrigatoria (preposicao a + artigo a noite). A/E: pronomes -> sem crase. B: 'a Bahia' tem crase (vou A a Bahia), mas a alternativa D e a inequivoca aqui. C: locucao 'a pe' (masculino) nao tem crase."},
{a:2023,r:"FCC/Fiscal-2023",q:"A concordancia esta CORRETA em:",o:["A) Vende-se casas","B) Precisa-se de funcionarios","C) Aluga-se apartamentos","D) Conserta-se computadores","E) Fazem-se reparos errados"],g:"B",c:"'Precisa-se de funcionarios': 'se' e indice de indeterminacao do sujeito (verbo + preposicao), fica no SINGULAR. As demais (A,C,D) sao voz passiva sintetica e exigem plural."},
{a:2022,r:"FCC/PGE-2022",q:"O 'a' craseado em 'a partir de':",o:["A) E obrigatorio","B) NAO ocorre crase (expressao 'a partir de' nao tem acento)","C) Depende do contexto","D) So antes de feminino","E) E facultativo"],g:"B",c:"'A partir de' NUNCA recebe crase (e expressao consagrada sem acento). Pegadinha classica da FCC."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Em 'Os Estados Unidos enviaram ajuda', a concordancia:",o:["A) Esta errada","B) Esta correta: nome com artigo plural pede verbo no plural","C) Deveria ser 'enviou'","D) Falta crase","E) 'ajuda' deveria ser plural"],g:"B",c:"Nomes proprios de lugar com artigo no plural (Os Estados Unidos, Os Andes) levam o verbo ao PLURAL: 'Os Estados Unidos enviaram'."},
{a:2023,r:"FCC/Fiscal-2023",q:"A regencia do verbo 'implicar' (acarretar) e:",o:["A) Implicar EM algo","B) Implicar algo (transitivo direto, sem preposicao)","C) Implicar A algo","D) Implicar DE algo","E) Implicar COM algo sempre"],g:"B",c:"'Implicar' no sentido de acarretar/resultar e TRANSITIVO DIRETO: 'A medida implica reducao' (sem 'em'). Com 'com' = antipatizar."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Em 'Bateram a porta' e 'Bateram-lhe a porta', os verbos sao, respectivamente:",o:["A) Ambos transitivos diretos","B) Transitivo indireto (a porta=bater A) e bitransitivo","C) Intransitivos","D) De ligacao","E) Ambos diretos"],g:"B",c:"'Bater a porta' (bater A porta) = transitivo indireto, com crase. 'Bater-lhe a porta' acrescenta objeto indireto (lhe). A regencia muda o sentido."},
{a:2023,r:"FCC/Fiscal-2023",q:"A frase com colocacao pronominal CORRETA e:",o:["A) Me diga a verdade","B) Diga-me a verdade","C) Nao diga-me nada","D) Que diga-me isso","E) Sempre diga-me"],g:"B",c:"Inicio de frase nao admite proclise: 'Diga-me' (enclise). Em 'Nao diga-me' o correto seria 'Nao me diga' (palavra negativa atrai o pronome - proclise)."},
{a:2022,r:"FCC/PGE-2022",q:"'Faz-se necessario rever os prazos' - a concordancia esta:",o:["A) Errada, deveria ser 'Fazem-se'","B) Correta: o sujeito e 'rever os prazos' (oracao), verbo no singular","C) Errada, falta crase","D) Errada, 'necessario' deveria ser plural","E) Errada, 'prazos' singular"],g:"B",c:"O sujeito e a oracao 'rever os prazos' (singular), logo 'Faz-se necessario' fica no singular. Cuidado: nao e 'os prazos' o sujeito."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Assinale a opcao em que NAO ha erro de paralelismo:",o:["A) Gosto de ler e de musica","B) Gosto de ler e de ouvir musica","C) Gosto de leitura e ouvir","D) Gosto ler e musica","E) Gosto de ler e musicas"],g:"B",c:"Paralelismo sintatico: 'de ler e de ouvir musica' (duas oracoes com infinitivo). As demais misturam substantivo e verbo, quebrando a simetria."},
{a:2023,r:"FCC/Fiscal-2023",q:"O verbo em 'Houve muitos problemas' deve ser:",o:["A) Houveram","B) Houve (haver no sentido de existir e impessoal)","C) Haviam","D) Hao","E) Havera de plural"],g:"B",c:"HAVER no sentido de EXISTIR e impessoal: fica sempre no SINGULAR. 'Houve muitos problemas' (nunca 'houveram')."},
{a:2022,r:"FCC/PGE-2022",q:"Em 'Cheguei a conclusao de que erramos', a regencia de 'chegar' exige:",o:["A) Objeto direto","B) Preposicao 'a' (chegar A algum lugar/conclusao)","C) Preposicao 'em'","D) Preposicao 'de'","E) Nenhuma preposicao"],g:"B",c:"'Chegar' (atingir) rege a preposicao A: cheguei A conclusao. Por isso ha crase antes de palavra feminina ('a conclusao')."},
],
"LP-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Na interpretacao textual, INFERIR significa:",o:["A) Repetir literalmente o texto.","B) Deduzir o que o texto permite concluir, mesmo nao explicito.","C) Resumir o primeiro paragrafo.","D) Listar palavras-chave.","E) Identificar erros gramaticais."],g:"B",c:"INFERENCIA=conclusao logica a partir do texto, mesmo sem estar literal. FCC cobra muito; cuidado com alternativas que exageram."},
{a:2022,r:"FCC/Fiscal-2022",q:"O conectivo 'ao passo que' indica:",o:["A) Causa","B) Consequencia","C) Concessao","D) Oposicao/contraste","E) Finalidade"],g:"D",c:"'Ao passo que'=oposicao/contraste (equivale a 'enquanto', 'ao contrario')."},
{a:2021,r:"FCC/TCE-2021",q:"Identifique o ERRO de ortografia:",o:["A) Exito no lancamento.","B) Credito constituido.","C) Parcelamento suspende.","D) Contribuicao de melhoria.","E) Imunidade prevista."],g:"A",c:"'Exito' correto e 'Êxito' (com acento - paroxitona terminada em ditongo? Na verdade proparoxitona: É-xi-to, sempre acentuada). As demais corretas."},
{a:2020,r:"FCC/Fiscal-2020",q:"A oracao 'que incide sobre mercadorias' em 'O ICMS, que incide sobre mercadorias, e estadual' e:",o:["A) Subordinada adjetiva restritiva","B) Subordinada adjetiva explicativa","C) Subordinada substantiva","D) Coordenada aditiva","E) Principal"],g:"B",c:"Entre virgulas=adjetiva EXPLICATIVA (informacao adicional). Sem virgulas seria restritiva."},
{a:2019,r:"FCC/Adm-2019",q:"A funcao da linguagem predominante em texto publicitario e:",o:["A) Referencial","B) Emotiva","C) Conativa/apelativa","D) Fatica","E) Metalinguistica"],g:"C",c:"CONATIVA/apelativa=foco no receptor, busca convencer/persuadir (publicidade). Referencial=informacao. Emotiva=emissor."},
{a:2023,r:"FCC/TRT-2023",q:"A pontuacao esta CORRETA em:",o:["A) Estudou; logo, passou.","B) Estudou logo passou.","C) Estudou, logo passou","D) Estudou: logo passou.","E) Estudou. Logo, passou"],g:"A",c:"Ponto e virgula separa oracoes coordenadas com conectivo conclusivo; virgula isola 'logo'."},
{a:2022,r:"FCC/TCE-2022",q:"O 'se' e particula apassivadora em:",o:["A) Se chove, fico em casa.","B) Vendem-se casas.","C) Trata-se de um erro.","D) Ele se feriu.","E) Nao se sabe a resposta."],g:"B",c:"'Vendem-se casas'=casas SAO VENDIDAS (voz passiva sintetica). Verbo concorda com sujeito 'casas' (plural)."},
{a:2021,r:"FCC/Fiscal-2021",q:"Em 'Choveu muito ontem', o sujeito e:",o:["A) Oculto (ele)","B) Indeterminado","C) Inexistente (oracao sem sujeito)","D) Simples (chuva)","E) Composto"],g:"C",c:"Verbo que indica fenomeno da natureza (chover)=impessoal=oracao SEM sujeito (sujeito inexistente)."},
{a:2020,r:"FCC/PGE-2020",q:"A coesao por SUBSTITUICAO ocorre em:",o:["A) O auditor chegou. Ele analisou tudo.","B) Comprou e vendeu.","C) Estudou, portanto passou.","D) Casa grande e bonita.","E) Veio mas nao falou."],g:"A",c:"'Ele' substitui 'o auditor'=coesao referencial por substituicao pronominal (anafora)."},
{a:2019,r:"FCC/TRF-2019",q:"Sinonimo de 'expurgar' no contexto juridico:",o:["A) ratificar","B) convalidar","C) anular/eliminar","D) homologar","E) confirmar"],g:"C",c:"EXPURGAR=eliminar, extirpar, ANULAR. Anulacao tem efeito ex tunc (retroativo)."},
{a:2023,r:"FCC/Adm-2023",q:"'Por que', 'porque', 'por que' e 'porque' - a forma para iniciar pergunta direta e:",o:["A) porque","B) porquê","C) por que","D) por quê","E) Por quê"],g:"C",c:"'Por que' (separado, sem acento) inicia perguntas: Por que voce faltou? 'Por quê' (com acento) no fim de frase. 'Porque'=resposta. 'Porquê'=substantivo."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No periodo 'Embora estudasse, nao passou', a oracao destacada exprime:",o:["A) Causa","B) Concessao","C) Condicao","D) Finalidade","E) Consequencia"],g:"B",c:"'Embora' introduz oracao subordinada adverbial CONCESSIVA (admite um fato contrario ao esperado)."},
{a:2023,r:"FCC/Fiscal-2023",q:"A funcao da linguagem centrada no proprio codigo e a:",o:["A) Emotiva","B) Metalinguistica","C) Fatica","D) Conativa","E) Referencial"],g:"B",c:"Funcao METALINGUISTICA: a linguagem fala dela mesma (ex: dicionario, gramatica explicando a lingua)."},
{a:2022,r:"FCC/PGE-2022",q:"'Ele nao apenas estudou, mas tambem trabalhou' - a relacao e de:",o:["A) Oposicao","B) Adicao (correlacao aditiva)","C) Alternancia","D) Conclusao","E) Causa"],g:"B",c:"'Nao apenas... mas tambem' = correlacao ADITIVA (soma ideias). Conjuncao coordenativa aditiva."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O uso dos dois-pontos em 'Trouxe tudo: livros, canetas e cadernos' indica:",o:["A) Citacao","B) Enumeracao/explicacao","C) Oposicao","D) Duvida","E) Pergunta"],g:"B",c:"Dois-pontos: anunciam uma ENUMERACAO, esclarecimento ou citacao. Aqui, enumeram os itens."},
{a:2023,r:"FCC/Fiscal-2023",q:"Em 'A reuniao foi adiada porque choveu', a oracao final exprime:",o:["A) Consequencia","B) Causa","C) Concessao","D) Condicao","E) Comparacao"],g:"B",c:"'Porque' (com verbo no indicativo) introduz oracao subordinada adverbial CAUSAL."},
{a:2022,r:"FCC/PGE-2022",q:"A coerencia textual relaciona-se a:",o:["A) Conexao gramatical entre palavras","B) Logica e sentido global do texto (nao contradicao)","C) Pontuacao","D) Ortografia","E) Acentuacao"],g:"B",c:"COERENCIA: nivel do SENTIDO (logica, ausencia de contradicao, continuidade tematica). COESAO: nivel da forma (conectivos, referencias)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"'Comprei o livro; ele, porem, nao chegou.' O 'porem' expressa:",o:["A) Adicao","B) Adversidade/oposicao","C) Conclusao","D) Causa","E) Explicacao"],g:"B",c:"'Porem' = conjuncao coordenativa ADVERSATIVA (oposicao), equivalente a mas, contudo, todavia."},
{a:2023,r:"FCC/Fiscal-2023",q:"A ambiguidade em 'O guarda deteve o suspeito em sua casa' decorre de:",o:["A) Erro ortografico","B) Duplo sentido do pronome 'sua' (do guarda ou do suspeito)","C) Falta de virgula","D) Concordancia","E) Regencia"],g:"B",c:"Ambiguidade pelo pronome possessivo 'sua': nao se sabe se a casa e do guarda ou do suspeito. Resolve-se reescrevendo (ex: 'na casa deste')."},
{a:2024,r:"FCC/SEFAZ-2024",q:"'Conquanto fosse rico, vivia modestamente' - 'conquanto' indica:",o:["A) Causa","B) Concessao","C) Tempo","D) Condicao","E) Finalidade"],g:"B",c:"'Conquanto' = conjuncao CONCESSIVA (equivale a embora, ainda que): admite fato contrario ao esperado."},
{a:2023,r:"FCC/Fiscal-2023",q:"A reescritura que mantem o sentido de 'A medida, embora polemica, foi aprovada' e:",o:["A) A medida foi aprovada porque era polemica","B) Apesar de polemica, a medida foi aprovada","C) A medida polemica nao foi aprovada","D) Como era polemica, foi aprovada","E) A medida foi polemica e aprovada por isso"],g:"B",c:"'Embora polemica' = concessao = 'apesar de polemica'. Mantem a ideia de contraste (foi aprovada a despeito da polemica)."},
{a:2022,r:"FCC/PGE-2022",q:"Os elementos coesivos 'por isso', 'portanto', 'logo' estabelecem relacao de:",o:["A) Causa","B) Conclusao/consequencia","C) Oposicao","D) Adicao","E) Tempo"],g:"B",c:"'Por isso, portanto, logo, assim' = conectivos CONCLUSIVOS (introduzem conclusao/consequencia do que foi dito)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A substituicao de 'os contribuintes que pagam em dia' por 'os contribuintes adimplentes' e um caso de:",o:["A) Ambiguidade","B) Economia linguistica por nominalizacao/sinonimia","C) Erro","D) Pleonasmo","E) Giria"],g:"B",c:"Trocar a oracao por um termo equivalente ('adimplentes') e recurso de COESAO/ECONOMIA por nominalizacao, mantendo o sentido com menos palavras."},
{a:2023,r:"FCC/Fiscal-2023",q:"Em texto dissertativo-argumentativo, a tese e:",o:["A) Um exemplo","B) A opiniao/ponto de vista central que sera defendido","C) A conclusao apenas","D) Um dado estatistico","E) A introducao do tema"],g:"B",c:"TESE: o ponto de vista central, a posicao do autor sobre o tema, que sera sustentada pelos argumentos ao longo do texto."},
{a:2022,r:"FCC/PGE-2022",q:"'O auditor analisou o processo; este, porem, estava incompleto' - 'este' retoma:",o:["A) O auditor","B) O processo (referencia anaforica)","C) Nada","D) A analise","E) O incompleto"],g:"B",c:"'Este' retoma o termo mais proximo: o PROCESSO (referencia anaforica). Coesao referencial por pronome demonstrativo."},
],
"MAT-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Capital de R$15.000 a juros compostos de 2% a.m. por 3 meses (1,02^3=1,0612). O montante e:",o:["A) R$15.900","B) R$15.918","C) R$15.936","D) R$15.612","E) R$16.000"],g:"B",c:"M=C(1+i)^n=15.000x1,0612=15.918. Juros compostos=918. Juros simples seria 900 (15.900)."},
{a:2022,r:"FCC/Fiscal-2022",q:"Financiamento de R$60.000 em 3 parcelas pelo SAC, taxa 10% a.p. A 2a prestacao e:",o:["A) R$26.000","B) R$24.000","C) R$22.000","D) R$20.000","E) R$18.000"],g:"B",c:"SAC: amortizacao=60.000/3=20.000. 2a: SD=40.000, J=4.000, prestacao=20.000+4.000=24.000."},
{a:2021,r:"FCC/TCE-2021",q:"Aplicacao de R$8.000 a juros simples de 1,5% a.m. por 8 meses rende:",o:["A) R$960","B) R$1.000","C) R$1.200","D) R$640","E) R$800"],g:"A",c:"J=Cxixn=8.000x0,015x8=960."},
{a:2020,r:"FCC/ISS-2020",q:"No sistema PRICE, as prestacoes sao:",o:["A) Decrescentes","B) Crescentes","C) Constantes","D) Variaveis aleatoriamente","E) Iguais a amortizacao"],g:"C",c:"PRICE (frances): prestacoes CONSTANTES, juros decrescentes, amortizacao crescente. SAC tem prestacoes decrescentes."},
{a:2019,r:"FCC/Adm-2019",q:"A taxa REAL, dada inflacao de 5% e taxa nominal de 12%, e aproximadamente:",o:["A) 7,0%","B) 6,67%","C) 17,6%","D) 5,0%","E) 12,0%"],g:"B",c:"(1+0,12)=(1+real)(1+0,05) -> 1,12/1,05=1,0667 -> real=6,67%. Nao e simples subtracao (7%)."},
{a:2023,r:"FCC/TRT-2023",q:"O desconto COMERCIAL (por fora) e calculado sobre:",o:["A) O valor atual","B) O valor nominal (de face)","C) A media dos valores","D) O valor presente liquido","E) A taxa interna de retorno"],g:"B",c:"Desconto COMERCIAL incide sobre o valor NOMINAL (maior desconto). RACIONAL incide sobre o valor atual."},
{a:2022,r:"FCC/TCE-2022",q:"Capital que dobra a juros compostos de 100% ao periodo leva:",o:["A) 1 periodo","B) 2 periodos","C) 0,5 periodo","D) 4 periodos","E) Depende do capital"],g:"A",c:"M=C(1+1)^n=2C -> (2)^n=2 -> n=1. A 100%, dobra em 1 periodo."},
{a:2021,r:"FCC/Fiscal-2021",q:"No SAC, a parcela de JUROS ao longo do tempo e:",o:["A) Crescente","B) Constante","C) Decrescente","D) Igual a amortizacao","E) Zero"],g:"C",c:"SAC: juros DECRESCENTES (incidem sobre saldo devedor que diminui). Amortizacao constante."},
{a:2020,r:"FCC/PGE-2020",q:"Valor presente de R$11.000 a receber em 1 ano, taxa 10% a.a.:",o:["A) R$10.000","B) R$9.900","C) R$11.000","D) R$10.100","E) R$9.000"],g:"A",c:"VP=VF/(1+i)=11.000/1,10=10.000."},
{a:2019,r:"FCC/TRF-2019",q:"Taxas EQUIVALENTES, em juros compostos, produzem:",o:["A) Sempre o mesmo valor nominal","B) O mesmo montante em prazos diferentes para o mesmo capital","C) Valores proporcionais ao tempo","D) Juros simples","E) Rendimento linear"],g:"B",c:"Taxas EQUIVALENTES (compostos): geram o mesmo montante final em prazos distintos. Diferente de proporcionais (simples)."},
{a:2023,r:"FCC/Adm-2023",q:"Montante de R$5.000 a 1% a.m. por 2 meses (juros compostos):",o:["A) R$5.100","B) R$5.100,50","C) R$5.100,00","D) R$5.100,50 (1,0201)","E) R$5.200"],g:"D",c:"M=5.000x(1,01)^2=5.000x1,0201=5.100,50. Composto rende mais que simples (5.100)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Um capital cresce 21% em juros compostos em 2 periodos. A taxa por periodo e:",o:["A) 10%","B) 10,5%","C) 21%","D) 11%","E) 9%"],g:"A",c:"(1+i)^2=1,21 -> 1+i=1,1 -> i=10% ao periodo."},
{a:2023,r:"FCC/Fiscal-2023",q:"No desconto racional simples, o valor do desconto incide sobre:",o:["A) O valor nominal","B) O valor atual (valor presente)","C) A media","D) O montante","E) O valor de face"],g:"B",c:"Desconto RACIONAL (por dentro) = i x VP x n, calculado sobre o valor ATUAL. O comercial (por fora) incide sobre o valor nominal."},
{a:2022,r:"FCC/PGE-2022",q:"Uma taxa de 12% a.a. capitalizada mensalmente tem taxa efetiva:",o:["A) 12% a.a.","B) Maior que 12% a.a. (juros sobre juros mensais)","C) Menor que 12%","D) 1% efetivo ao ano","E) Igual a nominal"],g:"B",c:"Taxa NOMINAL 12% a.a. (1% a.m.) capitalizada mensalmente gera taxa EFETIVA = (1,01)^12 - 1 = 12,68% a.a., MAIOR que a nominal."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No SAC, sendo PV=120.000 e n=4, a amortizacao periodica e:",o:["A) 40.000","B) 30.000","C) 24.000","D) 60.000","E) 12.000"],g:"B",c:"SAC: amortizacao constante = PV/n = 120.000/4 = 30.000 por periodo."},
{a:2023,r:"FCC/Fiscal-2023",q:"A TIR (Taxa Interna de Retorno) e a taxa que torna o VPL igual a:",o:["A) 1","B) Zero","C) O investimento","D) O lucro","E) A receita"],g:"B",c:"TIR: taxa de desconto que torna o Valor Presente Liquido (VPL) igual a ZERO. Projeto viavel se TIR > custo de capital."},
{a:2022,r:"FCC/PGE-2022",q:"Em juros simples, dobrar o prazo (mantendo taxa e capital):",o:["A) Dobra os juros","B) Quadruplica","C) Triplica","D) Reduz pela metade","E) Nao altera"],g:"A",c:"Juros simples: J = C.i.n e LINEAR no tempo. Dobrar n dobra os juros."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Aplicando R$10.000 a 10% a.a. por 3 anos compostos (1,1^3=1,331), o juro e:",o:["A) R$3.000","B) R$3.310","C) R$1.331","D) R$13.310","E) R$3.300"],g:"B",c:"M=10.000 x 1,331=13.310. Juros=M-C=13.310-10.000=3.310."},
{a:2023,r:"FCC/Fiscal-2023",q:"No sistema PRICE, a parcela de amortizacao ao longo do tempo:",o:["A) E constante","B) E crescente","C) E decrescente","D) E zero","E) Iguala os juros"],g:"B",c:"PRICE: prestacao constante; os juros decrescem e a AMORTIZACAO CRESCE ao longo do tempo (inverso da composicao do SAC)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Aplicacao de R$2.000 a juros simples gerou R$2.480 em 12 meses. A taxa mensal foi:",o:["A) 1%","B) 2%","C) 1,5%","D) 2,5%","E) 3%"],g:"B",c:"J=2.480-2.000=480. i=J/(C.n)=480/(2.000x12)=0,02=2% a.m."},
{a:2023,r:"FCC/Fiscal-2023",q:"No fluxo de caixa, um valor presente positivo (VPL>0) indica que o projeto:",o:["A) Deve ser rejeitado","B) Gera retorno acima do custo de capital (viavel)","C) E indiferente","D) Tem TIR zero","E) Da prejuizo"],g:"B",c:"VPL > 0: o projeto remunera o capital acima da taxa minima exigida, agregando valor - deve ser ACEITO."},
{a:2022,r:"FCC/PGE-2022",q:"Duas taxas sao PROPORCIONAIS quando, em juros simples:",o:["A) Geram o mesmo montante composto","B) Mantem a razao com o tempo (ex: 12% a.a. = 1% a.m.)","C) Sao iguais","D) Dobram a cada periodo","E) Sao equivalentes compostas"],g:"B",c:"Taxas PROPORCIONAIS (juros simples): variam linearmente com o tempo (24% a.a. = 2% a.m.). EQUIVALENTES (compostos) geram o mesmo montante."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No SAC, a prestacao da 1a parcela de um financiamento de 100.000 em 5 anos a 10% a.a. e:",o:["A) 20.000","B) 30.000","C) 25.000","D) 10.000","E) 22.000"],g:"B",c:"SAC: amortizacao=100.000/5=20.000. Juros 1a parcela=100.000x10%=10.000. Prestacao=20.000+10.000=30.000."},
{a:2023,r:"FCC/Fiscal-2023",q:"O desconto comercial simples de um titulo de R$10.000, taxa 3% a.m. por 2 meses, e:",o:["A) R$300","B) R$600","C) R$580","D) R$200","E) R$612"],g:"B",c:"Desconto comercial=N.i.n=10.000x0,03x2=600 (incide sobre o valor nominal)."},
{a:2022,r:"FCC/PGE-2022",q:"No sistema PRICE, a soma das amortizacoes ao final iguala:",o:["A) O total de juros","B) O valor financiado (principal)","C) A prestacao","D) O montante","E) Zero"],g:"B",c:"Em qualquer sistema (PRICE ou SAC), a soma das AMORTIZACOES ao longo do tempo iguala o PRINCIPAL financiado (o saldo devedor zera no fim)."},
],
"MAT-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Dados 5,8,3,12,8,15,8 - a MEDIANA e a MODA sao:",o:["A) 8 e 8","B) 8 e 5","C) 8,43 e 8","D) 12 e 8","E) 8 e 12"],g:"A",c:"Ordenando: 3,5,8,8,8,12,15. N=7 impar -> mediana=4o elemento=8. Moda=8 (3 vezes). Media=8,43."},
{a:2022,r:"FCC/Fiscal-2022",q:"P->Q verdadeira e Q falsa. Pelo Modus Tollens conclui-se:",o:["A) P verdadeira","B) P falsa (nao-P)","C) Q verdadeira","D) Indeterminado","E) P e Q verdadeiras"],g:"B",c:"MODUS TOLLENS: P->Q, nao-Q, logo nao-P. Se Q e falsa, P e falsa."},
{a:2021,r:"FCC/TCE-2021",q:"Negacao de 'Todo auditor conhece o CTN':",o:["A) Nenhum auditor conhece o CTN","B) Algum auditor nao conhece o CTN","C) Todo auditor desconhece o CTN","D) Alguns conhecem","E) Nenhum desconhece"],g:"B",c:"Negacao de 'todo A e B' = 'algum A nao e B' (existe ao menos um que nao)."},
{a:2020,r:"FCC/ISS-2020",q:"P->Q e Q->R verdadeiras. Conclui-se necessariamente:",o:["A) R->P","B) P->R","C) nao-P","D) Q->P","E) R e P"],g:"B",c:"SILOGISMO HIPOTETICO (transitividade): P->Q, Q->R, logo P->R."},
{a:2019,r:"FCC/Adm-2019",q:"Desvio-padrao mede:",o:["A) O valor central","B) A dispersao dos dados em torno da media","C) O valor mais frequente","D) A amplitude total","E) A assimetria"],g:"B",c:"Desvio-padrao=dispersao em torno da media (raiz da variancia). Mediana=central; moda=frequente."},
{a:2023,r:"FCC/TRT-2023",q:"Probabilidade de, em 2 lancamentos de moeda, sair 2 caras:",o:["A) 1/2","B) 1/4","C) 1/3","D) 3/4","E) 1"],g:"B",c:"Eventos independentes: P=1/2 x 1/2=1/4."},
{a:2022,r:"FCC/TCE-2022",q:"Negacao de 'P e Q' (De Morgan):",o:["A) nao-P e nao-Q","B) nao-P ou nao-Q","C) P ou Q","D) nao-P -> Q","E) P e nao-Q"],g:"B",c:"De Morgan: nao(P e Q) = nao-P OU nao-Q."},
{a:2021,r:"FCC/Fiscal-2021",q:"Numero de comissoes de 3 pessoas escolhidas entre 5:",o:["A) 60","B) 10","C) 15","D) 125","E) 20"],g:"B",c:"Combinacao C(5,3)=5!/(3!2!)=10. Ordem nao importa em comissao."},
{a:2020,r:"FCC/PGE-2020",q:"Media de 10,20,30,40,50:",o:["A) 25","B) 30","C) 35","D) 20","E) 40"],g:"B",c:"Media=(10+20+30+40+50)/5=150/5=30."},
{a:2019,r:"FCC/TRF-2019",q:"A contrapositiva de 'Se chove, entao a rua molha' e:",o:["A) Se a rua molha, entao chove","B) Se nao molha a rua, entao nao chove","C) Se nao chove, nao molha","D) A rua molha e chove","E) Chove ou molha"],g:"B",c:"Contrapositiva de P->Q e nao-Q -> nao-P: 'Se a rua nao molha, entao nao chove' (equivalente a original)."},
{a:2023,r:"FCC/Adm-2023",q:"Coeficiente de variacao serve para:",o:["A) Calcular a media","B) Comparar a dispersao relativa entre conjuntos","C) Achar a moda","D) Medir probabilidade","E) Ordenar dados"],g:"B",c:"CV=desvio-padrao/media. Mede dispersao RELATIVA, util para comparar conjuntos de escalas diferentes."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Em 'Se chove entao a rua molha', sabendo que a rua NAO molhou, conclui-se:",o:["A) Choveu","B) Nao choveu (Modus Tollens)","C) Pode ter chovido","D) Indeterminado","E) A rua molhou"],g:"B",c:"Modus Tollens: P->Q, ~Q, logo ~P. Se a rua nao molhou, entao nao choveu."},
{a:2023,r:"FCC/Fiscal-2023",q:"O desvio-padrao de um conjunto em que todos os valores sao iguais e:",o:["A) A media","B) Zero","C) 1","D) Negativo","E) A soma"],g:"B",c:"Se todos os valores sao iguais, nao ha dispersao: variancia e desvio-padrao = ZERO."},
{a:2022,r:"FCC/PGE-2022",q:"A negacao de 'Joao estuda E trabalha' e:",o:["A) Joao nao estuda e nao trabalha","B) Joao nao estuda ou nao trabalha","C) Joao estuda ou trabalha","D) Joao nao estuda","E) Joao trabalha"],g:"B",c:"De Morgan: ~(P e Q) = ~P ou ~Q. 'Joao nao estuda OU nao trabalha'."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Lancando um dado, a probabilidade de sair numero par e:",o:["A) 1/6","B) 1/2","C) 1/3","D) 2/3","E) 1/4"],g:"B",c:"Pares: 2,4,6 (3 casos) em 6 possiveis = 3/6 = 1/2."},
{a:2023,r:"FCC/Fiscal-2023",q:"A mediana de 4,8,6,10,2 e:",o:["A) 6","B) 8","C) 4","D) 10","E) 5"],g:"A",c:"Ordenando: 2,4,6,8,10. N=5 (impar), mediana = elemento central = 6."},
{a:2022,r:"FCC/PGE-2022",q:"Quantos anagramas tem a palavra 'AMOR'?",o:["A) 4","B) 12","C) 24","D) 16","E) 8"],g:"C",c:"4 letras distintas: permutacoes = 4! = 24."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Se P->Q e verdadeira e P e verdadeira, entao (Modus Ponens):",o:["A) Q e falsa","B) Q e verdadeira","C) Indeterminado","D) ~P","E) ~Q"],g:"B",c:"Modus Ponens: P->Q, P, logo Q. Q e verdadeira."},
{a:2023,r:"FCC/Fiscal-2023",q:"A media de 2,4,6,8,10 e o desvio em relacao a ela do valor 10 e:",o:["A) media 6, desvio 4","B) media 5, desvio 5","C) media 6, desvio 6","D) media 7, desvio 3","E) media 6, desvio 0"],g:"A",c:"Media=(2+4+6+8+10)/5=30/5=6. Desvio de 10 = 10-6 = 4."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A probabilidade de tirar uma carta de copas de um baralho de 52 cartas e:",o:["A) 1/4","B) 1/13","C) 1/52","D) 4/52","E) 1/2"],g:"A",c:"13 cartas de copas em 52 = 13/52 = 1/4."},
{a:2023,r:"FCC/Fiscal-2023",q:"Em uma distribuicao simetrica, media, mediana e moda:",o:["A) Sao diferentes","B) Coincidem (sao iguais)","C) A media e maior","D) A moda e maior","E) Nao existem"],g:"B",c:"Em distribuicao perfeitamente SIMETRICA, media = mediana = moda (coincidem no centro)."},
{a:2022,r:"FCC/PGE-2022",q:"A negacao de 'Todos os auditores sao eficientes' e:",o:["A) Nenhum auditor e eficiente","B) Pelo menos um auditor nao e eficiente","C) Todos sao ineficientes","D) Alguns sao eficientes","E) Nenhum e ineficiente"],g:"B",c:"Negacao de 'todo A e B' = 'existe (pelo menos um) A que nao e B'. 'Pelo menos um auditor nao e eficiente'."},
{a:2024,r:"FCC/SEFAZ-2024",q:"De quantas formas 3 pessoas podem sentar em 3 cadeiras enfileiradas?",o:["A) 3","B) 6","C) 9","D) 27","E) 12"],g:"B",c:"Permutacao de 3 = 3! = 6 formas (a ordem importa)."},
{a:2023,r:"FCC/Fiscal-2023",q:"Se P e V (verdadeira) e Q e F (falsa), o valor logico de 'P -> Q' e:",o:["A) Verdadeiro","B) Falso","C) Indeterminado","D) Nulo","E) Tautologia"],g:"B",c:"A condicional P->Q so e FALSA quando o antecedente e V e o consequente e F. P=V e Q=F -> P->Q = FALSO."},
{a:2022,r:"FCC/PGE-2022",q:"O coeficiente de variacao serve para comparar a dispersao de conjuntos com:",o:["A) Mesma media","B) Medias e/ou unidades diferentes (dispersao relativa)","C) Mesma unidade so","D) Mesmo desvio","E) Mesmos dados"],g:"B",c:"CV = desvio-padrao/media (geralmente em %). Permite comparar a dispersao RELATIVA entre conjuntos com medias ou unidades diferentes."},
],
"ADM-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"No Modelo das 3 Linhas (IIA 2020), a 3a linha corresponde a:",o:["A) Gestao operacional","B) Compliance e gestao de riscos","C) Auditoria interna (asseguracao independente)","D) Controle externo (TCU)","E) Alta administracao"],g:"C",c:"3a LINHA=AUDITORIA INTERNA (asseguracao independente). 1a=gestao operacional; 2a=compliance/riscos."},
{a:2022,r:"FCC/TCE-2022",q:"A Lei 14.230/2021 exige, para improbidade, elemento subjetivo de:",o:["A) Culpa grave","B) Dolo especifico","C) Culpa simples","D) Apenas dano ao erario","E) Dolo generico"],g:"B",c:"Lei 14.230/2021: DOLO ESPECIFICO imprescindivel. Culpa nao configura mais improbidade."},
{a:2021,r:"FCC/PGE-2021",q:"Na LAI (Lei 12.527/2011), o prazo de resposta e:",o:["A) 10 dias","B) 15 dias uteis","C) 20 dias, prorrogavel por mais 10","D) 30 dias","E) 5 dias"],g:"C",c:"LAI art. 11: 20 dias + prorrogacao de 10 (com justificativa). Sigilo: reservado 5, secreto 15, ultra-secreto 25 anos."},
{a:2020,r:"FCC/Adm-2020",q:"A gestao de riscos (ISO 31000) tem como etapas:",o:["A) Planejar, executar, verificar, agir","B) Identificar, analisar, avaliar, tratar e monitorar","C) Prever, empenhar, liquidar, pagar","D) Apenas evitar riscos","E) Transferir todos os riscos"],g:"B",c:"ISO 31000: identificar->analisar->avaliar->tratar->monitorar. Tratamento: evitar, reduzir, transferir, aceitar."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O apetite ao risco refere-se a:",o:["A) Eliminacao total dos riscos","B) Nivel de risco que a organizacao aceita assumir","C) Transferencia obrigatoria de riscos","D) Riscos operacionais apenas","E) Auditoria externa"],g:"B",c:"Apetite ao risco=nivel de risco que a organizacao esta disposta a aceitar para atingir objetivos."},
{a:2023,r:"FCC/TRT-2023",q:"Accountability significa:",o:["A) Apenas contabilidade publica","B) Responsabilizacao e prestacao de contas","C) Auditoria externa","D) Transparencia passiva","E) Gestao de pessoal"],g:"B",c:"Accountability=responsabilizacao + dever de prestar contas. Pilar da governanca publica."},
{a:2022,r:"FCC/TCE-2022",q:"Na governanca publica, a teoria da agencia trata da relacao entre:",o:["A) Estados e municipios","B) Principal (sociedade) e agente (gestor)","C) Auditor e auditado","D) Legislativo e Judiciario","E) Servidor e cidadao"],g:"B",c:"Teoria da agencia: conflito entre PRINCIPAL (sociedade/povo) e AGENTE (gestor publico), com assimetria de informacao."},
{a:2021,r:"FCC/PGE-2021",q:"A transparencia ATIVA na LAI consiste em:",o:["A) Responder a pedidos de informacao","B) Divulgar informacoes por iniciativa propria","C) Manter sigilo de documentos","D) Cobrar pelo acesso","E) Negar acesso a terceiros"],g:"B",c:"Transparencia ATIVA=divulgacao proativa (por iniciativa do orgao). PASSIVA=resposta a pedidos."},
{a:2020,r:"FCC/Adm-2020",q:"Na 2a linha do Modelo das 3 Linhas estao funcoes de:",o:["A) Auditoria interna","B) Gestao operacional","C) Compliance, controles e gestao de riscos","D) Controle externo","E) Conselho de administracao"],g:"C",c:"2a LINHA=funcoes de suporte: compliance, gestao de riscos, controles internos (apoiam a 1a linha)."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O assedio moral no trabalho e tratado pela:",o:["A) Lei de Licitacoes","B) Convencao OIT 190/2019","C) LAI","D) LRF","E) Lei Anticorrupcao"],g:"B",c:"Convencao OIT 190/2019 trata de violencia e assedio no mundo do trabalho."},
{a:2023,r:"FCC/TCE-2023",q:"Integridade publica, no contexto de governanca, refere-se a:",o:["A) Apenas seguranca da informacao","B) Alinhamento consistente com valores e principios eticos para prevenir corrupcao","C) Auditoria de sistemas","D) Controle de estoque","E) Gestao orcamentaria"],g:"B",c:"Integridade=alinhamento consistente e adesao a valores, principios e normas eticas para prevenir e combater a corrupcao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No COSO ERM, o ambiente interno/governanca e a base porque:",o:["A) Define o lucro","B) Estabelece o tom da organizacao e a cultura de gestao de riscos","C) Calcula riscos","D) Audita contas","E) Elabora o orcamento"],g:"B",c:"COSO ERM: a governanca e cultura ('tone at the top') sustentam todo o gerenciamento de riscos; sem cultura de risco, os controles falham."},
{a:2023,r:"FCC/TCE-2023",q:"Risco INERENTE difere de risco RESIDUAL porque o residual e:",o:["A) O risco antes dos controles","B) O risco que permanece apos a aplicacao dos controles/respostas","C) Sempre zero","D) O risco maximo","E) Igual ao inerente"],g:"B",c:"Risco INERENTE: antes de qualquer tratamento. Risco RESIDUAL: o que sobra apos as respostas/controles. O apetite a risco baliza o residual aceitavel."},
{a:2022,r:"FCC/PGE-2022",q:"Na LAI, a classificacao 'reservada' tem prazo maximo de sigilo de:",o:["A) 5 anos","B) 15 anos","C) 25 anos","D) 10 anos","E) 3 anos"],g:"A",c:"LAI: reservada = ate 5 anos; secreta = ate 15 anos; ultrassecreta = ate 25 anos (prorrogavel uma vez)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Compliance, no setor publico, refere-se a:",o:["A) Auditoria externa","B) Conformidade com leis, normas e politicas, prevenindo desvios","C) Planejamento orcamentario","D) Gestao de pessoal","E) Controle de estoque"],g:"B",c:"Compliance = estar em conformidade com o arcabouço normativo (leis, regulamentos, politicas internas), integrando o programa de integridade."},
{a:2023,r:"FCC/TCE-2023",q:"A matriz de risco (probabilidade x impacto) serve para:",o:["A) Eliminar riscos","B) Priorizar riscos conforme severidade","C) Calcular o orcamento","D) Auditar contas","E) Definir o lucro"],g:"B",c:"A matriz probabilidade x impacto classifica e PRIORIZA os riscos (baixo/medio/alto/critico), orientando onde concentrar as respostas."},
{a:2022,r:"FCC/PGE-2022",q:"Os tres niveis de governanca publica (TCU) sao:",o:["A) Federal, estadual, municipal","B) Estrategico, tatico e operacional","C) Politico, tecnico e administrativo","D) Interno, externo e social","E) Legislativo, executivo, judiciario"],g:"B",c:"A governanca atua em niveis: ESTRATEGICO (direcao), TATICO (traducao em planos) e OPERACIONAL (execucao), conforme o referencial do TCU."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A resposta ao risco 'compartilhar' significa:",o:["A) Aceitar o risco","B) Transferir parte do risco a terceiros (ex: seguro, terceirizacao)","C) Eliminar a atividade","D) Reduzir a probabilidade","E) Ignorar"],g:"B",c:"Respostas ao risco: evitar, reduzir/mitigar, COMPARTILHAR/transferir (seguro, terceirizacao) e aceitar."},
{a:2023,r:"FCC/TCE-2023",q:"A integridade publica e fortalecida por mecanismos como:",o:["A) Sigilo absoluto","B) Codigo de etica, canais de denuncia e gestao de conflitos de interesse","C) Centralizacao do poder","D) Ausencia de controles","E) Discricionariedade ilimitada"],g:"B",c:"Pilares da integridade: codigo de etica/conduta, canais de denuncia (ouvidoria), gestao de conflito de interesses, controles e responsabilizacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No modelo das 3 linhas (IIA 2020), o orgao de governanca:",o:["A) Executa operacoes","B) Presta contas as partes interessadas e supervisiona a gestao","C) Faz auditoria interna","D) Gere riscos operacionais","E) Elabora demonstracoes"],g:"B",c:"No modelo das 3 linhas, o ORGAO DE GOVERNANCA (conselho/alta administracao) responde as partes interessadas e supervisiona; a gestao (1a/2a linhas) executa e a auditoria interna (3a) assegura."},
{a:2023,r:"FCC/TCE-2023",q:"A diferenca entre eficiencia, eficacia e efetividade: efetividade refere-se a:",o:["A) Usar bem os recursos","B) Atingir as metas","C) Impacto/transformacao real gerada para a sociedade","D) Velocidade","E) Custo"],g:"C",c:"EFICIENCIA: usar bem os recursos (meios). EFICACIA: atingir as metas (resultados). EFETIVIDADE: impacto/transformacao real e duradoura na sociedade (efeitos)."},
{a:2022,r:"FCC/PGE-2022",q:"O conflito de interesses no servico publico ocorre quando:",o:["A) Ha duas tarefas","B) Interesse privado pode influenciar o desempenho da funcao publica","C) Ha trabalho em equipe","D) O servidor estuda","E) Ha meta a cumprir"],g:"B",c:"CONFLITO DE INTERESSES (Lei 12.813/2013): situacao em que interesses PRIVADOS podem comprometer o interesse coletivo ou influenciar o desempenho da funcao publica."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A primeira linha, no modelo das 3 linhas, e responsavel por:",o:["A) Auditoria","B) Gerir os riscos no dia a dia (donos dos processos e controles operacionais)","C) Supervisao do conselho","D) Asseguracao independente","E) Compliance"],g:"B",c:"1a LINHA: gestores operacionais, donos dos riscos e controles no dia a dia (executam e gerenciam os riscos diretamente)."},
{a:2023,r:"FCC/TCE-2023",q:"A gestao por competencias visa:",o:["A) Reduzir salarios","B) Alinhar conhecimentos, habilidades e atitudes das pessoas aos objetivos organizacionais","C) Eliminar cargos","D) Centralizar decisoes","E) Terceirizar tudo"],g:"B",c:"Gestao por COMPETENCIAS: gerir pessoas com base em CHA (Conhecimentos, Habilidades, Atitudes), alinhando-as as estrategias e objetivos da organizacao."},
{a:2022,r:"FCC/PGE-2022",q:"A LAI estabelece como diretriz a observancia da publicidade como:",o:["A) Excecao","B) Preceito geral e o sigilo como excecao","C) Regra absoluta","D) Opcao do gestor","E) Vedacao"],g:"B",c:"LAI (art. 3): a publicidade e o PRECEITO GERAL e o SIGILO a EXCECAO. Acesso a informacao e a regra; restricoes devem ser justificadas e temporarias."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O ciclo PDCA aplicado a gestao publica significa:",o:["A) Planejar, Dirigir, Controlar, Avaliar","B) Plan (planejar), Do (executar), Check (verificar), Act (agir corretivamente)","C) Prever, Decidir, Cobrar, Ajustar","D) Produzir, Distribuir","E) Politica, Diretriz"],g:"B",c:"PDCA: PLAN (planejar), DO (executar), CHECK (verificar resultados), ACT (agir para corrigir/padronizar) - ciclo de melhoria continua."},
{a:2023,r:"FCC/TCE-2023",q:"A maturidade em gestao de riscos de uma organizacao indica:",o:["A) O lucro","B) O grau de estruturacao e institucionalizacao das praticas de gestao de riscos","C) O numero de servidores","D) O orcamento","E) A idade da organizacao"],g:"B",c:"Maturidade em gestao de riscos: nivel de desenvolvimento, estruturacao e cultura das praticas de gerenciamento de riscos (de inicial/ad hoc a otimizado)."},
{a:2022,r:"FCC/PGE-2022",q:"O planejamento estrategico difere do operacional por ser:",o:["A) De curto prazo","B) De longo prazo e abrangencia global da organizacao","C) Detalhado por tarefa","D) Diario","E) Setorial apenas"],g:"B",c:"Planejamento ESTRATEGICO: longo prazo, visao global, alta administracao. TATICO: medio prazo, por area. OPERACIONAL: curto prazo, tarefas especificas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Accountability vertical refere-se a:",o:["A) Controle entre poderes","B) Prestacao de contas aos cidadaos/eleitores (ex: eleicoes, controle social)","C) Auditoria interna","D) Hierarquia administrativa","E) Controle do TCU"],g:"B",c:"Accountability VERTICAL: responsabilizacao perante os cidadaos (voto, controle social, participacao). HORIZONTAL: fiscalizacao entre orgaos/poderes (TCU, MP, freios e contrapesos)."},
],
"ADM-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"A modalidade DIALOGO COMPETITIVO (Lei 14.133/2021) aplica-se quando:",o:["A) O valor supera o limite do pregao","B) Ha 5 fornecedores cadastrados","C) Necessita-se de inovacao ou solucao inexistente no mercado","D) O objeto e intelectual","E) A licitacao e eletronica"],g:"C",c:"Art. 32: dialogo competitivo para inovacao tecnologica ou solucao inexistente no mercado. A Adm. dialoga com licitantes antes de definir o objeto."},
{a:2022,r:"FCC/TCE-2022",q:"Na Lei 14.133/2021, o criterio de julgamento por MENOR PRECO e tipico de:",o:["A) Concurso","B) Pregao (bens e servicos comuns)","C) Leilao","D) Dialogo competitivo","E) Concorrencia para obras especiais"],g:"B",c:"PREGAO: bens e servicos comuns, criterio menor preco ou maior desconto."},
{a:2021,r:"FCC/PGE-2021",q:"A improbidade que importa enriquecimento ilicito (Lei 8.429/92):",o:["A) Dispensa dolo","B) Exige dolo especifico apos a Lei 14.230/2021","C) Admite culpa","D) E imprescritivel","E) So atinge particulares"],g:"B",c:"Apos Lei 14.230/2021, TODAS as modalidades de improbidade exigem DOLO ESPECIFICO, inclusive enriquecimento ilicito."},
{a:2020,r:"FCC/Adm-2020",q:"A INEXIGIBILIDADE de licitacao ocorre quando:",o:["A) O valor e baixo","B) Ha inviabilidade de competicao","C) Ha emergencia","D) E guerra","E) Ha calamidade"],g:"B",c:"INEXIGIBILIDADE (art. 74): inviabilidade de competicao (fornecedor exclusivo, artista consagrado). DISPENSA: competicao viavel mas a lei dispensa."},
{a:2019,r:"FCC/SEFAZ-2019",q:"Os principios da Adm. Publica no art. 37 CF sao (LIMPE):",o:["A) Legalidade, razoabilidade, moralidade, publicidade, eficiencia","B) Legalidade, impessoalidade, moralidade, publicidade, eficiencia","C) Legitimidade, economicidade, moralidade, publicidade, eficiencia","D) Supremacia, indisponibilidade, moralidade, publicidade","E) Legalidade, proporcionalidade, moralidade, publicidade"],g:"B",c:"LIMPE: Legalidade, Impessoalidade, Moralidade, Publicidade, Eficiencia (EC 19/98)."},
{a:2023,r:"FCC/TRT-2023",q:"A prescricao na improbidade (Lei 14.230/2021) e de:",o:["A) 5 anos","B) 8 anos do fato ou 4 anos apos fim do vinculo","C) 10 anos","D) 3 anos","E) Imprescritivel"],g:"B",c:"Lei 14.230/2021: prescricao de 8 anos do fato; ou 4 anos apos o fim do vinculo (prescricao intercorrente)."},
{a:2022,r:"FCC/TCE-2022",q:"Na Lei 14.133/2021, a fase de habilitacao ocorre:",o:["A) Antes do julgamento das propostas","B) Apos o julgamento das propostas (regra geral)","C) Antes do edital","D) Apos a homologacao","E) Junto com a fase recursal apenas"],g:"B",c:"Lei 14.133: regra geral inverte fases - habilitacao APOS julgamento das propostas (como no pregao)."},
{a:2021,r:"FCC/PGE-2021",q:"A legitimidade para propor acao de improbidade e:",o:["A) Concorrente entre MP e pessoa juridica lesada","B) Exclusiva do MP (Lei 14.230/2021)","C) De qualquer cidadao","D) Do Tribunal de Contas","E) Da Defensoria Publica"],g:"B",c:"Lei 14.230/2021: legitimidade EXCLUSIVA do Ministerio Publico (extinguiu a legitimidade da pessoa juridica)."},
{a:2020,r:"FCC/Adm-2020",q:"A Lei Anticorrupcao (12.846/2013) responsabiliza pessoas juridicas de forma:",o:["A) Subjetiva","B) Objetiva","C) Solidaria apenas","D) Penal","E) Apenas civil mediante culpa"],g:"B",c:"Lei 12.846/2013: responsabilidade OBJETIVA (independe de dolo/culpa) das pessoas juridicas por atos lesivos a Adm. nacional ou estrangeira."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O LEILAO, na Lei 14.133/2021, destina-se a:",o:["A) Servicos comuns","B) Trabalho tecnico","C) Alienacao de bens (maior lance)","D) Inovacao tecnologica","E) Obras de engenharia"],g:"C",c:"LEILAO: alienacao de bens moveis/imoveis inserviveis ou legalmente apreendidos, criterio maior lance."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na Lei 14.133/2021, o orcamento estimado pode ser sigiloso ate:",o:["A) O fim do contrato","B) A conclusao da licitacao (orcamento sigiloso facultativo)","C) Sempre publico","D) 5 anos","E) A homologacao mais 1 ano"],g:"B",c:"Lei 14.133: o orcamento estimado pode ser SIGILOSO (criterio da Adm.), tornando-se publico apos a fase de propostas/conclusao da licitacao."},
{a:2023,r:"FCC/Fiscal-2023",q:"A modalidade CONCURSO (Lei 14.133) destina-se a:",o:["A) Compra de bens comuns","B) Escolha de trabalho tecnico, cientifico ou artistico mediante premio","C) Alienacao de bens","D) Obras","E) Servicos continuos"],g:"B",c:"CONCURSO: selecao de trabalho TECNICO, CIENTIFICO ou ARTISTICO, com premio ou remuneracao ao vencedor."},
{a:2022,r:"FCC/PGE-2022",q:"Na improbidade (Lei 14.230/21), atos que atentam contra principios exigem:",o:["A) Culpa","B) Dolo (vontade livre e consciente de violar a lei)","C) Mero dano","D) Enriquecimento","E) Prejuizo ao erario"],g:"B",c:"Apos a Lei 14.230/21, todos os atos de improbidade (inclusive o do art. 11 - contra principios) exigem DOLO. Culpa nao caracteriza mais improbidade."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A agencia de inovacao 'sandbox regulatorio' refere-se a:",o:["A) Licitacao","B) Ambiente experimental controlado para testar inovacoes com flexibilizacao temporaria de regras","C) Pregao eletronico","D) Convenio","E) Termo de fomento"],g:"B",c:"Sandbox regulatorio: ambiente de testes com afastamento controlado e temporario de normas, para inovacoes (ex: fintechs), sob supervisao do regulador."},
{a:2023,r:"FCC/Fiscal-2023",q:"O credenciamento, na Lei 14.133, e hipotese de:",o:["A) Licitacao por pregao","B) Contratacao direta por inexigibilidade (todos os interessados aptos sao contratados)","C) Dispensa por valor","D) Concorrencia","E) Leilao"],g:"B",c:"Credenciamento: processo de contratacao em que TODOS os interessados que cumpram os requisitos podem ser contratados (inviabilidade de competicao -> inexigibilidade)."},
{a:2022,r:"FCC/PGE-2022",q:"As sancoes por ato de improbidade incluem:",o:["A) Apenas multa","B) Perda da funcao, suspensao de direitos politicos, ressarcimento e proibicao de contratar","C) Prisao automatica","D) So advertencia","E) Apenas demissao"],g:"B",c:"Sancoes (art. 12 Lei 8.429): perda dos bens, ressarcimento, perda da funcao, suspensao dos direitos politicos, multa civil e proibicao de contratar com o Poder Publico."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A fase preparatoria da licitacao (Lei 14.133) compreende:",o:["A) A homologacao","B) O planejamento: ETP, termo de referencia, pesquisa de precos e analise de riscos","C) O julgamento","D) A habilitacao","E) Os recursos"],g:"B",c:"Fase preparatoria: planejamento com Estudo Tecnico Preliminar (ETP), termo de referencia/projeto, pesquisa de precos e matriz/analise de riscos."},
{a:2023,r:"FCC/Fiscal-2023",q:"A Lei Anticorrupcao prevê, como atenuante, a celebracao de:",o:["A) Termo de ajuste","B) Acordo de leniencia (colaboracao da PJ reduz sancoes)","C) Convenio","D) Contrato","E) Parceria"],g:"B",c:"Acordo de LENIENCIA (Lei 12.846): a PJ que colabora efetivamente (identifica envolvidos, fornece provas) obtem reducao das sancoes."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A Lei 14.133/21 permite, como procedimento auxiliar:",o:["A) Apenas o pregao","B) O sistema de registro de precos (SRP) e o credenciamento","C) So a concorrencia","D) Somente dispensa","E) Apenas leilao"],g:"B",c:"Procedimentos auxiliares (Lei 14.133): credenciamento, pre-qualificacao, procedimento de manifestacao de interesse, sistema de registro de precos (SRP) e registro cadastral."},
{a:2023,r:"FCC/Fiscal-2023",q:"Na contratacao integrada (Lei 14.133), o contratado:",o:["A) So executa a obra","B) Elabora os projetos basico e executivo e executa a obra","C) Apenas projeta","D) Fiscaliza","E) Fornece material"],g:"B",c:"CONTRATACAO INTEGRADA: o contratado e responsavel por elaborar os projetos BASICO e EXECUTIVO, executar a obra e demais operacoes necessarias (regime de obras)."},
{a:2022,r:"FCC/PGE-2022",q:"A prescricao das sancoes da Lei Anticorrupcao (12.846) e de:",o:["A) 3 anos","B) 5 anos da ciencia da infracao (ou do fim, se permanente)","C) 10 anos","D) 8 anos","E) Imprescritivel"],g:"B",c:"Lei 12.846: as infracoes prescrevem em 5 ANOS contados da ciencia da infracao ou, no caso de permanente/continuada, do dia em que cessar."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A modalidade de licitacao extinta pela Lei 14.133 (em relacao a Lei 8.666) foi:",o:["A) Pregao","B) Tomada de precos e convite","C) Concorrencia","D) Leilao","E) Concurso"],g:"B",c:"A Lei 14.133 EXTINGUIU as modalidades TOMADA DE PRECOS e CONVITE (da antiga Lei 8.666). Restam: pregao, concorrencia, concurso, leilao e dialogo competitivo."},
{a:2023,r:"FCC/Fiscal-2023",q:"O agente de contratacao, na Lei 14.133, e responsavel por:",o:["A) Julgar recursos sempre","B) Conduzir a licitacao, impulsionando o procedimento","C) Assinar o contrato","D) Fiscalizar a obra","E) Pagar o fornecedor"],g:"B",c:"O AGENTE DE CONTRATACAO (servidor designado) conduz e impulsiona o processo licitatorio, recebe propostas, conduz a sessao e encaminha as decisoes (auxiliado por equipe de apoio)."},
{a:2022,r:"FCC/PGE-2022",q:"A inexigibilidade por notoria especializacao (servico tecnico) exige:",o:["A) Servico comum","B) Servico tecnico especializado, de natureza singular, com profissional/empresa de notoria especializacao","C) Menor preco","D) Concorrencia","E) Pregao"],g:"B",c:"Inexigibilidade (art. 74, III): contratacao de servico TECNICO ESPECIALIZADO de natureza predominantemente intelectual com profissional ou empresa de NOTORIA ESPECIALIZACAO (vedada para publicidade)."},
],
"ECO-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Se |Ed|=0,3, a demanda e:",o:["A) Elastica","B) Inelastica: aumento de preco eleva a receita","C) Unitaria","D) Perfeitamente inelastica","E) Perfeitamente elastica"],g:"B",c:"|Ed|=0,3<1 -> INELASTICA. Aumento de preco eleva a receita total (quantidade cai pouco)."},
{a:2022,r:"FCC/Fiscal-2022",q:"A Curva de Laffer demonstra que:",o:["A) Mais aliquota sempre eleva arrecadacao","B) Ha aliquota otima; acima dela, mais tributacao reduz arrecadacao","C) Arrecadacao maxima com aliquota zero","D) Relacao linear aliquota-arrecadacao","E) Reduzir aliquota sempre eleva arrecadacao"],g:"B",c:"Laffer: aliquota 0%=arrecadacao 0; 100%=arrecadacao 0. Ha ponto OTIMO; acima dele, evasao/informalidade reduzem a arrecadacao."},
{a:2021,r:"FCC/ISS-2021",q:"A Regra de Ramsey, na tributacao otima, recomenda:",o:["A) Mesma aliquota para todos os bens","B) Aliquotas maiores em bens inelasticos para minimizar o peso morto","C) Aliquotas menores em bens de luxo","D) Maximizar arrecadacao ignorando eficiencia","E) Tributar so servicos"],g:"B",c:"Regra de RAMSEY: aliquotas inversamente proporcionais a elasticidade. Bens INELASTICOS -> aliquota maior (menor distorcao)."},
{a:2020,r:"FCC/TRF-2020",q:"A externalidade NEGATIVA provoca falha de mercado porque:",o:["A) Produz quantidade insuficiente","B) Custo social > custo privado; mercado produz em excesso","C) Empresas nao lucram","D) E bem publico","E) Exige subsidio"],g:"B",c:"Externalidade NEGATIVA: custo social > privado -> producao ACIMA do otimo. Solucao: imposto pigouviano."},
{a:2019,r:"FCC/Adm-2019",q:"Em concorrencia perfeita, no longo prazo, o lucro economico tende a:",o:["A) Ser maximo","B) Ser zero","C) Ser negativo","D) Crescer indefinidamente","E) Igualar o monopolio"],g:"B",c:"Concorrencia perfeita: livre entrada/saida leva o lucro economico a ZERO no longo prazo."},
{a:2023,r:"FCC/TRT-2023",q:"A incidencia economica de um tributo recai mais sobre:",o:["A) Quem a lei define como contribuinte","B) O lado menos elastico do mercado","C) O lado mais elastico","D) Sempre o consumidor","E) Sempre o produtor"],g:"B",c:"A carga recai mais sobre o lado MENOS elastico (que tem menos capacidade de evitar o tributo)."},
{a:2022,r:"FCC/Fiscal-2022",q:"O peso morto (perda de bem-estar) da tributacao e maior quando:",o:["A) A demanda e perfeitamente inelastica","B) Oferta e demanda sao mais elasticas","C) Nao ha tributo","D) O bem e essencial","E) A aliquota e zero"],g:"B",c:"Peso morto e MAIOR quanto mais ELASTICAS forem oferta e demanda (mais distorcao de quantidade)."},
{a:2021,r:"FCC/ISS-2021",q:"No monopolio, comparado a concorrencia perfeita, observa-se:",o:["A) Preco menor e quantidade maior","B) Preco maior e quantidade menor, com peso morto","C) Lucro zero","D) Ausencia de barreiras","E) Produto homogeneo"],g:"B",c:"Monopolio: preco MAIOR, quantidade MENOR que o otimo social -> gera peso morto (ineficiencia alocativa)."},
{a:2020,r:"FCC/TRF-2020",q:"Um bem com muitos substitutos proximos tende a ter demanda:",o:["A) Inelastica","B) Elastica","C) Unitaria","D) Perfeitamente inelastica","E) Constante"],g:"B",c:"Mais substitutos -> demanda mais ELASTICA (consumidor troca facilmente se o preco sobe)."},
{a:2019,r:"FCC/Adm-2019",q:"O imposto PIGOUVIANO tem como objetivo:",o:["A) Maximizar arrecadacao","B) Corrigir externalidade negativa internalizando o custo social","C) Subsidiar producao","D) Reduzir a oferta de bens publicos","E) Eliminar o monopolio"],g:"B",c:"Imposto PIGOUVIANO=corrige externalidade negativa, igualando custo privado ao social (poluidor-pagador)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Quando a demanda e perfeitamente INELASTICA, um imposto recai:",o:["A) Todo sobre o produtor","B) Todo sobre o consumidor","C) Meio a meio","D) Sobre ninguem","E) Gera maior peso morto"],g:"B",c:"Demanda perfeitamente inelastica: o consumidor compra a mesma quantidade a qualquer preco, logo arca com TODO o imposto; peso morto = zero."},
{a:2023,r:"FCC/Fiscal-2023",q:"Bens GIFFEN caracterizam-se por:",o:["A) Demanda elastica","B) Quantidade demandada que AUMENTA quando o preco sobe","C) Serem de luxo","D) Nao terem substitutos","E) Demanda unitaria"],g:"B",c:"Bem de GIFFEN (caso raro): a quantidade demandada aumenta com o aumento do preco (efeito renda supera o substituicao), violando a lei da demanda."},
{a:2022,r:"FCC/PGE-2022",q:"Em concorrencia perfeita, a empresa e tomadora de preco porque:",o:["A) Define o preco","B) Sua producao e insignificante frente ao mercado","C) Tem monopolio","D) Diferencia produtos","E) Ha barreiras a entrada"],g:"B",c:"Concorrencia perfeita: muitos produtores com produto homogeneo; cada um e PRICE TAKER (a oferta individual nao afeta o preco de mercado)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O excedente do consumidor e:",o:["A) O lucro da empresa","B) A diferenca entre o que o consumidor estaria disposto a pagar e o que pagou","C) O imposto","D) O custo marginal","E) A receita total"],g:"B",c:"Excedente do CONSUMIDOR: diferenca entre a disposicao maxima a pagar e o preco efetivamente pago. Tributos reduzem os excedentes e geram peso morto."},
{a:2023,r:"FCC/Fiscal-2023",q:"A elasticidade-renda negativa indica bem:",o:["A) Normal","B) Inferior","C) De luxo","D) Substituto","E) Complementar"],g:"B",c:"Elasticidade-renda NEGATIVA: a demanda CAI quando a renda sobe = bem INFERIOR (ex: transporte muito basico). Positiva = normal; >1 = superior/luxo."},
{a:2022,r:"FCC/PGE-2022",q:"O monopolio natural ocorre quando:",o:["A) Ha muitos produtores","B) Os custos medios decrescem na faixa relevante (economias de escala)","C) Nao ha barreiras","D) O produto e homogeneo","E) Ha livre entrada"],g:"B",c:"Monopolio natural: economias de escala fazem o custo medio cair continuamente; uma unica firma atende ao mercado com custo menor que varias (ex: redes de agua, energia)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Tributar um bem com oferta inelastica, do ponto de vista da eficiencia:",o:["A) Gera grande peso morto","B) Gera pequeno peso morto (menor distorcao)","C) Nao arrecada","D) Aumenta a quantidade","E) Reduz a arrecadacao"],g:"B",c:"Quanto mais INELASTICA a oferta (ou demanda), MENOR o peso morto do imposto (a quantidade pouco se altera). Base da regra de Ramsey."},
{a:2023,r:"FCC/Fiscal-2023",q:"Dois bens sao SUBSTITUTOS quando a elasticidade-preco cruzada e:",o:["A) Negativa","B) Positiva","C) Zero","D) Unitaria","E) Infinita"],g:"B",c:"Elasticidade cruzada POSITIVA: o aumento do preco de um eleva a demanda do outro = SUBSTITUTOS (cafe e cha). Negativa = complementares (carro e gasolina)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O custo marginal e definido como:",o:["A) Custo total / quantidade","B) Variacao do custo total ao produzir uma unidade adicional","C) Custo fixo medio","D) Receita marginal","E) Custo variavel total"],g:"B",c:"Custo MARGINAL (CMg): acrescimo no custo total ao produzir UMA unidade adicional. A firma maximiza lucro onde CMg = Receita Marginal."},
{a:2023,r:"FCC/Fiscal-2023",q:"Em mercado de concorrencia perfeita, o preco e igual ao:",o:["A) Custo fixo","B) Custo marginal no equilibrio (P = CMg)","C) Custo total","D) Lucro","E) Custo medio sempre"],g:"B",c:"Em concorrencia perfeita, a firma produz onde P = CMg (a curva de oferta da firma e o ramo crescente do CMg acima do custo variavel medio)."},
{a:2022,r:"FCC/PGE-2022",q:"O imposto sobre o consumo tende a ser, quanto a equidade:",o:["A) Progressivo","B) Regressivo (pesa mais sobre quem tem menor renda)","C) Neutro sempre","D) Proporcional ao patrimonio","E) Confiscatorio"],g:"B",c:"Tributos sobre o CONSUMO tendem a ser REGRESSIVOS: os mais pobres gastam proporcionalmente mais da renda em consumo, suportando carga relativa maior."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A externalidade positiva justifica a intervencao estatal via:",o:["A) Imposto pigouviano","B) Subsidio ou provisao publica (consumo abaixo do otimo social)","C) Proibicao","D) Tarifa","E) Monopolio"],g:"B",c:"Externalidade POSITIVA (ex: educacao, vacinacao): beneficio social > privado, consumo fica ABAIXO do otimo. Solucao: SUBSIDIO ou provisao publica para aproximar do otimo."},
{a:2023,r:"FCC/Fiscal-2023",q:"A curva de Laffer sugere que aliquotas muito altas:",o:["A) Sempre aumentam a arrecadacao","B) Podem reduzir a arrecadacao (desestimulo, evasao, informalidade)","C) Nao afetam","D) Eliminam o peso morto","E) Tornam o tributo progressivo"],g:"B",c:"Curva de LAFFER: a partir de certo ponto, aliquotas mais altas REDUZEM a arrecadacao (desestimulam producao, estimulam evasao e informalidade)."},
{a:2022,r:"FCC/PGE-2022",q:"Bens publicos puros caracterizam-se por nao-rivalidade, que significa:",o:["A) Exclusao facil","B) O consumo por um nao reduz a disponibilidade para outros","C) Preco alto","D) Escassez","E) Rivalidade total"],g:"B",c:"NAO-RIVALIDADE: o consumo por um individuo nao diminui a quantidade disponivel aos demais (ex: iluminacao publica, defesa nacional). Combinada com nao-exclusao = bem publico puro."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Quando oferta e demanda sao ambas elasticas, o peso morto do imposto e:",o:["A) Zero","B) Maior (grande reducao de quantidade transacionada)","C) Negativo","D) Igual a arrecadacao","E) Inexistente"],g:"B",c:"Peso morto e MAIOR quando ambos os lados sao elasticos: o imposto provoca grande queda na quantidade negociada, aumentando a perda de eficiencia."},
{a:2023,r:"FCC/Fiscal-2023",q:"No oligopolio, a interdependencia significa que:",o:["A) As firmas ignoram as concorrentes","B) A decisao de cada firma considera a reacao das demais","C) Ha infinitas firmas","D) O produto e unico","E) Nao ha barreiras"],g:"B",c:"OLIGOPOLIO: poucas firmas com INTERDEPENDENCIA estrategica - cada uma considera as possiveis reacoes das concorrentes ao definir preco/quantidade (teoria dos jogos)."},
{a:2022,r:"FCC/PGE-2022",q:"A regra de Ramsey, sob equidade, e criticada porque:",o:["A) Tributa bens elasticos","B) Tributar mais bens inelasticos (essenciais) pode ser regressivo","C) Reduz a arrecadacao","D) Elimina o peso morto","E) Beneficia os pobres"],g:"B",c:"Critica a regra de Ramsey: bens INELASTICOS sao muitas vezes ESSENCIAIS (alimentos, remedios), consumidos proporcionalmente mais pelos pobres - tributa-los pesadamente fere a EQUIDADE."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A receita marginal de um monopolista e:",o:["A) Igual ao preco","B) Menor que o preco (precisa baixar o preco para vender mais)","C) Maior que o preco","D) Constante","E) Zero"],g:"B",c:"No MONOPOLIO, a receita marginal e MENOR que o preco, pois para vender uma unidade a mais o monopolista reduz o preco de todas as unidades (curva de demanda negativamente inclinada)."},
],
"ECO-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"O PIB pela otica da demanda e:",o:["A) Salarios+Lucros+Juros+Alugueis","B) Valor da Producao - Consumo Intermediario","C) C+I+G+(X-M)","D) PNB - renda externa","E) Consumo+Poupanca"],g:"C",c:"Otica da DEMANDA: PIB=C+I+G+(X-M). Renda: W+L+J+A. Producao: soma dos valores adicionados."},
{a:2022,r:"FCC/Fiscal-2022",q:"A diferenca entre PIB e PNB e:",o:["A) Inflacao","B) A renda liquida enviada/recebida do exterior","C) Os impostos indiretos","D) A depreciacao","E) O consumo intermediario"],g:"B",c:"PNB=PIB - renda enviada ao exterior + renda recebida do exterior. PIB=territorio; PNB=residentes."},
{a:2021,r:"FCC/ISS-2021",q:"Politica fiscal expansionista, no modelo IS-LM:",o:["A) Desloca a LM para a esquerda","B) Desloca a IS para a direita","C) Reduz o PIB","D) Eleva a taxa de cambio","E) Nao afeta o produto"],g:"B",c:"Politica fiscal expansionista (aumento de G ou reducao de T) desloca a IS para a DIREITA, elevando produto e juros."},
{a:2020,r:"FCC/TRF-2020",q:"O indice oficial de inflacao do Brasil e o:",o:["A) IGP-M","B) IPCA","C) INPC","D) IPC-Fipe","E) IGP-DI"],g:"B",c:"IPCA (IBGE) e o indice OFICIAL de inflacao, usado nas metas do Banco Central. Familias de 1 a 40 salarios minimos."},
{a:2019,r:"FCC/Adm-2019",q:"O multiplicador keynesiano dos gastos e igual a:",o:["A) 1/(propensao marginal a consumir)","B) 1/(propensao marginal a poupar)","C) Propensao a consumir","D) PIB/consumo","E) 1/inflacao"],g:"B",c:"Multiplicador=1/PMgPoupar=1/(1-PMgConsumir). Quanto maior a propensao a consumir, maior o multiplicador."},
{a:2023,r:"FCC/TRT-2023",q:"Politica monetaria CONTRACIONISTA (combate a inflacao) envolve:",o:["A) Reducao da taxa Selic","B) Elevacao da taxa de juros","C) Aumento de gastos publicos","D) Reducao de impostos","E) Emissao de moeda"],g:"B",c:"Monetaria contracionista: ELEVA juros (Selic), reduz liquidez, controla inflacao. Fiscal usa gastos/tributos."},
{a:2022,r:"FCC/Fiscal-2022",q:"O investimento (I) no PIB inclui:",o:["A) Apenas compra de acoes","B) Formacao bruta de capital fixo + variacao de estoques","C) Gastos do governo","D) Consumo das familias","E) Exportacoes"],g:"B",c:"I=FBCF (maquinas, construcao) + variacao de estoques. Compra de acoes e aplicacao financeira, nao entra no I do PIB."},
{a:2021,r:"FCC/ISS-2021",q:"O deflator do PIB e calculado por:",o:["A) PIB real / PIB nominal","B) (PIB nominal / PIB real) x 100","C) PIB nominal - PIB real","D) IPCA acumulado","E) PIB / populacao"],g:"B",c:"Deflator=(PIB nominal/PIB real)x100. Mede a variacao geral de precos de todos os bens do PIB."},
{a:2020,r:"FCC/TRF-2020",q:"Na balanca comercial, exportacoes superiores a importacoes geram:",o:["A) Deficit","B) Superavit comercial","C) Equilibrio","D) Inflacao","E) Recessao"],g:"B",c:"Exportacoes > importacoes = SUPERAVIT comercial (saldo positivo na balanca comercial)."},
{a:2019,r:"FCC/Adm-2019",q:"A conta corrente do balanco de pagamentos inclui:",o:["A) Apenas investimentos diretos","B) Bens, servicos, rendas e transferencias unilaterais","C) Reservas internacionais","D) Emprestimos externos","E) Apenas a balanca comercial"],g:"B",c:"Conta corrente: balanca comercial (bens) + servicos + rendas (juros, lucros) + transferencias unilaterais."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O PIB nominal difere do real porque o nominal:",o:["A) Exclui servicos","B) Usa precos correntes (inclui o efeito da inflacao)","C) Usa precos de um ano-base","D) E sempre menor","E) Nao considera o governo"],g:"B",c:"PIB NOMINAL: a precos correntes (sofre inflacao). PIB REAL: a precos de um ano-base (mede a producao fisica). Deflator = nominal/real x 100."},
{a:2023,r:"FCC/Fiscal-2023",q:"Politica monetaria expansionista, em regra:",o:["A) Eleva a Selic","B) Reduz juros e aumenta a oferta de moeda","C) Reduz gastos publicos","D) Eleva impostos","E) Vende titulos"],g:"B",c:"Monetaria EXPANSIONISTA: reduz juros, compra titulos (open market), reduz compulsorio -> mais credito e demanda agregada."},
{a:2022,r:"FCC/PGE-2022",q:"No modelo IS-LM, a curva LM representa o equilibrio no mercado:",o:["A) De bens","B) Monetario (oferta e demanda por moeda)","C) De trabalho","D) Cambial","E) Externo"],g:"B",c:"LM: equilibrio do mercado MONETARIO (oferta = demanda por moeda). IS: mercado de BENS. O cruzamento da o equilibrio de renda e juros."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A inflacao de DEMANDA ocorre quando:",o:["A) Custos sobem","B) A demanda agregada cresce acima da capacidade produtiva","C) A moeda valoriza","D) Cai o consumo","E) Sobe o desemprego"],g:"B",c:"Inflacao de DEMANDA: excesso de demanda agregada frente a oferta (economia aquecida). Inflacao de CUSTOS: alta de insumos/salarios."},
{a:2023,r:"FCC/Fiscal-2023",q:"Os instrumentos classicos da politica monetaria sao:",o:["A) Gastos e tributos","B) Taxa de juros, deposito compulsorio e open market","C) Cambio fixo","D) Salario minimo","E) Tarifas publicas"],g:"B",c:"Politica MONETARIA: taxa de juros (Selic), recolhimento compulsorio e operacoes de mercado aberto (open market). Politica FISCAL usa gastos e tributos."},
{a:2022,r:"FCC/PGE-2022",q:"Quando o pais tem superavit em conta corrente:",o:["A) Importa mais que exporta","B) As receitas externas (exportacoes, rendas) superam as despesas","C) Aumenta a divida externa","D) Ha deficit comercial","E) Cai a reserva"],g:"B",c:"Superavit em conta corrente: as entradas (exportacoes, rendas, transferencias) superam as saidas; o pais e exportador liquido de poupanca."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O cambio FLUTUANTE caracteriza-se por:",o:["A) Taxa fixada pelo governo","B) Taxa definida pelo mercado (oferta e demanda de divisas)","C) Bandas cambiais rigidas","D) Paridade com o ouro","E) Controle de capitais total"],g:"B",c:"Cambio FLUTUANTE: a taxa e determinada livremente pelo mercado. FIXO: o BC fixa e defende a paridade. Brasil adota flutuante (com intervencoes)."},
{a:2023,r:"FCC/Fiscal-2023",q:"O efeito multiplicador dos gastos publicos e maior quando:",o:["A) A propensao marginal a consumir e baixa","B) A propensao marginal a consumir e alta","C) Nao ha consumo","D) Os impostos sao altos","E) A poupanca e total"],g:"B",c:"Multiplicador = 1/(1-PMgC). Quanto MAIOR a propensao a consumir, maior o multiplicador (cada real gasto reverbera mais na economia)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O agregado M1 (meios de pagamento restritos) compreende:",o:["A) Poupanca e titulos","B) Papel-moeda em poder do publico + depositos a vista","C) Apenas moeda no BC","D) Reservas internacionais","E) Toda a divida"],g:"B",c:"M1 = papel-moeda em poder do publico + depositos a vista (a liquidez imediata). M2, M3, M4 agregam aplicacoes progressivamente menos liquidas."},
{a:2023,r:"FCC/Fiscal-2023",q:"O efeito 'crowding out' (deslocamento) ocorre quando:",o:["A) Gasto publico estimula o privado","B) Aumento do gasto/divida publica eleva juros e reduz o investimento privado","C) Cai a inflacao","D) Sobe o cambio","E) Reduz o consumo"],g:"B",c:"CROWDING OUT: a expansao fiscal (mais gasto/divida) pressiona os juros para cima, DESLOCANDO (reduzindo) o investimento privado."},
{a:2022,r:"FCC/PGE-2022",q:"A taxa Selic e o principal instrumento da politica:",o:["A) Fiscal","B) Monetaria","C) Cambial","D) De rendas","E) Comercial"],g:"B",c:"A taxa SELIC (meta definida pelo Copom) e o instrumento central da politica MONETARIA brasileira para controlar a inflacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Uma desvalorizacao cambial tende a:",o:["A) Encarecer exportacoes","B) Estimular exportacoes e encarecer importacoes","C) Reduzir o dolar","D) Baratear importacoes","E) Nao afetar o comercio"],g:"B",c:"Desvalorizacao da moeda nacional (dolar sobe): exportacoes ficam mais competitivas (estimuladas) e importacoes mais caras (desestimuladas)."},
{a:2023,r:"FCC/Fiscal-2023",q:"No balanco de pagamentos, o investimento estrangeiro direto registra-se na conta:",o:["A) Corrente","B) Financeira (capital e financeira)","C) De servicos","D) De rendas","E) De transferencias"],g:"B",c:"O Investimento Estrangeiro Direto (IED) e registrado na conta FINANCEIRA (entrada de capitais), nao na conta corrente."},
{a:2022,r:"FCC/PGE-2022",q:"A politica fiscal contracionista, para conter inflacao de demanda, envolve:",o:["A) Aumentar gastos","B) Reduzir gastos publicos e/ou elevar tributos","C) Reduzir juros","D) Emitir moeda","E) Desvalorizar o cambio"],g:"B",c:"Politica fiscal CONTRACIONISTA: reduzir gastos e/ou aumentar tributos, diminuindo a demanda agregada para conter a inflacao."},
],
"DCO-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"No controle CONCENTRADO (ADI), os efeitos da decisao sao:",o:["A) Inter partes e ex nunc","B) Erga omnes, ex tunc e vinculante","C) Inter partes e ex tunc","D) Erga omnes e ex nunc apenas","E) Vinculante so para a Adm."],g:"B",c:"ADI/ADC/ADPF: erga omnes + ex tunc + vinculante (Judiciario e Adm. Publica). Modulacao temporal por 2/3 do STF."},
{a:2022,r:"FCC/TCE-2022",q:"A ADPF e cabivel para:",o:["A) Qualquer lei federal","B) Atos do poder publico que violem preceito fundamental, inclusive leis pre-1988","C) So leis municipais","D) Contratos administrativos","E) Atos de particulares"],g:"B",c:"ADPF (Lei 9.882/99): viola preceito fundamental; cabe contra leis PRE-constitucionais e atos municipais. Carater subsidiario."},
{a:2021,r:"FCC/PGE-2021",q:"A Sumula Vinculante vincula:",o:["A) So o STF","B) Todo o Judiciario e a Adm. Publica direta e indireta","C) Apenas a Adm. federal","D) Tambem o Legislativo (funcao tipica)","E) So instancias inferiores"],g:"B",c:"SV (art. 103-A): vincula todo o Judiciario + Adm. Publica direta e indireta. NAO vincula o STF nem o Legislativo (funcao tipica)."},
{a:2020,r:"FCC/ISS-2020",q:"Os direitos fundamentais do art. 5 CF tem aplicacao:",o:["A) Diferida","B) Imediata (art. 5 par.1)","C) Condicionada a lei","D) Programatica","E) So para natos"],g:"B",c:"Art. 5 par. 1: normas de direitos e garantias fundamentais tem aplicacao IMEDIATA."},
{a:2019,r:"FCC/TRF-2019",q:"No controle DIFUSO, os efeitos sao:",o:["A) Erga omnes","B) Inter partes e ex tunc","C) Vinculantes","D) Ex nunc obrigatorio","E) So prospectivos"],g:"B",c:"Difuso: INTER PARTES + ex tunc. Senado pode suspender (art. 52, X) para erga omnes + ex nunc."},
{a:2023,r:"FCC/TRT-2023",q:"Sao legitimados para propor ADI (art. 103 CF), EXCETO:",o:["A) Presidente da Republica","B) Procurador-Geral da Republica","C) Conselho Federal da OAB","D) Qualquer cidadao","E) Governador de Estado"],g:"D",c:"Cidadao NAO e legitimado para ADI (so para acao popular). Legitimados: Presidente, Mesas, Governadores, PGR, OAB, partidos, confederacoes."},
{a:2022,r:"FCC/TCE-2022",q:"A clausula petrea NAO inclui:",o:["A) Forma federativa de Estado","B) Voto direto, secreto, universal e periodico","C) Separacao dos Poderes","D) Direitos e garantias individuais","E) A taxa de juros constitucional"],g:"E",c:"Clausulas petreas (art. 60 par.4): forma federativa, voto direto/secreto, separacao dos poderes, direitos individuais. Taxa de juros nao e clausula petrea."},
{a:2021,r:"FCC/PGE-2021",q:"Norma constitucional de eficacia CONTIDA caracteriza-se por:",o:["A) Depender totalmente de lei","B) Ser plena, mas poder ser restringida por lei posterior","C) Nunca produzir efeitos","D) Ser apenas programatica","E) Nao admitir restricao"],g:"B",c:"Eficacia CONTIDA: aplicacao imediata e plena, mas pode ser RESTRINGIDA por lei (ex: liberdade profissional)."},
{a:2020,r:"FCC/ISS-2020",q:"A ADO (Acao Direta de Inconstitucionalidade por Omissao) combate:",o:["A) Lei inconstitucional","B) Omissao do legislador em regulamentar a CF","C) Ato administrativo","D) Decisao judicial","E) Conflito entre estados"],g:"B",c:"ADO: combate a OMISSAO inconstitucional (falta de norma regulamentadora). Da-se ciencia ao orgao omisso."},
{a:2019,r:"FCC/TRF-2019",q:"O efeito vinculante da ADI alcanca:",o:["A) O proprio STF","B) O Poder Legislativo na funcao de legislar","C) Os demais orgaos do Judiciario e a Adm. Publica","D) Apenas as partes do processo","E) So a Uniao"],g:"C",c:"Efeito vinculante: demais orgaos do Judiciario + Adm. Publica direta e indireta. NAO vincula o STF nem o Legislativo (funcao tipica)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A modulacao de efeitos na ADI exige quorum de:",o:["A) Maioria simples","B) Maioria absoluta","C) 2/3 dos membros do STF","D) Unanimidade","E) 3/5"],g:"C",c:"Art. 27 Lei 9.868/99: a modulacao temporal dos efeitos (restringir/alterar o marco) exige maioria de 2/3 dos membros do STF (8 ministros)."},
{a:2023,r:"FCC/TCE-2023",q:"No controle difuso, a clausula de reserva de plenario (art. 97 CF) exige:",o:["A) Decisao monocratica","B) Que a inconstitucionalidade so seja declarada pela maioria absoluta do tribunal ou do orgao especial","C) Voto unanime","D) Decisao do STF sempre","E) Quorum simples"],g:"B",c:"Art. 97 (full bench): tribunais so declaram inconstitucionalidade pela maioria absoluta do plenario ou do orgao especial (SV 10 reforca)."},
{a:2022,r:"FCC/PGE-2022",q:"A acao declaratoria de constitucionalidade (ADC) tem por objeto:",o:["A) Lei estadual","B) Lei ou ato normativo FEDERAL, para afastar controversia relevante","C) Ato municipal","D) Emenda constitucional","E) Decreto autonomo estadual"],g:"B",c:"ADC: cabivel apenas contra lei/ato normativo FEDERAL, exigindo demonstracao de controversia judicial relevante. Efeitos: erga omnes, vinculante, ex tunc."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Norma de eficacia LIMITADA:",o:["A) Produz todos os efeitos desde a promulgacao","B) Depende de regulamentacao para produzir plenos efeitos","C) Pode ser restringida por lei","D) E autoaplicavel","E) E clausula petrea"],g:"B",c:"Eficacia LIMITADA: depende de lei integradora para produzir todos os efeitos (programaticas/institutivas). Tem eficacia minima (revoga normas contrarias, vincula o legislador)."},
{a:2023,r:"FCC/TCE-2023",q:"Sao direitos sociais (art. 6 CF), EXCETO:",o:["A) Educacao","B) Saude","C) Propriedade privada","D) Moradia","E) Trabalho"],g:"C",c:"Direitos sociais (art. 6): educacao, saude, alimentacao, trabalho, moradia, transporte, lazer, seguranca, previdencia, protecao a maternidade/infancia e assistencia. Propriedade e direito individual (art. 5)."},
{a:2022,r:"FCC/PGE-2022",q:"A acao popular pode ser proposta por:",o:["A) Qualquer cidadao, para anular ato lesivo ao patrimonio publico","B) Apenas o MP","C) So partidos politicos","D) O PGR","E) Pessoas juridicas"],g:"A",c:"Acao popular (art. 5, LXXIII): qualquer CIDADAO (eleitor) pode anular ato lesivo ao patrimonio publico, a moralidade, ao meio ambiente e ao patrimonio historico."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O principio da legalidade tributaria (art. 150, I CF) exige:",o:["A) Decreto","B) Lei para instituir ou majorar tributos","C) Portaria","D) Convenio","E) Resolucao do Senado sempre"],g:"B",c:"Legalidade tributaria: tributo so e instituido ou majorado por LEI (em regra). Excecoes de aliquota (II, IE, IPI, IOF) podem ser alteradas por ato do Executivo, nos limites legais."},
{a:2023,r:"FCC/TCE-2023",q:"A imunidade reciproca (art. 150, VI, 'a') veda:",o:["A) Cobranca de taxas","B) Instituicao de IMPOSTOS sobre patrimonio, renda e servicos entre os entes federativos","C) Contribuicoes","D) Tarifas","E) ICMS sobre empresas"],g:"B",c:"Imunidade reciproca: veda a Uniao, Estados, DF e Municipios instituirem IMPOSTOS sobre patrimonio, renda ou servicos uns dos outros (protege o pacto federativo)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A repartição de receitas tributarias (CF) destina aos Municipios:",o:["A) 100% do IR retido na fonte de seus servidores","B) Parcela do ICMS (25%) e do IPVA (50%) estaduais","C) Todo o ICMS","D) O IPI integral","E) Nada"],g:"B",c:"Os Municipios recebem 25% do ICMS e 50% do IPVA arrecadados pelo Estado (alem de 100% do IR-fonte de seus servidores e 50% do ITR). E reparticao de receita, nao da competencia."},
{a:2023,r:"FCC/TCE-2023",q:"A imunidade dos templos de qualquer culto (art. 150, VI, 'b') alcanca:",o:["A) Todos os tributos","B) Impostos sobre patrimonio, renda e servicos relacionados as finalidades essenciais","C) Taxas","D) Contribuicoes","E) So o IPTU"],g:"B",c:"A imunidade religiosa abrange IMPOSTOS sobre patrimonio, renda e servicos vinculados as finalidades essenciais do templo. Nao alcanca taxas nem contribuicoes."},
{a:2022,r:"FCC/PGE-2022",q:"O principio da anterioridade nonagesimal (noventena) NAO se aplica ao:",o:["A) ICMS","B) Imposto de Renda","C) IPI","D) Contribuicoes sociais","E) IPVA (base de calculo)"],g:"B",c:"O IR e excecao a NOVENTENA (mas obedece a anterioridade anual). A fixacao da base de calculo de IPVA e IPTU tambem excepciona a noventena."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A competencia para instituir o ITCD e:",o:["A) Federal","B) Estadual/DF","C) Municipal","D) Compartilhada","E) Do Senado"],g:"B",c:"O ITCD (transmissao causa mortis e doacao) e de competencia dos ESTADOS e do DF (art. 155, I CF). As aliquotas maximas sao fixadas pelo Senado (8%)."},
{a:2023,r:"FCC/TCE-2023",q:"Lei complementar e exigida para:",o:["A) Instituir qualquer tributo","B) Dispor sobre normas gerais, conflitos de competencia e instituir emprestimos compulsorios","C) Fixar aliquota do IPI","D) Criar taxa","E) Conceder isencao de ICMS"],g:"B",c:"Art. 146 CF: LC para normas gerais, conflitos de competencia, regular limitacoes ao poder de tributar. Tambem instituicao de emprestimos compulsorios (art. 148) e IGF."},
{a:2022,r:"FCC/PGE-2022",q:"O principio do nao-confisco (art. 150, IV) veda tributo que:",o:["A) Seja progressivo","B) Tenha efeito de confisco (carga excessiva que inviabilize a propriedade/atividade)","C) Seja seletivo","D) Incida sobre consumo","E) Seja indireto"],g:"B",c:"Vedacao ao CONFISCO: o tributo nao pode ser tao gravoso que absorva o bem/renda ou inviabilize a atividade economica. Aplica-se tambem as multas (STF)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A medida provisoria, em materia tributaria, pode:",o:["A) Instituir qualquer tributo livremente","B) Instituir/majorar impostos, produzindo efeito no exercicio seguinte se convertida em lei ate o fim do exercicio de edicao","C) Criar emprestimo compulsorio","D) Tratar de materia de LC","E) Reduzir garantias"],g:"B",c:"Art. 62, par.2 CF: MP que institua/majore IMPOSTO so produz efeitos no exercicio seguinte se convertida em LEI ate o ultimo dia do exercicio em que foi editada (salvo II, IE, IPI, IOF, extraordinarios)."},
{a:2023,r:"FCC/TCE-2023",q:"A seletividade do IPI e do ICMS significa que:",o:["A) A aliquota e unica","B) As aliquotas variam conforme a essencialidade do produto","C) Ha isencao total","D) O tributo e cumulativo","E) Nao ha credito"],g:"B",c:"SELETIVIDADE: aliquotas inversamente proporcionais a essencialidade - produtos essenciais (alimentos) menor aliquota; superfluos (cigarro, bebida) maior. Obrigatoria no IPI, facultativa no ICMS."},
{a:2022,r:"FCC/PGE-2022",q:"O contribuinte que paga tributo indevido tem direito a:",o:["A) Multa","B) Restituicao (repeticao de indebito)","C) Prisao","D) Nada","E) Compensacao obrigatoria"],g:"B",c:"Art. 165 CTN: quem paga tributo indevido ou a maior tem direito a RESTITUICAO (repeticao de indebito), independentemente de previo protesto, no prazo de 5 anos."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A vedacao a instituicao de tributo nao uniforme no territorio nacional decorre do principio da:",o:["A) Capacidade contributiva","B) Uniformidade geografica (art. 151, I CF)","C) Anterioridade","D) Legalidade","E) Irretroatividade"],g:"B",c:"Art. 151, I: a Uniao deve instituir tributos UNIFORMES em todo o territorio nacional, vedada distincao em relacao a Estados/Municipios (admitidos incentivos para reduzir desigualdades regionais)."},
],
"DAD-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"O ato com vicio de COMPETENCIA (em razao da pessoa):",o:["A) E sempre nulo","B) Pode ser convalidado/ratificado pela autoridade competente","C) E inexistente","D) E revogavel","E) Nao produz efeitos"],g:"B",c:"Vicio de competencia (em razao da pessoa) e SANAVEL -> admite convalidacao/ratificacao. Exceto competencia exclusiva ou em razao da materia."},
{a:2022,r:"FCC/TCE-2022",q:"A ANULACAO de ato administrativo produz efeitos:",o:["A) Ex nunc","B) Ex tunc (retroativos)","C) So futuros","D) Vinculantes","E) Prospectivos"],g:"B",c:"ANULACAO (ilegalidade): efeitos EX TUNC (retroage). REVOGACAO (merito): ex nunc. Sumula 473 STF."},
{a:2021,r:"FCC/PGE-2021",q:"A responsabilidade civil do Estado (art. 37 par.6) por atos comissivos e:",o:["A) Subjetiva","B) Objetiva (teoria do risco administrativo)","C) Por culpa presumida apenas","D) Penal","E) Inexistente"],g:"B",c:"Atos comissivos: responsabilidade OBJETIVA (risco administrativo). Basta conduta+dano+nexo. Regresso contra agente com dolo/culpa."},
{a:2020,r:"FCC/ISS-2020",q:"A REVOGACAO de ato administrativo:",o:["A) Decorre de ilegalidade","B) Funda-se em conveniencia e oportunidade, efeitos ex nunc, so pela Adm.","C) Tem efeitos ex tunc","D) Pode ser feita pelo Judiciario","E) E vinculada"],g:"B",c:"REVOGACAO: motivo de merito (conveniencia/oportunidade), efeitos EX NUNC, exclusiva da Administracao."},
{a:2019,r:"FCC/SEFAZ-2019",q:"DESCENTRALIZACAO administrativa significa:",o:["A) Distribuir competencias dentro do mesmo orgao","B) Transferir competencias para outra pessoa juridica","C) Criar hierarquia interna","D) Concentrar poder","E) Extinguir orgaos"],g:"B",c:"DESCENTRALIZACAO: transfere para OUTRA PJ (autarquia, fundacao, EP, SEM) ou particular. DESCONCENTRACAO: dentro da mesma PJ (orgaos)."},
{a:2023,r:"FCC/TRT-2023",q:"Atributo do ato administrativo que permite execucao sem intervencao judicial:",o:["A) Presuncao de legitimidade","B) Imperatividade","C) Autoexecutoriedade","D) Tipicidade","E) Discricionariedade"],g:"C",c:"AUTOEXECUTORIEDADE: a Adm. executa o ato diretamente, sem precisar do Judiciario (ex: demolicao, apreensao)."},
{a:2022,r:"FCC/TCE-2022",q:"O poder de POLICIA caracteriza-se por:",o:["A) Punir servidores","B) Limitar direitos individuais em favor do interesse publico","C) Editar regulamentos internos","D) Organizar a hierarquia","E) Anular atos"],g:"B",c:"Poder de POLICIA: condiciona/limita direitos e liberdades em prol do interesse publico (preventivo e repressivo)."},
{a:2021,r:"FCC/PGE-2021",q:"Sao requisitos do ato administrativo (COFIFOMOB):",o:["A) Competencia, finalidade, forma, motivo e objeto","B) Capacidade, forma e objeto licito","C) Apenas competencia e objeto","D) Legalidade e moralidade","E) Forma e publicidade"],g:"A",c:"Requisitos: COmpetencia, FInalidade, FOrma, MOtivo, OBjeto. Vicios em competencia/forma sao sanaveis."},
{a:2020,r:"FCC/ISS-2020",q:"Excludente da responsabilidade civil do Estado:",o:["A) Dolo do agente","B) Culpa exclusiva da vitima","C) Conduta comissiva","D) Nexo causal","E) Dano material"],g:"B",c:"Excludentes (rompem o nexo): culpa exclusiva da vitima, caso fortuito/forca maior, fato exclusivo de terceiro."},
{a:2019,r:"FCC/SEFAZ-2019",q:"A administracao INDIRETA e composta por:",o:["A) Ministerios e secretarias","B) Autarquias, fundacoes publicas, empresas publicas e sociedades de economia mista","C) Orgaos sem personalidade","D) So autarquias","E) Particulares delegatarios"],g:"B",c:"Adm. INDIRETA: autarquias, fundacoes publicas, empresas publicas, sociedades de economia mista (todas com personalidade juridica propria)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A convalidacao do ato administrativo:",o:["A) Tem efeitos ex nunc","B) Tem efeitos ex tunc (retroativos), sanando vicio sanavel","C) E sempre vedada","D) Equivale a revogacao","E) So o Judiciario faz"],g:"B",c:"Convalidacao: sana vicio SANAVEL (competencia/forma) com efeitos EX TUNC (retroage a origem do ato)."},
{a:2023,r:"FCC/TCE-2023",q:"O atributo da presuncao de legitimidade implica que:",o:["A) O ato e sempre valido","B) O onus de provar o vicio recai sobre quem alega (inversao)","C) O ato nao pode ser anulado","D) A Adm. nao erra","E) O ato e imutavel"],g:"B",c:"Presuncao de legitimidade (relativa/juris tantum): presume-se que o ato nasceu conforme a lei; o ONUS DA PROVA do vicio cabe ao administrado."},
{a:2022,r:"FCC/PGE-2022",q:"A responsabilidade do Estado por OMISSAO e, segundo o STF, em regra:",o:["A) Objetiva","B) Subjetiva (exige culpa do servico - faute du service)","C) Inexistente","D) Solidaria","E) Penal"],g:"B",c:"Para a corrente majoritaria/STF, a responsabilidade por omissao e SUBJETIVA: exige demonstrar a falha/culpa do servico (faute du service). Atos comissivos: objetiva."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A autotutela administrativa (Sumulas 346 e 473 STF) permite a Adm.:",o:["A) Julgar acoes","B) Anular seus atos ilegais e revogar os inconvenientes, sem o Judiciario","C) Criar tributos","D) Legislar","E) Punir terceiros sem processo"],g:"B",c:"Autotutela: a Adm. pode ANULAR atos ilegais e REVOGAR atos inconvenientes/inoportunos, respeitados direitos adquiridos e o devido processo (Sumulas 346 e 473 STF)."},
{a:2023,r:"FCC/TCE-2023",q:"O poder discricionario submete-se a controle judicial quanto a:",o:["A) Conveniencia e oportunidade (merito)","B) Legalidade, razoabilidade e proporcionalidade","C) Nada","D) So a forma","E) So o motivo"],g:"B",c:"O Judiciario controla a LEGALIDADE do ato discricionario (inclusive razoabilidade/proporcionalidade), mas NAO substitui o MERITO (conveniencia/oportunidade) do administrador."},
{a:2022,r:"FCC/PGE-2022",q:"A teoria dos motivos determinantes estabelece que:",o:["A) O motivo e irrelevante","B) Os motivos declarados vinculam o ato; se falsos/inexistentes, ele e invalido","C) So o objeto importa","D) A forma e livre","E) A competencia e delegavel sempre"],g:"B",c:"Teoria dos motivos determinantes: a validade do ato fica vinculada aos motivos que o fundamentaram; se inexistentes ou falsos, o ato e nulo."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A delegacao de competencia administrativa:",o:["A) E sempre proibida","B) E possivel, salvo competencia exclusiva, decisao de recurso e edicao de ato normativo","C) Transfere a titularidade","D) Independe de publicacao","E) E irrevogavel"],g:"B",c:"Lei 9.784/99: a delegacao e admitida, salvo: competencia exclusiva, decisao de recursos administrativos e edicao de atos normativos. E revogavel e exige publicacao."},
{a:2023,r:"FCC/TCE-2023",q:"O servico publico prestado sob regime de concessao:",o:["A) Dispensa licitacao","B) Exige licitacao e e remunerado por tarifa do usuario","C) E gratuito sempre","D) Nao admite reajuste","E) E executado direto pela Adm."],g:"B",c:"Concessao (Lei 8.987/95): delegacao mediante LICITACAO (concorrencia), por conta e risco do concessionario, remunerada por TARIFA, preservado o equilibrio economico-financeiro."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O ato administrativo VINCULADO caracteriza-se por:",o:["A) Liberdade de escolha do agente","B) A lei predeterminar todos os elementos, sem margem de juizo","C) Conveniencia e oportunidade","D) Discricionariedade","E) Merito administrativo"],g:"B",c:"Ato VINCULADO: a lei define todos os requisitos, sem margem de escolha ao agente (ex: licenca, aposentadoria). DISCRICIONARIO: ha juizo de conveniencia/oportunidade nos limites legais."},
{a:2023,r:"FCC/TCE-2023",q:"A desapropriacao e forma de intervencao do Estado na propriedade que:",o:["A) E gratuita","B) Transfere a propriedade mediante previa e justa indenizacao (em regra, em dinheiro)","C) Nao indeniza","D) E temporaria","E) Independe de utilidade publica"],g:"B",c:"DESAPROPRIACAO: o Estado retira compulsoriamente a propriedade por necessidade/utilidade publica ou interesse social, mediante PREVIA e JUSTA indenizacao (em dinheiro, em regra)."},
{a:2022,r:"FCC/PGE-2022",q:"O servidor estavel so perde o cargo por:",o:["A) Vontade do chefe","B) Sentenca judicial transitada em julgado, PAD ou avaliacao periodica de desempenho","C) Aposentadoria compulsoria apenas","D) Decreto","E) Portaria"],g:"B",c:"Art. 41 CF: o servidor estavel so perde o cargo por sentenca judicial transitada em julgado, processo administrativo (PAD com ampla defesa) ou avaliacao periodica de desempenho."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A licitacao tem como um de seus principios a:",o:["A) Pessoalidade","B) Isonomia (igualdade entre os licitantes)","C) Discricionariedade plena","D) Sigilo das propostas sempre","E) Informalidade"],g:"B",c:"A licitacao busca a ISONOMIA (tratamento igualitario aos licitantes) e a selecao da proposta mais vantajosa, alem do desenvolvimento nacional sustentavel."},
{a:2023,r:"FCC/TCE-2023",q:"A revogacao de ato administrativo NAO pode atingir:",o:["A) Atos discricionarios","B) Atos que ja geraram direitos adquiridos","C) Atos vigentes","D) Atos de merito","E) Atos validos"],g:"B",c:"A REVOGACAO (por conveniencia/oportunidade) nao pode atingir DIREITOS ADQUIRIDOS (Sumula 473 STF) nem atos vinculados, atos consumados ou ja apreciados por instancia superior."},
{a:2022,r:"FCC/PGE-2022",q:"O abuso de poder, na forma de DESVIO de poder, ocorre quando o agente:",o:["A) Age sem competencia","B) Atua dentro da competencia, mas com finalidade diversa do interesse publico","C) Erra na forma","D) Nao motiva","E) Atrasa o ato"],g:"B",c:"Abuso de poder: EXCESSO de poder (extrapola a competencia) ou DESVIO de poder/finalidade (age na competencia, mas com finalidade estranha ao interesse publico)."},
],
"DCI-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"A SV 24 do STF estabelece que crime material contra a ordem tributaria:",o:["A) Independe de lancamento","B) So se tipifica apos o lancamento definitivo do tributo","C) Prescreve em 3 anos","D) Inclui o mero inadimplemento","E) E acao penal privada"],g:"B",c:"SV 24: nao se tipifica crime material (art. 1, I-IV, Lei 8.137/90) antes do lancamento DEFINITIVO do tributo."},
{a:2022,r:"FCC/TRF-2022",q:"A lavagem de dinheiro (Lei 9.613/98) ocorre quando:",o:["A) Ha evasao acima de 5 milhoes","B) Bens de infracao penal sao ocultados/dissimulados","C) Empresa nao recolhe contribuicao","D) Funcionario aceita propina","E) Ha exportacao ficticia"],g:"B",c:"Lavagem: ocultar/dissimular origem de bens de INFRACAO PENAL. Modelo all crimes (Lei 12.683/2012). 3 fases: colocacao, dissimulacao, integracao."},
{a:2021,r:"FCC/PGE-2021",q:"A Lei Anticorrupcao (12.846/2013) responsabiliza:",o:["A) So pessoas fisicas","B) Pessoas juridicas objetivamente por atos contra a Adm. nacional e estrangeira","C) So servidores","D) PJ so se condenada criminalmente","E) So transnacionais"],g:"B",c:"Lei 12.846/2013: responsabilidade OBJETIVA das PJ por atos lesivos a Adm. Publica nacional ou estrangeira. Acordo de leniencia reduz sancoes."},
{a:2020,r:"FCC/ISS-2020",q:"No Direito Civil, a PRESCRICAO extingue:",o:["A) O direito material em si","B) A pretensao (direito de exigir judicialmente)","C) O negocio juridico","D) Contratos a termo","E) O direito potestativo"],g:"B",c:"PRESCRICAO: extingue a PRETENSAO (acao). O direito subjetivo persiste. DECADENCIA: extingue o proprio direito potestativo."},
{a:2019,r:"FCC/TRT-2019",q:"O crime FORMAL caracteriza-se por:",o:["A) Exigir resultado naturalistico","B) Consumar-se com a conduta, independente do resultado","C) So por funcionario publico","D) Exigir dois agentes","E) Depender de condicao objetiva"],g:"B",c:"Crime FORMAL: consuma-se com a CONDUTA, o resultado e mero exaurimento. MATERIAL exige resultado; mera conduta nao preve resultado."},
{a:2023,r:"FCC/TRT-2023",q:"O art. 2 da Lei 8.137/90 (crimes formais) inclui:",o:["A) Omitir informacao as autoridades","B) Falta de recolhimento de tributo descontado de terceiros","C) Fraudar a fiscalizacao","D) Negar nota fiscal","E) Alterar documento"],g:"B",c:"Art. 2 (formais): ex. deixar de recolher tributo descontado/cobrado de terceiros. Consuma com a conduta, sem exigir lancamento definitivo."},
{a:2022,r:"FCC/TCE-2022",q:"A DECADENCIA, no Direito Civil:",o:["A) Pode ser renunciada quando legal","B) Extingue o direito potestativo e, sendo legal, e irrenunciavel","C) Sempre se interrompe","D) So atinge a pretensao","E) Depende de acao judicial"],g:"B",c:"DECADENCIA legal: extingue o DIREITO potestativo, e IRRENUNCIAVEL e pode ser reconhecida de oficio."},
{a:2021,r:"FCC/PGE-2021",q:"No crime organizado (Lei 12.850/2013), a organizacao exige:",o:["A) 2 pessoas","B) 4 ou mais pessoas com estrutura ordenada e divisao de tarefas","C) 10 pessoas","D) Vinculo familiar","E) Apenas crimes tributarios"],g:"B",c:"Lei 12.850/2013: organizacao criminosa = 4+ pessoas, estrutura ordenada, divisao de tarefas, vantagem ilicita. Colaboracao premiada e instrumento."},
{a:2020,r:"FCC/ISS-2020",q:"No negocio juridico, o plano da VALIDADE exige:",o:["A) Apenas manifestacao de vontade","B) Agente capaz, objeto licito/possivel e forma prescrita ou nao defesa em lei","C) Registro em cartorio","D) Eficacia imediata","E) Ausencia de condicao"],g:"B",c:"Validade (art. 104 CC): agente capaz + objeto licito, possivel, determinado + forma prescrita ou nao defesa em lei."},
{a:2019,r:"FCC/TRF-2019",q:"O peculato (crime contra a Adm. Publica) e praticado por:",o:["A) Qualquer particular","B) Funcionario publico que se apropria de bem de que tem posse em razao do cargo","C) So por agentes politicos","D) Empresas","E) So em licitacoes"],g:"B",c:"PECULATO: funcionario publico apropria-se de dinheiro/bem de que tem posse em razao do cargo (crime proprio)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No crime de excesso de exacao (art. 316, par.1 CP), o funcionario:",o:["A) Deixa de cobrar tributo","B) Exige tributo que sabe indevido ou cobra de modo vexatorio","C) Apropria-se de verba","D) Falsifica documento","E) Frauda licitacao"],g:"B",c:"Excesso de exacao: o funcionario exige tributo/contribuicao que sabe indevido, ou, devido, emprega meio vexatorio/gravoso nao autorizado em lei."},
{a:2023,r:"FCC/Fiscal-2023",q:"A Sumula Vinculante 24 NAO se aplica aos crimes:",o:["A) Materiais do art. 1, I a IV da Lei 8.137/90","B) Formais (art. 2), que independem do lancamento definitivo","C) De sonegacao","D) De supressao de tributo","E) Contra a ordem tributaria em geral"],g:"B",c:"SV 24 condiciona ao lancamento definitivo apenas os crimes MATERIAIS (art. 1, I-IV). Os FORMAIS (art. 2) consumam-se com a conduta, independentemente do lancamento."},
{a:2022,r:"FCC/PGE-2022",q:"Na lavagem de dinheiro, a fase de 'ocultacao' (layering) busca:",o:["A) Inserir o dinheiro no sistema","B) Distanciar os recursos da origem por meio de varias transacoes","C) Reintegrar o dinheiro a economia","D) Pagar tributos","E) Declarar a renda"],g:"B",c:"Lavagem em 3 fases: COLOCACAO (introducao), OCULTACAO/layering (varias operacoes para esconder a origem) e INTEGRACAO (retorno aparentemente licito)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O peculato culposo (art. 312, par.2 CP):",o:["A) Nunca admite reparacao","B) Extingue a punibilidade se o dano for reparado antes da sentenca irrecorrivel","C) E inafiancavel","D) Independe de culpa","E) So ocorre com dolo"],g:"B",c:"Peculato culposo: se a reparacao do dano ocorre ANTES da sentenca irrecorrivel, extingue-se a punibilidade; se posterior, reduz a pena pela metade."},
{a:2023,r:"FCC/Fiscal-2023",q:"Corrupcao passiva (art. 317 CP) consuma-se quando o funcionario:",o:["A) Pratica o ato de oficio","B) Solicita ou recebe vantagem indevida, ou aceita promessa","C) Apenas pensa em receber","D) Comunica o superior","E) Recusa a propina"],g:"B",c:"Corrupcao passiva consuma-se com SOLICITAR, RECEBER ou ACEITAR PROMESSA de vantagem indevida em razao da funcao, mesmo sem praticar o ato."},
{a:2022,r:"FCC/PGE-2022",q:"A prescricao penal, em regra, comeca a correr:",o:["A) Da denuncia","B) Do dia em que o crime se consumou","C) Da sentenca","D) Do inquerito","E) Do transito em julgado"],g:"B",c:"Art. 111 CP: a prescricao da pretensao punitiva, em regra, comeca a correr do dia da CONSUMACAO do crime (ou cessacao, nos permanentes)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No Direito Civil, a fraude contra credores e:",o:["A) Um ato nulo","B) Um vicio social que torna o negocio anulavel","C) Erro","D) Coacao fisica","E) Simulacao"],g:"B",c:"Fraude contra credores: vicio SOCIAL do negocio juridico (devedor insolvente dilapida patrimonio em prejuizo do credor); o negocio e ANULAVEL (acao pauliana)."},
{a:2023,r:"FCC/Fiscal-2023",q:"O contrabando difere do descaminho porque o contrabando envolve:",o:["A) Tributos nao pagos","B) Mercadoria proibida (ilicita)","C) Importacao regular","D) Exportacao isenta","E) Apenas multa"],g:"B",c:"DESCAMINHO (art. 334): elidir tributo de mercadoria PERMITIDA. CONTRABANDO (art. 334-A): importar/exportar mercadoria PROIBIDA."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A apropriacao indebita previdenciaria (art. 168-A CP) consiste em:",o:["A) Nao declarar tributo","B) Deixar de repassar a previdencia contribuicoes recolhidas dos segurados","C) Fraudar nota fiscal","D) Corromper agente","E) Sonegar IR"],g:"B",c:"Art. 168-A CP: deixar de REPASSAR a previdencia as contribuicoes descontadas/recolhidas dos contribuintes no prazo legal (crime omissivo proprio)."},
{a:2023,r:"FCC/Fiscal-2023",q:"No concurso de pessoas, a participacao de menor importancia:",o:["A) Aumenta a pena","B) Pode reduzir a pena de 1/6 a 1/3","C) Isenta de pena","D) Dobra a pena","E) E irrelevante"],g:"B",c:"Art. 29, par.1 CP: se a participacao for de MENOR IMPORTANCIA, a pena pode ser diminuida de 1/6 a 1/3."},
{a:2022,r:"FCC/PGE-2022",q:"A acao penal nos crimes contra a ordem tributaria e:",o:["A) Privada","B) Publica incondicionada (titularidade do MP)","C) Condicionada a representacao","D) Da vitima","E) Subsidiaria"],g:"B",c:"Os crimes contra a ordem tributaria (Lei 8.137) sao de acao penal PUBLICA INCONDICIONADA: o MP age independentemente de provocacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O erro de tipo (art. 20 CP):",o:["A) Aumenta a pena","B) Exclui o dolo (e, se inevitavel, tambem a culpa)","C) E irrelevante","D) E causa de aumento","E) Configura crime doloso"],g:"B",c:"ERRO DE TIPO: falsa percepcao da realidade sobre elemento do tipo. EXCLUI O DOLO; se inevitavel, exclui tambem a culpa; se evitavel, pune-se a titulo de culpa (se prevista)."},
{a:2023,r:"FCC/Fiscal-2023",q:"A simulacao, no Direito Civil, torna o negocio juridico:",o:["A) Anulavel","B) Nulo (art. 167 CC)","C) Valido","D) Ineficaz apenas","E) Inexistente"],g:"B",c:"Art. 167 CC: a SIMULACAO torna o negocio juridico NULO (vicio social), mas subsiste o que se dissimulou se valido na substancia e forma."},
{a:2022,r:"FCC/PGE-2022",q:"A reincidencia, no Direito Penal, ocorre quando o agente:",o:["A) Comete o primeiro crime","B) Pratica novo crime apos transito em julgado de condenacao anterior","C) Confessa","D) Repara o dano","E) E primario"],g:"B",c:"REINCIDENCIA (art. 63 CP): cometer NOVO crime depois do TRANSITO EM JULGADO de sentenca condenatoria por crime anterior (no Brasil ou exterior). Agrava a pena."},
],
"DFI-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"O limite de despesa com pessoal para os ESTADOS (LRF) e:",o:["A) 50% da RCL; Executivo 40,9%","B) 60% da RCL; Executivo 49%","C) 60% da RCL; Executivo 54%","D) 65%; Executivo 49%","E) 60%; Executivo 45%"],g:"B",c:"Estados=60% da RCL, Executivo=49% (Leg+TC 3%, Jud 6%, MP 2%). Uniao=50/40,9. Municipios=60/54."},
{a:2022,r:"FCC/TCE-2022",q:"A limitacao de empenho (art. 9 LRF) e acionada:",o:["A) No inicio do exercicio","B) Bimestralmente, quando a receita nao comporta as metas de resultado primario","C) So por lei","D) Em qualquer despesa","E) Pelo TCU"],g:"B",c:"Art. 9: bimestralmente, se a receita nao comportar as metas fiscais -> contingenciamento. Nao atinge despesas constitucionalmente obrigatorias."},
{a:2021,r:"FCC/SEFAZ-2021",q:"O Resultado Primario e:",o:["A) Receitas totais - despesas totais","B) Receitas nao financeiras - despesas nao financeiras (sem juros)","C) Resultado nominal + correcao","D) Receita tributaria - pessoal","E) Superavit / PIB"],g:"B",c:"PRIMARIO: receitas nao financeiras - despesas nao financeiras (exclui juros). Mede o esforco fiscal. NOMINAL=primario - juros."},
{a:2020,r:"FCC/TRT-2020",q:"O limite PRUDENCIAL de despesa com pessoal corresponde a:",o:["A) 90% do limite","B) 95% do limite legal","C) 100%","D) 50%","E) 60% da RCL"],g:"B",c:"Limite prudencial=95% do limite legal. Atingido, vedam-se aumentos, criacao de cargos, horas extras (medidas preventivas)."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O RGF (Relatorio de Gestao Fiscal) e publicado:",o:["A) Mensalmente","B) Bimestralmente","C) Quadrimestralmente","D) Anualmente","E) Semestralmente"],g:"C",c:"RGF=QUADRIMESTRAL. RREO (Relatorio Resumido de Execucao Orcamentaria)=BIMESTRAL."},
{a:2023,r:"FCC/TRT-2023",q:"O art. 42 da LRF veda, nos 2 ultimos quadrimestres do mandato:",o:["A) Pagar servidores","B) Contrair obrigacao de despesa sem disponibilidade de caixa","C) Realizar licitacoes","D) Arrecadar tributos","E) Editar a LDO"],g:"B",c:"Art. 42: vedado contrair, nos 2 ultimos quadrimestres, obrigacao de despesa que nao possa ser paga no mandato sem disponibilidade de caixa."},
{a:2022,r:"FCC/TCE-2022",q:"O Resultado NOMINAL difere do PRIMARIO porque:",o:["A) Inclui os juros nominais da divida","B) Exclui as receitas","C) So considera o PIB","D) Ignora as despesas","E) E sempre positivo"],g:"A",c:"NOMINAL=Primario - Juros nominais. Mede a variacao total da divida. Pode haver superavit primario e deficit nominal."},
{a:2021,r:"FCC/SEFAZ-2021",q:"A regra de ouro (CF/LRF) veda:",o:["A) Qualquer endividamento","B) Operacoes de credito que superem as despesas de capital","C) Pagar juros","D) Investir","E) Arrecadar acima da meta"],g:"B",c:"Regra de ouro (art. 167, III CF): veda operacoes de credito que excedam as despesas de capital (evita financiar custeio com divida)."},
{a:2020,r:"FCC/TRT-2020",q:"A RCL (Receita Corrente Liquida) e a base para:",o:["A) Calcular o PIB","B) Os limites de pessoal e divida na LRF","C) A inflacao","D) O cambio","E) A taxa Selic"],g:"B",c:"RCL=base de calculo dos limites da LRF (pessoal, divida, garantias). Soma das receitas correntes com deducoes legais."},
{a:2019,r:"FCC/SEFAZ-2019",q:"A ARO (operacao de credito por antecipacao de receita):",o:["A) E proibida","B) Destina-se a atender insuficiencia de caixa e deve ser quitada ate 10/12","C) Nao tem prazo","D) E permanente","E) Independe de autorizacao"],g:"B",c:"ARO: cobre insuficiencia de caixa no exercicio, liquidada ate 10 de dezembro. Vedada no ultimo ano de mandato."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na LRF, despesa obrigatoria de carater continuado (DOCC) e a que:",o:["A) Dura menos de 1 ano","B) Fixa obrigacao legal de execucao por periodo superior a 2 exercicios","C) E facultativa","D) E de capital","E) Nao tem fonte"],g:"B",c:"Art. 17 LRF: DOCC = despesa corrente derivada de lei/ato que fixe obrigacao por mais de 2 exercicios; exige estimativa de impacto e compensacao."},
{a:2023,r:"FCC/TCE-2023",q:"A Receita Corrente Liquida (RCL) e apurada somando as receitas dos:",o:["A) Ultimos 6 meses","B) Mes de referencia e os 11 anteriores (12 meses)","C) Ano civil","D) Mandato","E) Quadrimestre"],g:"B",c:"RCL = somatorio das receitas correntes do mes de referencia + os 11 meses anteriores, com as deducoes legais (periodo movel de 12 meses)."},
{a:2022,r:"FCC/PGE-2022",q:"Atingido o limite de despesa com pessoal, se nao houver reconducao em 2 quadrimestres:",o:["A) Nada ocorre","B) Aplicam-se vedacoes como suspensao de transferencias voluntarias e contratacao de operacoes de credito","C) O ente e extinto","D) Aumenta-se a RCL","E) Suspende-se a LOA"],g:"B",c:"Ultrapassado o limite e nao recomposto nos 2 quadrimestres seguintes, ha vedacoes: transferencias voluntarias, operacoes de credito (salvo refinanciamento) e garantias."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O Anexo de Metas Fiscais integra a:",o:["A) LOA","B) LDO","C) PPA","D) CF","E) Lei de crimes fiscais"],g:"B",c:"O Anexo de Metas Fiscais (receitas, despesas, resultados nominal e primario, divida) integra a LDO (art. 4, par.1 LRF)."},
{a:2023,r:"FCC/TCE-2023",q:"A 'regra de ouro' constitucional veda:",o:["A) Deficit primario","B) Operacoes de credito que excedam as despesas de capital","C) Superavit nominal","D) Endividamento externo","E) Pagamento de juros"],g:"B",c:"Art. 167, III CF (regra de ouro): proibe operacoes de credito que superem as despesas de capital, salvo creditos suplementares/especiais autorizados por maioria absoluta."},
{a:2022,r:"FCC/PGE-2022",q:"A reserva de contingencia na LOA destina-se a:",o:["A) Pagar pessoal","B) Atender passivos contingentes e riscos/eventos fiscais imprevistos","C) Investimentos","D) Amortizar divida","E) Distribuir a estados"],g:"B",c:"Reserva de contingencia (art. 5, III LRF): definida na LOA com base na RCL, para passivos contingentes e outros riscos/eventos fiscais imprevistos."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A transferencia voluntaria, segundo a LRF, exige do ente recebedor:",o:["A) Apenas o pedido","B) Comprovacao de regularidade (tributos, contas, limites) e contrapartida","C) Nada","D) Autorizacao do TCU","E) Operacao de credito"],g:"B",c:"Art. 25 LRF: transferencia voluntaria exige do beneficiario regularidade fiscal/previdenciaria, observancia dos limites e previsao de contrapartida no orcamento."},
{a:2023,r:"FCC/TCE-2023",q:"O resultado primario superavitario contribui para:",o:["A) Aumentar a divida","B) Reduzir a necessidade de financiamento e estabilizar/abater a divida","C) Elevar os juros","D) Reduzir a RCL","E) Aumentar o deficit nominal sempre"],g:"B",c:"Superavit primario reduz a necessidade de novo endividamento e ajuda a abater a divida; se superar os juros, a divida liquida cai."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A LRF veda ao titular de Poder, nos ultimos 180 dias do mandato:",o:["A) Pagar fornecedores","B) Aumentar despesa com pessoal (ato que resulte aumento)","C) Arrecadar","D) Empenhar despesas correntes","E) Editar a LDO"],g:"B",c:"Art. 21, PU LRF: e NULO o ato que resulte aumento de despesa com pessoal expedido nos 180 dias anteriores ao fim do mandato do titular do Poder/orgao."},
{a:2023,r:"FCC/Fiscal-2023",q:"O limite de gastos com pessoal para o Poder Judiciario estadual e de:",o:["A) 49% da RCL","B) 6% da RCL","C) 3% da RCL","D) 2% da RCL","E) 60% da RCL"],g:"B",c:"Reparticao do limite de pessoal nos Estados (60% total): Executivo 49%, Legislativo+TC 3%, JUDICIARIO 6%, Ministerio Publico 2%."},
{a:2022,r:"FCC/PGE-2022",q:"A operacao de credito por antecipacao de receita orcamentaria (ARO):",o:["A) Pode ser feita no ultimo ano de mandato","B) E vedada no ultimo ano de mandato do chefe do Executivo","C) Nao tem prazo de quitacao","D) Independe de juros","E) E permanente"],g:"B",c:"Art. 38 LRF: a ARO deve ser liquidada ate 10/dez do mesmo exercicio e e VEDADA no ULTIMO ANO de mandato do chefe do Poder Executivo."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A renuncia de receita (LRF) exige:",o:["A) Apenas decreto","B) Estimativa do impacto e medidas de compensacao ou demonstracao de que nao afeta as metas","C) Autorizacao do TCU","D) Aprovacao popular","E) Nada"],g:"B",c:"Art. 14 LRF: a concessao de beneficio que renuncie receita exige estimativa de impacto orcamentario-financeiro e medidas de COMPENSACAO (ou demonstracao de nao afetar as metas)."},
{a:2023,r:"FCC/Fiscal-2023",q:"O Relatorio Resumido da Execucao Orcamentaria (RREO) e publicado:",o:["A) Anualmente","B) Bimestralmente, ate 30 dias apos o bimestre","C) Quadrimestralmente","D) Mensalmente","E) Semestralmente"],g:"B",c:"RREO: BIMESTRAL, publicado em ate 30 dias apos o encerramento do bimestre (art. 52-53 LRF). O RGF e quadrimestral."},
{a:2022,r:"FCC/PGE-2022",q:"A despesa total com pessoal abrange:",o:["A) Apenas vencimentos","B) Vencimentos, vantagens, encargos sociais, aposentadorias e pensoes","C) So aposentadorias","D) Material de consumo","E) Investimentos"],g:"B",c:"Art. 18 LRF: despesa com pessoal = somatorio de vencimentos, vantagens, subsidios, proventos de aposentadoria, pensoes, encargos sociais e contribuicoes."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A meta de resultado primario e estabelecida:",o:["A) Na LOA","B) No Anexo de Metas Fiscais da LDO","C) No PPA","D) Na CF","E) Em decreto"],g:"B",c:"A meta de resultado primario consta do ANEXO DE METAS FISCAIS da LDO (art. 4 LRF), orientando a execucao orcamentaria do exercicio."},
{a:2023,r:"FCC/Fiscal-2023",q:"Se a despesa com pessoal exceder 95% do limite (prudencial), veda-se:",o:["A) Nada","B) Concessao de vantagem, criacao de cargo, contratacao e horas extras","C) Pagamento de salarios","D) Arrecadacao","E) Empenho de custeio"],g:"B",c:"Atingido o limite PRUDENCIAL (95% do limite), vedam-se: aumento/reajuste, criacao de cargo, alteracao de estrutura que eleve gasto, contratacao (salvo reposicao) e horas extras (com ressalvas)."},
{a:2022,r:"FCC/PGE-2022",q:"O resultado nominal mede:",o:["A) O esforco fiscal sem juros","B) A variacao da divida fiscal liquida (inclui juros)","C) So as receitas","D) O PIB","E) O superavit primario"],g:"B",c:"Resultado NOMINAL = variacao da divida fiscal liquida no periodo = resultado primario - juros nominais. Mede o endividamento total."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A transparencia na gestao fiscal (LRF) inclui:",o:["A) Sigilo das contas","B) Divulgacao ampla, inclusive em meios eletronicos, e incentivo a participacao popular","C) Restricao de acesso","D) Publicacao so anual","E) Apenas relatorio interno"],g:"B",c:"Art. 48 LRF: a transparencia fiscal preve divulgacao ampla (inclusive internet/portais), versoes simplificadas e incentivo a participacao popular em audiencias publicas."},
],
"DFI-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Os estagios da DESPESA (Lei 4.320) sao:",o:["A) Previsao, lancamento, arrecadacao, recolhimento","B) Fixacao, empenho, liquidacao, pagamento","C) Programacao, reserva, empenho, quitacao","D) Dotacao, contingenciamento, empenho","E) Orcamentacao, cobranca, recebimento"],g:"B",c:"Despesa: FIXACAO, EMPENHO (art. 58), LIQUIDACAO (art. 63), PAGAMENTO (art. 64)."},
{a:2022,r:"FCC/TCE-2022",q:"Creditos EXTRAORDINARIOS sao abertos:",o:["A) Por lei especifica","B) Por decreto do Executivo para despesas urgentes e improvistos, sem fonte previa","C) So com autorizacao legislativa previa","D) Para reforcar dotacoes","E) Com indicacao de fonte obrigatoria"],g:"B",c:"EXTRAORDINARIOS: urgentes/improvistos (guerra, calamidade) -> decreto do Executivo, comunicacao posterior, SEM indicacao previa de fonte."},
{a:2021,r:"FCC/PGE-2021",q:"A LDO tem por finalidade:",o:["A) Autorizar despesas do exercicio","B) Orientar a elaboracao da LOA, metas e riscos fiscais","C) Detalhar o PPA","D) Criar fundos","E) Estabelecer prioridades sem conteudo fiscal"],g:"B",c:"LDO: orienta a LOA, fixa metas fiscais (anexo de metas) e riscos fiscais, criterios de limitacao de empenho. PPA=longo prazo; LOA=autoriza despesas."},
{a:2020,r:"FCC/TRT-2020",q:"O principio orcamentario da UNIVERSALIDADE exige que:",o:["A) O orcamento dure 1 ano","B) Todas as receitas e despesas constem do orcamento","C) Haja um unico orcamento","D) Valores liquidos","E) Especificacao detalhada"],g:"B",c:"UNIVERSALIDADE: o orcamento deve conter TODAS as receitas e despesas. ANUALIDADE=1 ano; UNIDADE=orcamento unico."},
{a:2019,r:"FCC/SEFAZ-2019",q:"Creditos SUPLEMENTARES destinam-se a:",o:["A) Novas dotacoes","B) Reforco de dotacao orcamentaria existente","C) Despesas urgentes","D) Calamidade","E) Guerra"],g:"B",c:"SUPLEMENTARES: reforco de dotacao JA existente (a LOA pode ja autorizar). ESPECIAIS: novas dotacoes. EXTRAORDINARIOS: urgentes."},
{a:2023,r:"FCC/TRT-2023",q:"O EMPENHO da despesa (art. 58):",o:["A) Verifica o direito do credor","B) Cria para o Estado obrigacao de pagamento","C) Entrega o recurso ao credor","D) Fixa a dotacao","E) Arrecada a receita"],g:"B",c:"EMPENHO: ato que cria para o Estado obrigacao de pagamento. LIQUIDACAO verifica o direito; PAGAMENTO entrega o recurso."},
{a:2022,r:"FCC/TCE-2022",q:"Sao receitas de CAPITAL:",o:["A) Receita tributaria","B) Operacoes de credito, alienacao de bens, transferencias de capital","C) Receita patrimonial","D) Receita de servicos","E) Contribuicoes"],g:"B",c:"Receitas de CAPITAL: operacoes de credito, alienacao de bens, amortizacao de emprestimos, transferencias de capital. Tributaria=corrente."},
{a:2021,r:"FCC/PGE-2021",q:"O principio da EXCLUSIVIDADE orcamentaria significa que:",o:["A) Ha um unico orcamento","B) A LOA nao contem materia estranha a fixacao da despesa e previsao da receita","C) O orcamento e anual","D) Valores brutos","E) Receita vinculada"],g:"B",c:"EXCLUSIVIDADE: a LOA so trata de receita e despesa (excecao: autorizacao de credito suplementar e operacoes de credito/ARO)."},
{a:2020,r:"FCC/TRT-2020",q:"A LIQUIDACAO da despesa (art. 63) consiste em:",o:["A) Criar a obrigacao","B) Verificar o direito do credor com base nos titulos e documentos","C) Pagar ao credor","D) Fixar dotacao","E) Empenhar"],g:"B",c:"LIQUIDACAO: verificacao do direito do credor (apuracao da origem, importancia e a quem pagar), com base em documentos comprobatorios."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O PPA (Plano Plurianual) tem vigencia de:",o:["A) 1 ano","B) 2 anos","C) 4 anos","D) 5 anos","E) 8 anos"],g:"C",c:"PPA: 4 anos (do 2o ano de um mandato ao 1o do mandato seguinte). Estabelece diretrizes, objetivos e metas regionalizadas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O credito ESPECIAL destina-se a:",o:["A) Reforcar dotacao existente","B) Despesas para as quais nao haja dotacao orcamentaria especifica","C) Guerra e calamidade","D) Pagar pessoal","E) Amortizar divida"],g:"B",c:"Credito ESPECIAL: para despesas sem dotacao especifica (cria nova rubrica), depende de autorizacao legislativa e indicacao de fonte."},
{a:2023,r:"FCC/Fiscal-2023",q:"O principio da NAO AFETACAO da receita de impostos veda:",o:["A) Cobrar impostos","B) Vincular receita de impostos a orgao, fundo ou despesa, salvo excecoes constitucionais","C) Arrecadar taxas","D) Criar fundos","E) Transferir a estados"],g:"B",c:"Art. 167, IV CF: veda a vinculacao de receita de IMPOSTOS, salvo excecoes (saude, educacao, FPE/FPM, garantias a Uniao etc.). Taxas e contribuicoes podem ser vinculadas."},
{a:2022,r:"FCC/PGE-2022",q:"O orcamento-programa caracteriza-se por:",o:["A) Listar so despesas por objeto","B) Vincular recursos a programas, objetivos e metas (enfase em resultados)","C) Ser anual apenas","D) Nao ter planejamento","E) Ser incremental"],g:"B",c:"Orcamento-PROGRAMA: organiza os gastos por programas/acoes com objetivos e metas, integrando planejamento e orcamento (base do PPA-LDO-LOA brasileiro)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A vedacao do estorno de verbas (art. 167, VI CF) impede:",o:["A) Empenhar despesas","B) Transpor, remanejar ou transferir recursos de uma categoria para outra sem autorizacao legislativa","C) Arrecadar","D) Pagar credores","E) Abrir creditos extraordinarios"],g:"B",c:"Art. 167, VI: veda a transposicao, remanejamento ou transferencia de recursos de uma categoria de programacao para outra SEM previa autorizacao legislativa."},
{a:2023,r:"FCC/Fiscal-2023",q:"O ciclo orcamentario compreende as fases de:",o:["A) So execucao","B) Elaboracao, aprovacao (apreciacao legislativa), execucao e controle/avaliacao","C) Apenas planejamento","D) So controle","E) Empenho e pagamento"],g:"B",c:"Ciclo orcamentario: ELABORACAO (Executivo) -> APRECIACAO/APROVACAO (Legislativo) -> EXECUCAO -> CONTROLE e avaliacao."},
{a:2022,r:"FCC/PGE-2022",q:"As transferencias constitucionais (FPE, FPM) sao:",o:["A) Voluntarias","B) Obrigatorias, decorrentes de mandamento constitucional","C) Facultativas","D) Convenios","E) Operacoes de credito"],g:"B",c:"FPE/FPM e demais repartições de receitas sao transferencias OBRIGATORIAS (constitucionais), distintas das transferencias VOLUNTARIAS (convenios)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O principio do EQUILIBRIO orcamentario preconiza:",o:["A) Mais despesa que receita","B) Equivalencia entre receitas e despesas previstas","C) Superavit obrigatorio","D) Deficit permanente","E) Ausencia de planejamento"],g:"B",c:"Principio do EQUILIBRIO: as despesas fixadas devem guardar equivalencia com as receitas previstas, reforcado pela LRF (gestao fiscal responsavel)."},
{a:2023,r:"FCC/Fiscal-2023",q:"A despesa de capital denominada 'inversao financeira' inclui:",o:["A) Pagamento de pessoal","B) Aquisicao de imoveis ja em uso ou de titulos representativos de capital","C) Juros da divida","D) Material de consumo","E) Diarias"],g:"B",c:"INVERSOES FINANCEIRAS: aquisicao de imoveis/bens ja em utilizacao, de participacoes acionarias, concessao de emprestimos. Diferente de INVESTIMENTOS (bens novos)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O credito SUPLEMENTAR pode ser autorizado:",o:["A) Apenas por lei especifica","B) Na propria LOA (ate certo limite), aberto por decreto do Executivo","C) So por MP","D) Por convenio","E) Por resolucao"],g:"B",c:"O credito SUPLEMENTAR (reforco de dotacao) pode ser previamente autorizado na LOA ate um limite/percentual, sendo aberto por DECRETO do Executivo dentro desse limite."},
{a:2023,r:"FCC/Fiscal-2023",q:"O principio orcamentario da PROGRAMACAO exige que o orcamento:",o:["A) Seja so uma lista de gastos","B) Contenha objetivos e metas, vinculando recursos a programas","C) Seja anual apenas","D) Tenha valores liquidos","E) Seja unico"],g:"B",c:"Principio da PROGRAMACAO: o orcamento deve expressar objetivos, metas e programas (orcamento-programa), nao apenas autorizar gastos por objeto."},
{a:2022,r:"FCC/PGE-2022",q:"Receita extraorcamentaria caracteriza-se por:",o:["A) Constar da LOA","B) Ingressos transitorios que nao pertencem ao ente (ex: cauções, depositos)","C) Ser tributo","D) Ser permanente","E) Financiar despesas"],g:"B",c:"Receita EXTRAORCAMENTARIA: ingressos transitorios (cauções, depositos, retencoes) que NAO pertencem definitivamente ao ente e serao devolvidos; nao constam da LOA."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A LOA compreende os orcamentos:",o:["A) Apenas fiscal","B) Fiscal, da seguridade social e de investimento das estatais","C) So da seguridade","D) Municipal apenas","E) De capital"],g:"B",c:"Art. 165, par.5 CF: a LOA compreende o orcamento FISCAL, o da SEGURIDADE SOCIAL e o de INVESTIMENTO das empresas estatais."},
{a:2023,r:"FCC/Fiscal-2023",q:"O estagio do empenho pode ser dispensado:",o:["A) Sempre","B) Em casos previstos em lei especifica (excecao), nao como regra","C) Nas despesas de capital","D) No pagamento","E) Na liquidacao"],g:"B",c:"Em regra o empenho e obrigatorio (art. 60 Lei 4.320: e vedada despesa sem empenho). Apenas casos especificos previstos em lei admitem dispensa/empenho por estimativa."},
{a:2022,r:"FCC/PGE-2022",q:"A despesa de exercicios anteriores (DEA) refere-se a:",o:["A) Despesa do ano corrente","B) Despesas de exercicios encerrados, nao processadas na epoca propria, pagas a conta de dotacao do exercicio vigente","C) Restos a pagar","D) Investimento","E) Receita"],g:"B",c:"DEA: dividas de exercicios ENCERRADOS, que nao foram processadas na epoca propria, reconhecidas e pagas a conta de dotacao especifica do orcamento vigente."},
],
"CGP-1":[
{a:2023,r:"FCC/TCE-2023",q:"Os estagios da RECEITA orcamentaria (MCASP) sao:",o:["A) Empenho, liquidacao, pagamento, recolhimento","B) Previsao, lancamento, arrecadacao, recolhimento","C) Fixacao, empenho, arrecadacao","D) Programacao, reserva, movimentacao","E) Orcamentacao, cobranca, deposito"],g:"B",c:"Receita: PREVISAO (LOA), LANCAMENTO (art. 53), ARRECADACAO (banco), RECOLHIMENTO (Tesouro/conta unica)."},
{a:2022,r:"FCC/TCE-2022",q:"Os Restos a Pagar PROCESSADOS sao aqueles com:",o:["A) Apenas empenho","B) Empenho e liquidacao realizados (direito verificado)","C) Pagamento efetuado","D) So dotacao","E) Liquidacao cancelada"],g:"B",c:"RP PROCESSADOS: empenho + liquidacao feitos -> Estado deve pagar. NAO PROCESSADOS: so empenho (liquidacao pendente)."},
{a:2021,r:"FCC/PGE-2021",q:"As caracteristicas qualitativas FUNDAMENTAIS (NBC TSP) sao:",o:["A) Comparabilidade e verificabilidade","B) Relevancia e representacao fidedigna","C) Tempestividade e compreensibilidade","D) Objetividade e consistencia","E) Neutralidade e prudencia"],g:"B",c:"FUNDAMENTAIS: relevancia + representacao fidedigna. DE MELHORIA: comparabilidade, verificabilidade, tempestividade, compreensibilidade."},
{a:2020,r:"FCC/TCM-2020",q:"No PCASP, a classe que registra Variacoes Patrimoniais Diminutivas (VPD) e:",o:["A) Classe 1 (Ativo)","B) Classe 3 (VPD)","C) Classe 4 (VPA)","D) Classe 2 (Passivo)","E) Classe 5"],g:"B",c:"PCASP: 1-Ativo, 2-Passivo, 3-VPD (diminutivas), 4-VPA (aumentativas), 5/6-controles, 7/8-especificos."},
{a:2019,r:"FCC/SEFAZ-2019",q:"O EMPENHO ESTIMATIVO e utilizado quando:",o:["A) O valor e exato","B) Nao se conhece previamente o valor exato (ex: agua, energia)","C) E contrato parcelado","D) Ha calamidade","E) E despesa de capital"],g:"B",c:"EMPENHO ESTIMATIVO: valor nao exatamente determinado (servicos continuados como agua/energia). ORDINARIO=valor certo; GLOBAL=parcelado."},
{a:2023,r:"FCC/TRT-2023",q:"A Demonstracao das Variacoes Patrimoniais (DVP) evidencia:",o:["A) Apenas o orcamento","B) As variacoes quantitativas e qualitativas do patrimonio","C) Os restos a pagar","D) A divida ativa","E) O fluxo de caixa"],g:"B",c:"DVP: variacoes patrimoniais aumentativas (VPA) e diminutivas (VPD), apurando o resultado patrimonial do periodo."},
{a:2022,r:"FCC/TCE-2022",q:"O regime contabil adotado para a RECEITA no setor publico (Lei 4.320) e:",o:["A) Competencia integral","B) Caixa para a receita","C) Competencia para receita e despesa","D) Misto invertido","E) So competencia para despesa"],g:"B",c:"Lei 4.320: regime de CAIXA para a receita (reconhecida na arrecadacao) e COMPETENCIA para a despesa (empenhada). MCASP avanca para competencia patrimonial."},
{a:2021,r:"FCC/PGE-2021",q:"O RECOLHIMENTO, ultimo estagio da receita, consiste em:",o:["A) Prever na LOA","B) Entregar os valores arrecadados ao Tesouro (conta unica)","C) Lancar o credito","D) Pagar o credor","E) Empenhar"],g:"B",c:"RECOLHIMENTO: transferencia dos valores arrecadados pelos agentes para a conta unica do Tesouro (principio da unidade de tesouraria)."},
{a:2020,r:"FCC/TCM-2020",q:"Os Restos a Pagar sao inscritos em:",o:["A) 1 de janeiro","B) 31 de dezembro (despesas empenhadas e nao pagas)","C) 30 de junho","D) Qualquer data","E) Inicio do mandato"],g:"B",c:"RP: despesas empenhadas e nao pagas ate 31/12. Processados (liquidados) e nao processados (so empenhados)."},
{a:2019,r:"FCC/SEFAZ-2019",q:"A NBC TSP 01 trata de:",o:["A) Estoques","B) Apresentacao das demonstracoes contabeis","C) Receita de tributos","D) Ativo imobilizado","E) Provisoes"],g:"B",c:"NBC TSP 01: apresentacao das demonstracoes contabeis (equivale a IPSAS 1): BP, DVP, DFC, DMPL e notas explicativas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No regime orcamentario da Lei 4.320, pertencem ao exercicio financeiro:",o:["A) As receitas arrecadadas e as despesas legalmente empenhadas","B) So o que foi pago","C) Apenas a previsao","D) Receitas e despesas de competencia","E) Somente os restos a pagar"],g:"A",c:"Art. 35 Lei 4.320: pertencem ao exercicio as RECEITAS nele arrecadadas (caixa) e as DESPESAS nele legalmente EMPENHADAS (compromisso)."},
{a:2023,r:"FCC/TCE-2023",q:"A divida ativa tributaria e inscrita apos:",o:["A) O fato gerador","B) Esgotado o prazo de pagamento e apurada a liquidez e certeza do credito","C) O empenho","D) A previsao na LOA","E) O lancamento provisorio"],g:"B",c:"A inscricao em divida ativa ocorre apos esgotado o prazo para pagamento, conferindo liquidez e certeza ao credito e gerando a CDA (titulo executivo)."},
{a:2022,r:"FCC/TCM-2022",q:"No PCASP, a conta 'Variacao Patrimonial Aumentativa' representa:",o:["A) Reducao do patrimonio","B) Aumento da situacao liquida (ex: receita de impostos)","C) Despesa orcamentaria","D) Passivo","E) Restos a pagar"],g:"B",c:"VPA (classe 4): aumentos da situacao patrimonial liquida (impostos, contribuicoes, exploracao de bens) - regime de competencia patrimonial."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A despesa publica, quanto a categoria economica, divide-se em:",o:["A) Tributaria e patrimonial","B) Correntes e de capital","C) Ordinaria e extraordinaria","D) Fixa e variavel","E) Direta e indireta"],g:"B",c:"Despesas: CORRENTES (custeio, pessoal, juros) e de CAPITAL (investimentos, inversoes financeiras, amortizacao da divida). Igual classificacao para receitas."},
{a:2023,r:"FCC/TCE-2023",q:"O superavit financeiro apurado no Balanco Patrimonial:",o:["A) Nao pode ser usado","B) E fonte para abertura de creditos adicionais","C) E despesa","D) Compoe a divida","E) E receita tributaria"],g:"B",c:"Art. 43 Lei 4.320: o superavit financeiro (ativo financeiro - passivo financeiro) e fonte para abertura de creditos suplementares e especiais."},
{a:2022,r:"FCC/TCM-2022",q:"A natureza da receita orcamentaria por categoria economica inclui:",o:["A) Receitas correntes e de capital","B) Receitas fixas","C) Receitas extraordinarias","D) Receitas vinculadas apenas","E) Receitas diretas"],g:"A",c:"Receitas: CORRENTES (tributaria, contribuicoes, patrimonial, servicos, transferencias correntes) e de CAPITAL (operacoes de credito, alienacao, transferencias de capital)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na contabilidade aplicada ao setor publico, o reconhecimento da despesa por competencia ocorre:",o:["A) No pagamento","B) Na liquidacao (fato gerador da VPD)","C) No empenho","D) Na previsao","E) Na inscricao em RP"],g:"B",c:"Sob a otica patrimonial, a Variacao Patrimonial Diminutiva (despesa por competencia) e reconhecida na LIQUIDACAO, quando ocorre o fato gerador. O empenho e etapa orcamentaria."},
{a:2023,r:"FCC/TCE-2023",q:"O Balanco Financeiro evidencia:",o:["A) Ativos e passivos","B) Receitas e despesas orcamentarias + recebimentos e pagamentos extraorcamentarios + saldos","C) So o resultado patrimonial","D) Apenas a divida ativa","E) As VPA e VPD"],g:"B",c:"Balanco Financeiro (art. 103 Lei 4.320): receita e despesa orcamentarias, recebimentos e pagamentos extraorcamentarios, conjugados com os saldos de caixa inicial e final."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A receita orcamentaria sob a otica patrimonial e reconhecida:",o:["A) So na arrecadacao","B) Pelo regime de competencia, no fato gerador (ex: lancamento do tributo)","C) No recolhimento","D) Na previsao","E) No empenho"],g:"B",c:"Sob a otica PATRIMONIAL (MCASP), a Variacao Patrimonial Aumentativa (receita) e reconhecida por COMPETENCIA, no fato gerador. A otica orcamentaria usa o regime de caixa para a receita."},
{a:2023,r:"FCC/TCE-2023",q:"A despesa empenhada e nao liquidada ate 31/12 inscreve-se em:",o:["A) Restos a pagar processados","B) Restos a pagar NAO processados","C) Despesa de exercicios anteriores","D) Divida ativa","E) Superavit financeiro"],g:"B",c:"RP NAO PROCESSADOS: empenho realizado, mas liquidacao pendente ao fim do exercicio. Processados: ja liquidados (Estado deve pagar)."},
{a:2022,r:"FCC/TCM-2022",q:"O ativo imobilizado no setor publico sofre:",o:["A) Apenas reavaliacao","B) Depreciacao, amortizacao ou exaustao, conforme o caso","C) Nenhum ajuste","D) So impairment","E) Correcao monetaria obrigatoria"],g:"B",c:"No setor publico (MCASP), os bens sofrem DEPRECIACAO (bens moveis/imoveis), AMORTIZACAO (intangiveis) ou EXAUSTAO (recursos naturais), pelo regime de competencia."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A conta unica do Tesouro tem como principio a:",o:["A) Pluralidade de caixas","B) Unidade de tesouraria (centralizacao dos recursos)","C) Descentralizacao total","D) Vinculacao integral","E) Autonomia dos orgaos"],g:"B",c:"Art. 56 Lei 4.320: principio da UNIDADE DE TESOURARIA - todos os recursos sao recolhidos a conta unica, vedada a fragmentacao em caixas especiais."},
{a:2023,r:"FCC/TCE-2023",q:"A divida fundada (consolidada) compreende:",o:["A) Restos a pagar do exercicio","B) Compromissos de prazo superior a 12 meses","C) Despesas correntes","D) Receitas","E) Creditos extraordinarios"],g:"B",c:"Divida FUNDADA/CONSOLIDADA: obrigacoes financeiras com prazo SUPERIOR A 12 MESES (e as de prazo inferior incluidas por lei orcamentaria). Flutuante: ate 12 meses."},
{a:2022,r:"FCC/TCM-2022",q:"No PCASP, as contas de controle (classes 5 e 6) registram:",o:["A) Ativos e passivos","B) Atos potenciais e a execucao orcamentaria (controles devedores e credores)","C) Receitas","D) Despesas","E) Patrimonio liquido"],g:"B",c:"Classes 5 (controles DEVEDORES) e 6 (controles CREDORES) registram atos potenciais e o controle da execucao orcamentaria (ex: previsao, fixacao, empenho)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O resultado patrimonial do exercicio e apurado na:",o:["A) Balanco Orcamentario","B) Demonstracao das Variacoes Patrimoniais (VPA - VPD)","C) Balanco Financeiro","D) DFC","E) Divida ativa"],g:"B",c:"A DVP confronta as VPA (aumentativas) e VPD (diminutivas), apurando o RESULTADO PATRIMONIAL do periodo (superavit/deficit patrimonial)."},
{a:2023,r:"FCC/TCE-2023",q:"A fixacao da despesa ocorre na:",o:["A) Liquidacao","B) Lei Orcamentaria Anual (LOA)","C) No empenho","D) No pagamento","E) Na inscricao em RP"],g:"B",c:"A FIXACAO da despesa (1o estagio) ocorre na LOA, que autoriza os gastos. Depois vem empenho, liquidacao e pagamento (execucao)."},
{a:2022,r:"FCC/TCM-2022",q:"A receita de capital 'operacoes de credito' representa:",o:["A) Tributos","B) Recursos captados por emprestimos/financiamentos (endividamento)","C) Aluguel de bens","D) Multas","E) Transferencias correntes"],g:"B",c:"Operacoes de credito (receita de CAPITAL): ingressos provenientes de emprestimos e financiamentos (colocacao de titulos, contratos), aumentando a divida publica."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A inscricao de um credito tributario em divida ativa gera:",o:["A) Variacao patrimonial diminutiva","B) Variacao patrimonial aumentativa (reconhecimento de um ativo)","C) Despesa","D) Passivo","E) Nenhum efeito patrimonial"],g:"B",c:"A inscricao em divida ativa reconhece um ATIVO (direito a receber), gerando VARIACAO PATRIMONIAL AUMENTATIVA na contabilidade patrimonial."},
],
"CGP-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"No metodo PEPS, o estoque final fica valorado a:",o:["A) Precos mais antigos","B) Precos mais recentes","C) Media das compras","D) Custo padrao","E) Valor de venda"],g:"B",c:"PEPS (primeiro a entrar, primeiro a sair): saidas pelos precos antigos -> estoque final pelos precos mais RECENTES. Em inflacao, estoque final maior."},
{a:2022,r:"FCC/RS-2022",q:"O CMV (Custo da Mercadoria Vendida) e calculado por:",o:["A) EI + Compras - EF","B) EF - EI","C) Compras - EI","D) EI + EF","E) Vendas - Compras"],g:"A",c:"CMV = Estoque Inicial + Compras - Estoque Final."},
{a:2021,r:"FCC/ISS-2021",q:"A DEPRECIACAO pelo metodo linear (linha reta):",o:["A) Cresce ao longo do tempo","B) E constante em cada periodo","C) Decresce","D) Depende da producao","E) E zero no 1o ano"],g:"B",c:"Linha reta: cota de depreciacao CONSTANTE por periodo = (custo - valor residual)/vida util."},
{a:2020,r:"FCC/Adm-2020",q:"Provisao (CPC 25) deve ser reconhecida quando:",o:["A) Ha possibilidade remota de saida","B) Ha obrigacao presente, saida provavel e estimativa confiavel","C) Apenas se houver acao judicial","D) Sempre que houver risco","E) So por exigencia fiscal"],g:"B",c:"Provisao: obrigacao presente + saida provavel de recursos + estimativa confiavel. Passivo contingente possivel=notas; remoto=nada."},
{a:2019,r:"FCC/BA-2019",q:"O Ativo Intangivel (CPC 04) caracteriza-se por:",o:["A) Ter substancia fisica","B) Ser identificavel, sem substancia fisica e controlado pela entidade","C) Ser sempre o goodwill","D) Nao gerar beneficios","E) Ser circulante"],g:"B",c:"Intangivel: identificavel, sem substancia fisica, controlado, gera beneficios futuros. Goodwill gerado internamente NAO e reconhecido."},
{a:2023,r:"FCC/TRT-2023",q:"O teste de IMPAIRMENT (CPC 01) reduz o ativo quando:",o:["A) O valor contabil e menor que o recuperavel","B) O valor contabil supera o valor recuperavel","C) Ha valorizacao","D) Ocorre venda","E) Sempre no fim do ano"],g:"B",c:"Impairment: se valor contabil > valor recuperavel, reconhece-se perda por reducao ao valor recuperavel."},
{a:2022,r:"FCC/TCE-2022",q:"A Media Ponderada Movel (MPM):",o:["A) Mantem o preco da 1a compra","B) Recalcula o custo medio a cada nova entrada","C) Usa o preco mais recente","D) Ignora as compras","E) E igual ao PEPS"],g:"B",c:"MPM: recalcula o custo medio unitario A CADA ENTRADA de mercadoria. Suaviza variacoes de preco."},
{a:2021,r:"FCC/ISS-2021",q:"A DRE apura:",o:["A) A posicao patrimonial","B) O resultado (lucro ou prejuizo) do periodo","C) Os fluxos de caixa","D) As mutacoes do PL","E) A riqueza distribuida"],g:"B",c:"DRE: confronta receitas e despesas, apurando o RESULTADO (lucro/prejuizo). BP=posicao; DFC=caixa; DMPL=PL; DVA=riqueza."},
{a:2020,r:"FCC/Adm-2020",q:"Os estoques sao mensurados pelo:",o:["A) Valor de venda","B) Menor valor entre custo e valor realizavel liquido","C) Custo de reposicao","D) Valor justo sempre","E) Valor presente"],g:"B",c:"CPC 16: estoques pelo MENOR valor entre o custo e o valor realizavel liquido (VRL)."},
{a:2019,r:"FCC/BA-2019",q:"A Demonstracao do Valor Adicionado (DVA) evidencia:",o:["A) O lucro liquido apenas","B) A riqueza gerada pela entidade e sua distribuicao","C) Os fluxos de caixa","D) As provisoes","E) O ativo imobilizado"],g:"B",c:"DVA: riqueza criada pela entidade e como foi distribuida (pessoal, governo, financiadores, socios). Obrigatoria para companhias abertas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Pelo regime de competencia, a receita e reconhecida:",o:["A) No recebimento","B) Quando ganha (transferido o controle do bem/servico), independente do recebimento","C) No pedido","D) Na emissao da proposta","E) No fim do ano"],g:"B",c:"Regime de COMPETENCIA: a receita e reconhecida quando GANHA (controle transferido - CPC 47), e a despesa quando incorrida, independente do caixa."},
{a:2023,r:"FCC/RS-2023",q:"Uma duplicata descontada no banco representa:",o:["A) Receita","B) Passivo (obrigacao), pois a empresa responde pelo titulo","C) Reducao do ativo permanente","D) Despesa antecipada","E) Patrimonio liquido"],g:"B",c:"Duplicatas descontadas: o risco permanece com a empresa, sendo classificadas como PASSIVO (conta redutora de contas a receber / obrigacao com o banco)."},
{a:2022,r:"FCC/ISS-2022",q:"No Balanco Patrimonial, o Ativo e ordenado por:",o:["A) Ordem alfabetica","B) Grau decrescente de liquidez","C) Valor crescente","D) Data de aquisicao","E) Natureza juridica"],g:"B",c:"O Ativo e apresentado em ordem DECRESCENTE de liquidez (Circulante antes do Nao Circulante). O Passivo, por ordem de exigibilidade."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A Reserva de Lucros a Realizar destina-se a:",o:["A) Distribuir dividendos","B) Reter parcela do lucro ainda nao financeiramente realizada","C) Cobrir prejuizos","D) Aumentar capital","E) Pagar tributos"],g:"B",c:"Reserva de Lucros a Realizar: retem a parcela do lucro do exercicio decorrente de ganhos ainda nao realizados financeiramente (ex: equivalencia, vendas a prazo de LP)."},
{a:2023,r:"FCC/RS-2023",q:"O metodo de equivalencia patrimonial reconhece, no resultado:",o:["A) Dividendos recebidos","B) A participacao da investidora no resultado da investida","C) O valor de mercado","D) So o custo","E) O valor justo"],g:"B",c:"MEP: a investidora reconhece em RESULTADO sua participacao no lucro/prejuizo da investida (nao os dividendos, que reduzem o investimento)."},
{a:2022,r:"FCC/ISS-2022",q:"Na DFC pelo metodo indireto, parte-se do:",o:["A) Caixa inicial","B) Lucro liquido, ajustado por itens que nao afetam o caixa","C) Total de receitas","D) Saldo de clientes","E) Patrimonio liquido"],g:"B",c:"DFC indireto: parte do LUCRO LIQUIDO e ajusta por depreciacao, variacoes de capital de giro e itens nao-caixa, para chegar ao caixa das operacoes."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A despesa com depreciacao:",o:["A) Reduz o caixa","B) Reduz o resultado mas nao afeta o caixa diretamente","C) Aumenta o ativo","D) E uma receita","E) E um passivo"],g:"B",c:"Depreciacao e despesa que NAO afeta o caixa (item nao-caixa). Por isso e somada de volta na DFC indireta."},
{a:2023,r:"FCC/RS-2023",q:"O Capital Circulante Liquido (CCL) e:",o:["A) Ativo total - Passivo total","B) Ativo Circulante - Passivo Circulante","C) Patrimonio Liquido","D) Ativo Permanente","E) Receita - Despesa"],g:"B",c:"CCL = Ativo Circulante - Passivo Circulante. Indica a folga financeira de curto prazo da entidade."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Pelo principio da entidade, o patrimonio da empresa:",o:["A) Confunde-se com o dos socios","B) Nao se confunde com o dos socios (separacao patrimonial)","C) Pertence ao Estado","D) E sempre dos credores","E) Nao existe"],g:"B",c:"Principio da ENTIDADE: o patrimonio da empresa e distinto e nao se confunde com o dos socios/proprietarios (separacao patrimonial)."},
{a:2023,r:"FCC/RS-2023",q:"Uma despesa paga antecipadamente (ex: seguro anual) e classificada como:",o:["A) Receita","B) Ativo (despesa antecipada), apropriada ao resultado pela competencia","C) Passivo","D) Patrimonio liquido","E) Custo do produto"],g:"B",c:"Despesa ANTECIPADA: paga mas ainda nao incorrida, e ATIVO (circulante); apropria-se ao resultado conforme o periodo a que se refere (competencia)."},
{a:2022,r:"FCC/ISS-2022",q:"O lucro bruto na DRE corresponde a:",o:["A) Receita liquida - CMV/CPV","B) Receita bruta - impostos","C) Lucro liquido + despesas","D) Receita - todas as despesas","E) EBITDA"],g:"A",c:"Lucro BRUTO = Receita Liquida de Vendas - Custo das Mercadorias/Produtos Vendidos (CMV/CPV). Depois deduzem-se despesas operacionais para o resultado."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A Reserva Legal e constituida com:",o:["A) 10% do capital","B) 5% do lucro liquido, ate atingir 20% do capital social","C) Todo o lucro","D) Dividendos","E) Agio na emissao"],g:"B",c:"Lei 6.404/76: a Reserva Legal e formada por 5% do LUCRO LIQUIDO do exercicio, ate o limite de 20% do capital social (pode parar antes se reservas + capital = 30%)."},
{a:2023,r:"FCC/RS-2023",q:"No regime de competencia, vender a prazo gera reconhecimento de:",o:["A) Receita so no recebimento","B) Receita na venda (transferencia do controle), com contas a receber no ativo","C) Despesa","D) Passivo","E) Nenhuma receita"],g:"B",c:"Competencia: a receita e reconhecida na VENDA (transferencia do controle), registrando-se duplicatas/contas a receber no ativo, independente do recebimento."},
{a:2022,r:"FCC/ISS-2022",q:"O indice de liquidez corrente e calculado por:",o:["A) Ativo total / Passivo total","B) Ativo Circulante / Passivo Circulante","C) PL / Ativo","D) Lucro / Vendas","E) Disponivel / Passivo"],g:"B",c:"Liquidez CORRENTE = Ativo Circulante / Passivo Circulante. Mede a capacidade de pagar obrigacoes de curto prazo. >1 indica folga."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O agio na emissao de acoes (acima do valor nominal) e registrado em:",o:["A) Receita","B) Reserva de capital","C) Reserva de lucros","D) Capital social","E) Passivo"],g:"B",c:"O agio na emissao de acoes/bonus de subscricao e RESERVA DE CAPITAL (nao transita pelo resultado), pois decorre de aporte dos socios, nao de operacao."},
{a:2023,r:"FCC/RS-2023",q:"A baixa de um bem do imobilizado com valor contabil de 8.000, vendido por 10.000, gera:",o:["A) Prejuizo de 2.000","B) Ganho de 2.000 (outras receitas)","C) Receita de 10.000","D) Despesa de 8.000","E) Nenhum efeito"],g:"B",c:"Venda por 10.000 de bem com valor contabil liquido de 8.000 gera GANHO de 2.000 (resultado na alienacao de ativo - outras receitas/despesas operacionais)."},
{a:2022,r:"FCC/ISS-2022",q:"A conta 'Depreciacao Acumulada' e:",o:["A) Ativo","B) Conta redutora do ativo imobilizado (retificadora)","C) Despesa","D) Passivo","E) Patrimonio liquido"],g:"B",c:"Depreciacao Acumulada e conta RETIFICADORA (redutora) do ativo imobilizado; subtrai do custo para chegar ao valor contabil liquido."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O CMV, dado EI=20.000, Compras=80.000 e EF=30.000, e:",o:["A) 70.000","B) 90.000","C) 130.000","D) 50.000","E) 110.000"],g:"A",c:"CMV = EI + Compras - EF = 20.000 + 80.000 - 30.000 = 70.000."},
],
"COA-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"No CPC 46, os dados de NIVEL 1 da hierarquia de valor justo sao:",o:["A) Dados nao observaveis","B) Premissas da entidade","C) Precos cotados em mercado ativo para ativos identicos","D) Ativos similares","E) Fluxo de caixa descontado"],g:"C",c:"Nivel 1: precos cotados em mercado ATIVO para ativos IDENTICOS (maior confiabilidade). Nivel 3: nao observaveis (premissas internas)."},
{a:2022,r:"FCC/RS-2022",q:"No CPC 06 R2 (IFRS 16), o arrendatario reconhece:",o:["A) Apenas despesa linear","B) Ativo de direito de uso e passivo de arrendamento","C) Passivo contingente","D) Receita diferida","E) Apenas nas notas"],g:"B",c:"CPC 06 R2: arrendatario reconhece ATIVO DE DIREITO DE USO + PASSIVO DE ARRENDAMENTO. Excecoes: <=12 meses e baixo valor."},
{a:2021,r:"FCC/ISS-2021",q:"O GOODWILL positivo (CPC 15) ocorre quando:",o:["A) VJ liquido > contraprestacao","B) Contraprestacao+PNC+interesse previo > VJ liquido dos ativos/passivos","C) A adquirida tem prejuizo","D) Valor contabil > mercado","E) Ha marca famosa"],g:"B",c:"Goodwill = (contraprestacao + PNC + interesse previo) - VJ liquido. Positivo=goodwill (intangivel, impairment anual); negativo=compra vantajosa (resultado)."},
{a:2020,r:"FCC/Adm-2020",q:"O MEP (CPC 18) aplica-se a:",o:["A) Qualquer investimento acima de 1%","B) Coligadas (influencia significativa >=20% votante) e controladas","C) So controladas >50% total","D) Ativos ao valor justo","E) Todas as listadas"],g:"B",c:"MEP: coligadas (influencia significativa, presuncao >=20% do votante) e controladas. Atualiza o investimento pelo % do PL da investida."},
{a:2019,r:"FCC/BA-2019",q:"A COMPRA VANTAJOSA (goodwill negativo) e reconhecida:",o:["A) No ativo intangivel","B) Como ganho no resultado do periodo","C) No PL diretamente","D) Como passivo","E) Amortizada em 10 anos"],g:"B",c:"Goodwill NEGATIVO (compra vantajosa): ganho reconhecido no RESULTADO imediatamente (apos revisao das mensuracoes)."},
{a:2023,r:"FCC/TRT-2023",q:"No CPC 48 (IFRS 9), os instrumentos financeiros sao classificados em:",o:["A) So custo historico","B) Custo amortizado, valor justo por ORA e valor justo por resultado","C) Apenas valor de mercado","D) Valor nominal","E) So circulante e nao circulante"],g:"B",c:"CPC 48: custo amortizado; valor justo por outros resultados abrangentes (ORA); valor justo por resultado (VJR). Modelo de perdas esperadas."},
{a:2022,r:"FCC/RS-2022",q:"O Ajuste a Valor Presente (AVP) aplica-se a:",o:["A) Operacoes a vista","B) Ativos e passivos de longo prazo (e relevantes de curto prazo)","C) So o imobilizado","D) Apenas receitas","E) Estoques sempre"],g:"B",c:"AVP: elementos de longo prazo (e relevantes de curto prazo) trazidos a valor presente, reconhecendo encargo financeiro pro rata."},
{a:2021,r:"FCC/ISS-2021",q:"A hierarquia do valor justo busca:",o:["A) Minimizar disclosure","B) Maximizar o uso de dados observaveis e minimizar nao observaveis","C) Usar so premissas internas","D) Ignorar o mercado","E) Adotar custo historico"],g:"B",c:"CPC 46: MAXIMIZAR dados observaveis (niveis 1 e 2) e minimizar dados nao observaveis (nivel 3)."},
{a:2020,r:"FCC/Adm-2020",q:"O goodwill reconhecido em combinacao de negocios:",o:["A) E amortizado em 5 anos","B) Nao e amortizado, mas testado por impairment anualmente","C) E baixado no resultado","D) Vai para o PL","E) E reavaliado a valor justo"],g:"B",c:"Goodwill: NAO amortizado; submetido a teste de IMPAIRMENT anual (ou quando houver indicio de perda)."},
{a:2019,r:"FCC/BA-2019",q:"A subvencao governamental (CPC 07) deve ser:",o:["A) Reconhecida direto no PL","B) Reconhecida no resultado em base sistematica confrontada com as despesas","C) Ignorada","D) Tratada como passivo permanente","E) Distribuida como dividendo obrigatorio"],g:"B",c:"CPC 07: subvencao reconhecida no resultado de forma sistematica, confrontada com as despesas que pretende compensar."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No CPC 47 (Receita de Contrato com Cliente), a receita e reconhecida quando:",o:["A) O caixa e recebido","B) A entidade satisfaz a obrigacao de desempenho (transfere o controle)","C) O contrato e assinado","D) A nota e emitida","E) No fim do periodo"],g:"B",c:"CPC 47/IFRS 15: 5 passos; a receita e reconhecida quando (ou a medida que) a obrigacao de desempenho e satisfeita, com a transferencia do controle do bem/servico."},
{a:2023,r:"FCC/Fiscal-2023",q:"O custo de emprestimos (CPC 20) atribuivel a ativo qualificavel deve ser:",o:["A) Sempre despesa","B) Capitalizado como parte do custo do ativo","C) Reconhecido no PL","D) Ignorado","E) Levado a reserva"],g:"B",c:"CPC 20: custos de emprestimos diretamente atribuiveis a aquisicao/construcao de ativo qualificavel sao CAPITALIZADOS; os demais sao despesa."},
{a:2022,r:"FCC/PGE-2022",q:"No CPC 27, a reavaliacao de imobilizado (quando adotada):",o:["A) E vedada no Brasil","B) Permite mensurar pelo valor justo, com aumento em outros resultados abrangentes","C) Vai sempre ao resultado","D) Reduz o capital","E) Nao afeta a depreciacao"],g:"B",c:"O modelo de reavaliacao (CPC 27) mensura pelo valor justo; o aumento vai a ORA (reserva de reavaliacao). No Brasil societario o uso e restrito, mas o conceito e cobrado."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No CPC 32 (Tributos sobre o Lucro), o imposto diferido surge de:",o:["A) Diferencas permanentes","B) Diferencas temporarias entre base contabil e fiscal","C) Multas fiscais","D) Subvencoes","E) Dividendos"],g:"B",c:"CPC 32: o tributo diferido decorre de DIFERENCAS TEMPORARIAS (tributaveis -> passivo diferido; dedutiveis -> ativo diferido) e de prejuizos fiscais a compensar."},
{a:2023,r:"FCC/Fiscal-2023",q:"O valor recuperavel de um ativo (CPC 01) e o:",o:["A) Custo historico","B) Maior valor entre o valor justo liquido de despesas e o valor em uso","C) Valor contabil","D) Valor de mercado apenas","E) Custo de reposicao"],g:"B",c:"CPC 01: valor recuperavel = MAIOR entre (valor justo - despesas de venda) e (valor em uso = VP dos fluxos futuros). Se contabil > recuperavel, ha impairment."},
{a:2022,r:"FCC/PGE-2022",q:"No CPC 16, NAO integra o custo dos estoques:",o:["A) Custo de aquisicao","B) Custos de transformacao","C) Gastos gerais de administracao nao relacionados a producao","D) Fretes de compra","E) Impostos nao recuperaveis"],g:"C",c:"CPC 16: despesas administrativas gerais e perdas anormais NAO integram o custo do estoque (vao a resultado). Integram: aquisicao, transformacao e outros para deixar pronto."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A mensuracao a valor justo prioriza, na hierarquia (CPC 46):",o:["A) Premissas internas","B) Precos cotados em mercado ativo (nivel 1)","C) Custo historico","D) Fluxo de caixa","E) Valor de reposicao"],g:"B",c:"CPC 46: a hierarquia prioriza o Nivel 1 (precos cotados em mercado ativo para ativos identicos), depois Nivel 2 (observaveis) e por ultimo Nivel 3 (nao observaveis)."},
{a:2023,r:"FCC/Fiscal-2023",q:"Provisao difere de passivo contingente porque a provisao:",o:["A) Nunca e reconhecida","B) E reconhecida no passivo (obrigacao presente provavel e mensuravel)","C) So vai em nota explicativa","D) E um ativo","E) Depende de acao judicial transitada"],g:"B",c:"CPC 25: PROVISAO e passivo de prazo/valor incertos, reconhecida quando provavel e mensuravel. Passivo CONTINGENTE (possivel) so e divulgado em nota; remoto nao se divulga."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No CPC 47, o preco da transacao deve ser alocado:",o:["A) Igualmente entre periodos","B) As obrigacoes de desempenho com base no preco de venda individual (stand-alone)","C) Todo na assinatura","D) No recebimento","E) No fim do contrato"],g:"B",c:"CPC 47 (passo 4): o preco da transacao e alocado a cada obrigacao de desempenho proporcionalmente ao preco de venda INDIVIDUAL (stand-alone selling price)."},
{a:2023,r:"FCC/Fiscal-2023",q:"No CPC 06 (R2), o arrendatario NAO reconhece ativo de direito de uso quando:",o:["A) O prazo e de 5 anos","B) O arrendamento e de curto prazo (ate 12 meses) ou de baixo valor","C) Ha opcao de compra","D) O bem e imovel","E) Ha pagamentos variaveis"],g:"B",c:"CPC 06 R2: o arrendatario pode NAO reconhecer ativo/passivo nos arrendamentos de CURTO PRAZO (<=12 meses) e de BAIXO VALOR (lancando como despesa)."},
{a:2022,r:"FCC/PGE-2022",q:"A mensuracao subsequente de propriedade para investimento (CPC 28) pode ser pelo:",o:["A) Custo apenas","B) Metodo do custo ou do valor justo (escolha de politica contabil)","C) Valor de mercado obrigatorio","D) Valor presente","E) Custo de reposicao"],g:"B",c:"CPC 28: apos o reconhecimento, a propriedade para investimento pode ser mensurada pelo CUSTO ou pelo VALOR JUSTO (politica aplicada a todas)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No CPC 32, o ativo fiscal diferido decorre de:",o:["A) Diferencas permanentes","B) Diferencas temporarias dedutiveis e prejuizos fiscais a compensar","C) Multas","D) Dividendos","E) Reavaliacao"],g:"B",c:"Ativo fiscal diferido: diferencas temporarias DEDUTIVEIS e prejuizos fiscais/bases negativas a compensar, desde que provavel lucro tributavel futuro."},
{a:2023,r:"FCC/Fiscal-2023",q:"A combinacao de negocios (CPC 15) e contabilizada pelo metodo:",o:["A) Da equivalencia","B) De aquisicao (purchase method)","C) Da consolidacao proporcional","D) Do custo","E) Do valor justo do PL"],g:"B",c:"CPC 15: combinacoes de negocios sao contabilizadas pelo METODO DE AQUISICAO - identifica-se o adquirente, mensura-se a contraprestacao e reconhece-se o goodwill/compra vantajosa."},
{a:2022,r:"FCC/PGE-2022",q:"Os Outros Resultados Abrangentes (ORA) compreendem itens que:",o:["A) Transitam pelo resultado","B) Afetam o PL sem transitar pelo resultado do periodo (ex: ajuste de avaliacao patrimonial)","C) Sao despesas","D) Sao receitas de venda","E) Reduzem o capital"],g:"B",c:"ORA: variacoes patrimoniais que ainda nao transitam pelo resultado (ex: ganhos de instrumentos a valor justo por ORA, ajustes de conversao, reavaliacao). Compoem o resultado abrangente total."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No teste de impairment, a unidade geradora de caixa (UGC) e:",o:["A) Um unico ativo sempre","B) O menor grupo de ativos que gera entradas de caixa independentes","C) A empresa toda","D) Um passivo","E) O estoque"],g:"B",c:"CPC 01: quando nao se pode estimar o valor recuperavel de um ativo isolado, usa-se a UGC = menor grupo identificavel de ativos que gera fluxos de caixa amplamente independentes."},
{a:2023,r:"FCC/Fiscal-2023",q:"A subvencao governamental para investimento (CPC 07), apos a Lei 14.789/23:",o:["A) Nunca e tributada","B) Compoe a base do IRPJ/CSLL, com possibilidade de credito fiscal sobre subvencoes para implantacao/expansao","C) E receita isenta total","D) Vai direto ao capital","E) E ignorada"],g:"B",c:"Lei 14.789/2023 alterou o tratamento: as subvencoes passam a compor a base de calculo, criando-se um credito fiscal de ate 25% sobre subvencoes para implantacao/expansao habilitadas."},
{a:2022,r:"FCC/PGE-2022",q:"No CPC 25, uma obrigacao presente provavel, mas sem mensuracao confiavel:",o:["A) Vira provisao","B) E divulgada como passivo contingente (nota explicativa)","C) Vai ao resultado","D) E ativo","E) Aumenta o PL"],g:"B",c:"CPC 25: se a obrigacao e provavel mas NAO mensuravel de forma confiavel (caso raro), nao se reconhece provisao - divulga-se como passivo contingente em nota."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O valor em uso de um ativo (CPC 01) corresponde ao:",o:["A) Preco de venda","B) Valor presente dos fluxos de caixa futuros esperados do ativo","C) Custo historico","D) Valor de reposicao","E) Valor contabil liquido"],g:"B",c:"Valor em uso = VALOR PRESENTE dos fluxos de caixa futuros que se espera obter do ativo (uso continuado + alienacao final), descontados a taxa apropriada."},
],
"COA-2":[
{a:2023,r:"FCC/SEFAZ-2023",q:"CF=400.000, PV=200, CV=120. O Ponto de Equilibrio Contabil e:",o:["A) 2.000 un","B) 3.333 un","C) 4.000 un","D) 5.000 un","E) 6.667 un"],g:"D",c:"MC=200-120=80. PEC=CF/MC=400.000/80=5.000 unidades."},
{a:2022,r:"FCC/RS-2022",q:"No custeio por ABSORCAO, os custos fixos sao:",o:["A) Tratados como despesa do periodo","B) Rateados aos produtos","C) Ignorados","D) Levados ao PL","E) Sempre variaveis"],g:"B",c:"ABSORCAO: TODOS os custos (fixos+variaveis) sao alocados aos produtos. Exigido pelo fisco e societario."},
{a:2021,r:"FCC/ISS-2021",q:"A Margem de Contribuicao unitaria e:",o:["A) PV - custo fixo unitario","B) Preco de venda - custo/despesa variavel unitario","C) PV - custo total","D) Custo fixo / quantidade","E) Lucro / PV"],g:"B",c:"MC unitaria = Preco de Venda - Custos e Despesas Variaveis unitarios. Cobre os custos fixos e forma o lucro."},
{a:2020,r:"FCC/Adm-2020",q:"O custeio VARIAVEL e mais adequado para:",o:["A) Atender o fisco","B) Decisoes gerenciais (nao rateia fixos aos produtos)","C) Avaliacao de estoques fiscal","D) Demonstracoes societarias","E) Auditoria externa"],g:"B",c:"Custeio VARIAVEL: apenas custos variaveis no produto; fixos sao despesa do periodo. Melhor para DECISAO gerencial. Nao aceito pelo fisco."},
{a:2019,r:"FCC/BA-2019",q:"O Ponto de Equilibrio FINANCEIRO:",o:["A) Inclui o custo de oportunidade","B) Exclui a depreciacao dos custos fixos","C) E igual ao contabil","D) Ignora a MC","E) E sempre maior que o economico"],g:"B",c:"PEF = (CF - depreciacao)/MCu. Considera so as saidas de CAIXA. PEC inclui depreciacao; PEE soma custo de oportunidade."},
{a:2023,r:"FCC/TRT-2023",q:"O custeio ABC (Activity-Based Costing) aloca custos indiretos por:",o:["A) Volume de producao apenas","B) Atividades e seus direcionadores de custo","C) Rateio simples","D) Mao de obra direta","E) Material direto"],g:"B",c:"ABC: rastreia custos indiretos por ATIVIDADES e direcionadores (cost drivers), oferecendo maior precisao em ambientes diversificados."},
{a:2022,r:"FCC/RS-2022",q:"Custo fixo unitario, com aumento da producao:",o:["A) Aumenta","B) Diminui (diluicao)","C) Permanece constante","D) Torna-se variavel","E) Zera"],g:"B",c:"Custo fixo TOTAL e constante; o custo fixo UNITARIO DIMINUI com mais producao (diluicao). Variavel: total cresce, unitario constante."},
{a:2021,r:"FCC/ISS-2021",q:"O Ponto de Equilibrio ECONOMICO considera:",o:["A) So custos contabeis","B) Os custos fixos mais o custo de oportunidade do capital","C) Menos a depreciacao","D) Apenas o caixa","E) So custos variaveis"],g:"B",c:"PEE = (CF + custo de oportunidade)/MCu. Garante remunerar o capital proprio (lucro minimo desejado)."},
{a:2020,r:"FCC/Adm-2020",q:"Custos DIRETOS sao aqueles que:",o:["A) Nao podem ser identificados ao produto","B) Sao apropriados diretamente ao produto sem rateio","C) Sao sempre fixos","D) Independem da producao","E) Sao despesas administrativas"],g:"B",c:"Custos DIRETOS: identificados e apropriados diretamente ao produto (materia-prima, MO direta). INDIRETOS exigem rateio."},
{a:2019,r:"FCC/BA-2019",q:"Na producao conjunta, os subprodutos:",o:["A) Tem valor de venda elevado e objetivo principal","B) Sao secundarios, de valor reduzido, surgidos naturalmente do processo","C) Nao existem","D) Sao iguais aos coprodutos","E) Geram so prejuizo"],g:"B",c:"SUBPRODUTOS: itens secundarios, de pequeno valor, surgidos naturalmente. COPRODUTOS: objetivos principais. Sucata: residuo sem processo."},
{a:2024,r:"FCC/SEFAZ-2024",q:"CF=600.000, MCu=150. O ponto de equilibrio contabil em unidades e:",o:["A) 3.000","B) 4.000","C) 5.000","D) 6.000","E) 4.500"],g:"B",c:"PEC = CF/MCu = 600.000/150 = 4.000 unidades."},
{a:2023,r:"FCC/Fiscal-2023",q:"A margem de seguranca operacional indica:",o:["A) O lucro maximo","B) O quanto as vendas podem cair antes de atingir o ponto de equilibrio","C) O custo fixo","D) A margem de contribuicao","E) O preco minimo"],g:"B",c:"Margem de seguranca = (vendas atuais - vendas no PE) / vendas atuais. Mostra a folga antes de comecar a ter prejuizo."},
{a:2022,r:"FCC/ISS-2022",q:"No custeio variavel, o resultado e influenciado por:",o:["A) Volume de producao","B) Volume de VENDAS (custos fixos sao do periodo)","C) Nivel de estoque","D) Rateio dos fixos","E) Depreciacao alocada"],g:"B",c:"No custeio VARIAVEL, o lucro varia com as VENDAS (fixos sao despesa do periodo). No absorcao, estocar producao 'segura' custo fixo no estoque e altera o resultado."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O grau de alavancagem operacional (GAO) mede:",o:["A) O endividamento","B) A variacao percentual do lucro para cada 1% de variacao nas vendas","C) A liquidez","D) O custo de capital","E) A margem bruta"],g:"B",c:"GAO = variacao % do lucro operacional / variacao % das vendas = MC total / lucro operacional. Quanto maior o custo fixo, maior a alavancagem."},
{a:2023,r:"FCC/Fiscal-2023",q:"Custos de transformacao compreendem:",o:["A) Apenas materia-prima","B) Mao de obra direta + custos indiretos de fabricacao","C) Despesas de venda","D) Comissoes","E) Fretes de entrega"],g:"B",c:"Custos de transformacao = MOD + CIF (custos indiretos de fabricacao), aplicados para transformar a materia-prima em produto acabado."},
{a:2022,r:"FCC/ISS-2022",q:"No metodo ABC, os direcionadores de custo (cost drivers) servem para:",o:["A) Reduzir custos","B) Alocar custos indiretos as atividades e destas aos produtos","C) Calcular o preco","D) Definir o lucro","E) Ratear receitas"],g:"B",c:"ABC: os cost drivers medem o consumo de cada atividade pelos produtos, permitindo alocar os custos indiretos com mais precisao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na producao conjunta, o ponto de separacao (split-off) e:",o:["A) O fim da producao","B) O momento em que os coprodutos passam a ser identificaveis separadamente","C) O inicio do processo","D) A venda","E) O rateio do lucro"],g:"B",c:"Ponto de separacao: estagio do processo conjunto em que os produtos se tornam individualmente identificaveis. Custos conjuntos sao rateados ate ali."},
{a:2023,r:"FCC/Fiscal-2023",q:"O custo-padrao serve para:",o:["A) Substituir o custo real","B) Servir de referencia e permitir analise de variacoes (real x padrao)","C) Calcular tributos","D) Definir o preco de venda obrigatorio","E) Eliminar custos indiretos"],g:"B",c:"Custo-padrao: meta cientificamente estabelecida; compara-se com o real para apurar VARIACOES (de preco e de quantidade) e tomar acoes corretivas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"CF=300.000, PV=80, CV=50. Para lucro de 60.000, a quantidade a vender e:",o:["A) 10.000","B) 12.000","C) 8.000","D) 6.000","E) 15.000"],g:"B",c:"MCu=80-50=30. Q=(CF+lucro)/MCu=(300.000+60.000)/30=12.000 unidades."},
{a:2023,r:"FCC/Fiscal-2023",q:"No custeio por absorcao, o aumento dos estoques (produzir mais que vender):",o:["A) Reduz o lucro","B) Aumenta o lucro (parte do custo fixo fica ativada no estoque)","C) Nao altera","D) Zera o lucro","E) Vira despesa"],g:"B",c:"No ABSORCAO, produzir mais que vender 'segura' custo fixo no estoque (ativo), reduzindo o custo do periodo e AUMENTANDO o lucro. No variavel isso nao ocorre."},
{a:2022,r:"FCC/ISS-2022",q:"O custo primario (ou direto) e composto por:",o:["A) MOD + CIF","B) Material direto + Mao de obra direta","C) So material direto","D) Todos os custos","E) Despesas + custos"],g:"B",c:"Custo PRIMARIO = Material Direto + Mao de Obra Direta (os custos diretamente atribuiveis). Custo de transformacao = MOD + CIF."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O grau de alavancagem operacional, com MC total de 200.000 e lucro de 50.000, e:",o:["A) 2","B) 4","C) 0,25","D) 5","E) 250.000"],g:"B",c:"GAO = MC total / Lucro operacional = 200.000/50.000 = 4. Cada 1% de aumento nas vendas eleva o lucro em 4%."},
{a:2023,r:"FCC/Fiscal-2023",q:"A variacao de PRECO de materiais (custo-padrao) e apurada por:",o:["A) (Qtd real - padrao) x preco","B) (Preco real - preco padrao) x quantidade real","C) Preco real x padrao","D) Quantidade x lucro","E) MC x preco"],g:"B",c:"Variacao de PRECO = (preco real - preco padrao) x quantidade real adquirida/usada. A variacao de QUANTIDADE/eficiencia usa (qtd real - padrao) x preco padrao."},
{a:2022,r:"FCC/ISS-2022",q:"O rateio dos custos indiretos no custeio por absorcao e necessario porque:",o:["A) Os custos indiretos nao se identificam diretamente com cada produto","B) E proibido por lei","C) Os custos sao todos diretos","D) Nao ha custos fixos","E) O lucro e fixo"],g:"A",c:"Custos INDIRETOS (ex: aluguel da fabrica, supervisao) nao se identificam diretamente com o produto, exigindo RATEIO por criterios (horas-maquina, MOD etc.) no absorcao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No ponto de equilibrio, o lucro operacional e:",o:["A) Maximo","B) Zero (receita total = custo total)","C) Negativo","D) Igual a MC","E) Igual ao CF"],g:"B",c:"No ponto de equilibrio, a receita total iguala o custo total, e o lucro operacional e ZERO. Acima dele ha lucro; abaixo, prejuizo."},
{a:2023,r:"FCC/Fiscal-2023",q:"Coprodutos diferem de subprodutos porque os coprodutos:",o:["A) Tem valor irrelevante","B) Sao os produtos principais, objetivo da producao","C) Sao residuos","D) Nao tem mercado","E) Sao sucata"],g:"B",c:"COPRODUTOS: produtos principais que justificam o processo (valor relevante). SUBPRODUTOS: secundarios, de valor reduzido. SUCATA/residuo: valor irrisorio ou nulo."},
{a:2022,r:"FCC/ISS-2022",q:"O custeio variavel e util gerencialmente porque:",o:["A) Atende ao fisco","B) Isola a margem de contribuicao e facilita decisoes de curto prazo","C) Rateia os fixos","D) Aumenta o estoque","E) E exigido por lei"],g:"B",c:"Custeio VARIAVEL evidencia a MARGEM DE CONTRIBUICAO e separa custos fixos (do periodo), apoiando decisoes gerenciais (mix, precos, descontinuar produto). Nao e aceito para fins fiscais/societarios."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A margem de contribuicao total, vendidas 5.000 un com MCu de 30, e:",o:["A) R$30.000","B) R$150.000","C) R$5.000","D) R$35.000","E) R$300.000"],g:"B",c:"MC total = MCu x quantidade = 30 x 5.000 = 150.000. Dela se subtrai o custo fixo para chegar ao lucro."},
],
"DTR-1":[
{a:2023,r:"FCC/SEFAZ-2023",q:"A obrigacao tributaria ACESSORIA tem por objeto:",o:["A) Pagamento de tributo ou penalidade","B) Prestacoes positivas ou negativas no interesse da arrecadacao/fiscalizacao","C) So o pagamento do tributo","D) Entrega em cartorio","E) Recolhimento antecipado"],g:"B",c:"Art. 113 par.2: acessoria=prestacoes positivas (emitir NF, escriturar) ou negativas (nao obstruir). Descumprir converte em principal (multa)."},
{a:2022,r:"FCC/Fiscal-2022",q:"Sao causas de SUSPENSAO do credito (art. 151):",o:["A) Pagamento, compensacao, remissao","B) Moratoria, deposito integral, reclamacoes/recursos, liminar/tutela, parcelamento","C) Isencao e anistia","D) Decadencia e prescricao","E) Dacao em pagamento"],g:"B",c:"Art. 151 (MDRRLP): Moratoria, Deposito integral, Reclamacoes/Recursos, Liminar/Tutela, Parcelamento."},
{a:2021,r:"FCC/GO-2021",q:"O lancamento por HOMOLOGACAO caracteriza-se por:",o:["A) Fisco agir sozinho","B) Contribuinte declarar e Fisco lancar","C) Contribuinte antecipar o pagamento sem previo exame","D) Ser usado no IPTU","E) Dispensar pagamento"],g:"C",c:"Art. 150: por HOMOLOGACAO, o sujeito passivo antecipa o pagamento sem previo exame. Decadencia: 5 anos do FG. Ex: ICMS, IR, IPI."},
{a:2020,r:"FCC/TRF-2020",q:"A DECADENCIA tributaria extingue:",o:["A) A pretensao de cobrar","B) O direito de a Fazenda constituir o credito pelo lancamento","C) A execucao fiscal","D) O direito de repetir indebito","E) O parcelamento"],g:"B",c:"DECADENCIA (art. 173): extingue o direito de LANCAR. PRESCRICAO (art. 174): extingue a acao de COBRAR. Ambas: 5 anos."},
{a:2019,r:"FCC/RJ-2019",q:"Sao modalidades de EXTINCAO do credito (art. 156):",o:["A) Moratoria e parcelamento","B) Pagamento, compensacao, transacao, remissao, prescricao, decadencia","C) Isencao e anistia","D) Reclamacoes e recursos","E) Liminar em MS"],g:"B",c:"Art. 156 (extincao): pagamento, compensacao, transacao, remissao, prescricao, decadencia, dacao em pagamento etc. Isencao/anistia=exclusao."},
{a:2023,r:"FCC/TRT-2023",q:"A responsabilidade por SUBSTITUICAO tributaria:",o:["A) Surge apos o fato gerador","B) Atribui ao substituto a obrigacao desde a origem","C) E sempre subsidiaria","D) Depende de sucessao","E) Exige dolo"],g:"B",c:"SUBSTITUICAO: o responsavel (substituto) ocupa o lugar do contribuinte desde a origem (ex: ICMS-ST). TRANSFERENCIA: por evento posterior."},
{a:2022,r:"FCC/Fiscal-2022",q:"A ISENCAO, como causa de EXCLUSAO:",o:["A) Extingue o credito","B) Dispensa o pagamento do tributo (antes do lancamento)","C) Suspende a exigibilidade","D) Perdoa a multa","E) E o mesmo que imunidade"],g:"B",c:"ISENCAO: exclui o credito tributario (dispensa o tributo), decorre de lei. ANISTIA: exclui a multa. IMUNIDADE: limitacao constitucional."},
{a:2021,r:"FCC/GO-2021",q:"A solidariedade tributaria (art. 124):",o:["A) Comporta beneficio de ordem","B) Nao comporta beneficio de ordem","C) Exige contrato","D) So entre entes publicos","E) Depende de homologacao"],g:"B",c:"Art. 124 PU: a solidariedade tributaria NAO comporta beneficio de ordem (o Fisco cobra de qualquer um integralmente)."},
{a:2020,r:"FCC/TRF-2020",q:"A responsabilidade do art. 135 (socios-gerentes) ocorre quando:",o:["A) Ha mero inadimplemento","B) Ha atos com excesso de poderes ou infracao de lei/contrato (dolo)","C) Sempre que a empresa deve","D) Ha dissolucao regular","E) Por culpa leve"],g:"B",c:"Art. 135: responsabilidade PESSOAL por atos com excesso de poderes/infracao de lei. Sumula 430 STJ: mero inadimplemento nao gera responsabilidade do socio."},
{a:2019,r:"FCC/RJ-2019",q:"O Fato Gerador da obrigacao principal e:",o:["A) Qualquer ato administrativo","B) A situacao definida em lei como necessaria e suficiente a sua ocorrencia","C) O lancamento","D) A inscricao em divida ativa","E) O pagamento"],g:"B",c:"Art. 114: FG da obrigacao principal = situacao definida em lei como NECESSARIA E SUFICIENTE a sua ocorrencia."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A capacidade tributaria PASSIVA independe de:",o:["A) Estar a pessoa juridica regularmente constituida","B) Achar-se a pessoa sujeita a medidas que importem privacao de direitos","C) Estar a pessoa natural sujeita a incapacidade civil","D) Todas as anteriores (independe de tudo isso)","E) Apenas da capacidade civil"],g:"D",c:"Art. 126 CTN: a capacidade tributaria passiva independe da capacidade civil, de restricoes ao exercicio de atividades e da regular constituicao da PJ."},
{a:2023,r:"FCC/Fiscal-2023",q:"A denuncia espontanea (art. 138 CTN) afasta:",o:["A) O tributo devido","B) A responsabilidade por infracoes, se acompanhada do pagamento do tributo e juros","C) Os juros de mora","D) A correcao monetaria","E) Sempre todas as penalidades, mesmo sem pagamento"],g:"B",c:"Art. 138: a denuncia espontanea, com pagamento do tributo + juros antes de qualquer procedimento fiscal, exclui a responsabilidade por infracoes (multa). Sumula 360 STJ: nao se aplica a tributo declarado e nao pago."},
{a:2022,r:"FCC/PGE-2022",q:"Na solidariedade tributaria, o pagamento por um dos obrigados:",o:["A) Nao aproveita aos demais","B) Aproveita aos demais","C) Extingue so a parte dele","D) Depende de convenio","E) Exige autorizacao judicial"],g:"B",c:"Art. 125, I: o pagamento efetuado por um dos obrigados APROVEITA aos demais. A isencao/remissao tambem, salvo se outorgada pessoalmente."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A moratoria, quando em carater individual:",o:["A) Gera direito adquirido","B) NAO gera direito adquirido e pode ser revogada se cessadas as condicoes","C) E irrevogavel","D) Independe de lei","E) Extingue o credito"],g:"B",c:"Art. 155: a moratoria individual NAO gera direito adquirido; revoga-se de oficio se o beneficiario nao satisfazia as condicoes (cobranca com juros)."},
{a:2023,r:"FCC/Fiscal-2023",q:"A consignacao em pagamento (art. 164) cabe quando:",o:["A) O contribuinte quer parcelar","B) Ha recusa de recebimento ou exigencia de tributo indevido por mais de um ente","C) Ha decadencia","D) Ocorre remissao","E) Ha isencao"],g:"B",c:"Art. 164: cabe consignacao em caso de recusa de recebimento, subordinacao a outra exigencia, ou exigencia por mais de uma PJ sobre o mesmo fato gerador."},
{a:2022,r:"FCC/PGE-2022",q:"A isencao concedida por prazo certo e sob condicao onerosa:",o:["A) Pode ser revogada a qualquer tempo","B) Nao pode ser livremente revogada (Sumula 544 STF)","C) Independe de lei","D) E o mesmo que imunidade","E) Atinge a obrigacao acessoria"],g:"B",c:"Sumula 544 STF: isencoes tributarias concedidas sob condicao onerosa e por prazo certo NAO podem ser livremente suprimidas."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O lancamento reporta-se a data:",o:["A) Do lancamento","B) Da ocorrencia do fato gerador, regendo-se pela lei entao vigente","C) Da inscricao em divida ativa","D) Do pagamento","E) Da notificacao"],g:"B",c:"Art. 144: o lancamento reporta-se a data do FATO GERADOR e rege-se pela lei entao vigente, ainda que posteriormente modificada ou revogada."},
{a:2023,r:"FCC/Fiscal-2023",q:"A decadencia do direito de lancar, no lancamento de oficio, conta-se:",o:["A) Do fato gerador","B) Do 1o dia do exercicio seguinte aquele em que poderia ter sido lancado","C) Da inscricao em divida ativa","D) Da notificacao","E) Do pagamento antecipado"],g:"B",c:"Art. 173, I: 5 anos contados do 1o dia do exercicio seguinte aquele em que o lancamento poderia ter sido efetuado (regra geral/oficio)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Sobre a anterioridade tributaria, o IPI:",o:["A) Submete-se a anterioridade anual","B) Submete-se apenas a noventena (anterioridade nonagesimal)","C) Nao se submete a nenhuma","D) Submete-se as duas","E) E imune"],g:"B",c:"O IPI e excecao a anterioridade ANUAL, mas obedece a NOVENTENA (90 dias). II, IE e IOF nao se submetem a nenhuma das duas."},
{a:2023,r:"FCC/Fiscal-2023",q:"A obrigacao acessoria, pelo simples fato de sua inobservancia, converte-se em:",o:["A) Isencao","B) Obrigacao principal relativamente a penalidade pecuniaria","C) Imunidade","D) Anistia","E) Remissao"],g:"B",c:"Art. 113, par.3 CTN: a obrigacao acessoria, pelo seu descumprimento, converte-se em principal quanto a PENALIDADE PECUNIARIA (multa)."},
{a:2022,r:"FCC/PGE-2022",q:"O CTN admite a interpretacao literal da legislacao que disponha sobre:",o:["A) Obrigacao principal","B) Suspensao/exclusao do credito, outorga de isencao e dispensa de obrigacoes acessorias","C) Fato gerador","D) Base de calculo","E) Sujeito passivo"],g:"B",c:"Art. 111 CTN: interpreta-se LITERALMENTE a legislacao sobre suspensao/exclusao do credito, isencao e dispensa de cumprimento de obrigacoes acessorias."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A taxa, como tributo, tem por fato gerador:",o:["A) Qualquer atividade economica","B) O exercicio do poder de policia ou servico publico especifico e divisivel","C) A propriedade","D) A renda","E) A circulacao de mercadorias"],g:"B",c:"Art. 77 CTN: a taxa tem como FG o exercicio regular do poder de policia ou a utilizacao (efetiva/potencial) de servico publico especifico e divisivel."},
{a:2023,r:"FCC/Fiscal-2023",q:"A contribuicao de melhoria e instituida para fazer face ao custo de:",o:["A) Servicos gerais","B) Obras publicas de que decorra valorizacao imobiliaria","C) Iluminacao publica","D) Coleta de lixo","E) Seguranca"],g:"B",c:"Art. 81 CTN: contribuicao de melhoria decorre de OBRA PUBLICA que gere VALORIZACAO imobiliaria; limite total = despesa da obra; limite individual = valorizacao de cada imovel."},
{a:2022,r:"FCC/PGE-2022",q:"No CTN, a 'norma geral antielisiva' (art. 116, PU) permite a autoridade:",o:["A) Criar tributos","B) Desconsiderar atos/negocios praticados para dissimular o fato gerador","C) Anular isencoes","D) Aumentar aliquotas","E) Conceder remissao"],g:"B",c:"Art. 116, PU: a autoridade pode DESCONSIDERAR atos ou negocios juridicos praticados com a finalidade de DISSIMULAR a ocorrencia do fato gerador (norma antielisiva, pende de lei ordinaria de procedimentos)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O domicilio tributario, na falta de eleicao, para a pessoa juridica de direito privado e:",o:["A) O do socio","B) O lugar da sua sede ou de cada estabelecimento","C) O da residencia do contador","D) A Capital do Estado","E) O domicilio do credor"],g:"B",c:"Art. 127, II CTN: na falta de eleicao, o domicilio da PJ de direito privado e o lugar de sua SEDE ou, em relacao aos atos que derem origem a obrigacao, o de cada ESTABELECIMENTO."},
{a:2023,r:"FCC/Fiscal-2023",q:"A responsabilidade dos sucessores na aquisicao de fundo de comercio (art. 133) e integral quando o alienante:",o:["A) Continua a explorar atividade","B) Cessa a exploracao e nao inicia nova atividade em 6 meses","C) Paga o tributo","D) E pessoa fisica","E) Tem isencao"],g:"B",c:"Art. 133: o adquirente responde INTEGRALMENTE se o alienante CESSAR a exploracao; e SUBSIDIARIAMENTE se o alienante prosseguir ou iniciar nova atividade em ate 6 meses."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A compensacao tributaria, como forma de extincao:",o:["A) Independe de lei","B) Depende de lei que estipule as condicoes e garantias","C) E automatica","D) So por decisao judicial","E) Equivale a remissao"],g:"B",c:"Art. 170 CTN: a lei pode autorizar a COMPENSACAO de creditos tributarios com creditos liquidos e certos do sujeito passivo contra a Fazenda, nas condicoes que estipular."},
{a:2023,r:"FCC/Fiscal-2023",q:"Segundo o CTN, tributo NAO constitui sancao de ato ilicito. Isso significa que:",o:["A) Multa e tributo","B) A hipotese de incidencia nao pode ser um ato ilicito, mas a renda de atividade ilicita e tributavel (pecunia non olet)","C) Atividade ilicita nunca e tributada","D) Tributo e penalidade","E) So o licito gera renda"],g:"B",c:"Art. 3 CTN: tributo nao e sancao de ato ilicito (difere de multa). Porem, pelo principio PECUNIA NON OLET (art. 118), a renda obtida de atividade ilicita E tributavel."},
],
"DTR-2":[
{a:2024,r:"FCC/RT-2024",q:"A EC 132/2023 criou o IBS, de competencia:",o:["A) Federal","B) Estadual","C) Compartilhada entre estados, DF e municipios","D) Municipal","E) Uniao e estados"],g:"C",c:"EC 132/2023: IBS=competencia COMPARTILHADA (estados, DF, municipios), substitui ICMS+ISS, gerido pelo Comite Gestor (art. 156-B)."},
{a:2024,r:"FCC-estilo-2024",q:"O Comite Gestor do IBS tem como funcao:",o:["A) Politica monetaria","B) Administrar, arrecadar, fiscalizar e cobrar o IBS","C) Substituir o CONFAZ totalmente","D) Definir o IR","E) Regular o ISS municipal isolado"],g:"B",c:"Art. 156-B: Comite Gestor administra, arrecada, fiscaliza, cobra e representa o IBS. Colegiado de estados, DF e municipios."},
{a:2024,r:"FCC-estilo-2024",q:"O principio do DESTINO no IBS significa:",o:["A) Imposto no local de producao","B) Imposto devido no local de consumo","C) Aliquota por destino economico","D) So importacoes","E) Partilha 50/50"],g:"B",c:"DESTINO: imposto devido no local de CONSUMO, nao de producao. Reduz a guerra fiscal, alinha-se ao IVA internacional."},
{a:2023,r:"FCC/Fiscal-2023",q:"A CBS substitui:",o:["A) IPI e ICMS","B) PIS e COFINS","C) IRPJ e CSLL","D) IOF e ITR","E) IPI e IOF"],g:"B",c:"CBS=Contribuicao sobre Bens e Servicos: substitui PIS e COFINS. Competencia FEDERAL, administracao pela Receita Federal."},
{a:2023,r:"FCC/SEFAZ-2023",q:"O Imposto Seletivo (IS) incide sobre:",o:["A) Exportacoes","B) Operacoes financeiras","C) Bens/servicos prejudiciais a saude ou ao meio ambiente","D) Combustiveis substituindo o ICMS","E) Todo consumo a 1%"],g:"C",c:"IS (art. 153, VIII): bens/servicos PREJUDICIAIS a saude ou ao meio ambiente. Federal. Nao integra a base do IBS/CBS."},
{a:2024,r:"FCC-estilo-2024",q:"O modelo de tributacao sobre consumo da reforma e do tipo:",o:["A) Cumulativo","B) IVA dual (IBS subnacional + CBS federal)","C) Monofasico geral","D) Imposto unico federal","E) So estadual"],g:"B",c:"Reforma adota IVA DUAL: IBS (estados/municipios) + CBS (federal), com nao-cumulatividade plena e principio do destino."},
{a:2024,r:"FCC-estilo-2024",q:"A nao-cumulatividade PLENA do IBS significa:",o:["A) Credito so fisico","B) Credito amplo de todo IBS pago nas etapas anteriores","C) Sem direito a credito","D) Credito so do ativo","E) Credito so de insumos industriais"],g:"B",c:"Nao-cumulatividade PLENA: credito amplo de todo o IBS que onerou as aquisicoes, com poucas excecoes (uso/consumo pessoal)."},
{a:2023,r:"FCC/Fiscal-2023",q:"A transicao da reforma tributaria conclui-se em:",o:["A) 2026","B) 2027","C) 2029","D) 2033","E) 2040"],g:"D",c:"Transicao: inicio em 2026 (teste 0,1%), CBS plena em 2027, reducao gradual do ICMS/ISS 2029-2032, sistema completo em 2033."},
{a:2024,r:"FCC-estilo-2024",q:"O cashback previsto na reforma destina-se a:",o:["A) Grandes empresas","B) Devolucao de tributo a familias de baixa renda","C) Exportadores","D) Estados deficitarios","E) Importadores"],g:"B",c:"Cashback: devolucao de parte do IBS/CBS a familias de BAIXA RENDA, reduzindo a regressividade do consumo."},
{a:2023,r:"FCC/SEFAZ-2023",q:"A CBS sera administrada pela:",o:["A) Comite Gestor do IBS","B) Receita Federal do Brasil","C) Secretarias estaduais","D) CONFAZ","E) Banco Central"],g:"B",c:"CBS (federal): administrada pela RECEITA FEDERAL. O IBS (subnacional) e administrado pelo Comite Gestor."},
{a:2024,r:"FCC/RT-2024",q:"A EC 132/2023 instituiu o principio da:",o:["A) Cumulatividade","B) Neutralidade e simplicidade tributaria","C) Tributacao na origem","D) Anterioridade nonagesimal apenas","E) Progressividade do consumo"],g:"B",c:"A EC 132 trouxe os principios da SIMPLICIDADE, TRANSPARENCIA, JUSTICA TRIBUTARIA, COOPERACAO e DEFESA DO MEIO AMBIENTE, alem da NEUTRALIDADE do IVA."},
{a:2024,r:"FCC-estilo-2024",q:"A cesta basica nacional de alimentos, na reforma:",o:["A) Tera aliquota dobrada","B) Tera aliquota ZERO de IBS e CBS","C) Sera tributada normalmente","D) So tera reducao de 50%","E) Sera isenta apenas de CBS"],g:"B",c:"A LC define a Cesta Basica Nacional de Alimentos com aliquota ZERO de IBS e CBS, para reduzir a regressividade."},
{a:2024,r:"FCC-estilo-2024",q:"O 'split payment' previsto na reforma consiste em:",o:["A) Dividir o pagamento em parcelas","B) Recolhimento do imposto no momento da liquidacao financeira da operacao","C) Pagar metade do imposto","D) Parcelar o IBS","E) Dividir entre estados"],g:"B",c:"Split payment: o imposto e segregado e recolhido automaticamente no momento da liquidacao financeira (pagamento), reduzindo a sonegacao."},
{a:2023,r:"FCC/Fiscal-2023",q:"Na reforma, os setores com regimes ESPECIFICOS incluem:",o:["A) Apenas industria","B) Combustiveis, servicos financeiros, planos de saude, entre outros","C) Somente exportadores","D) So o agronegocio","E) Nenhum setor"],g:"B",c:"A EC 132 preve regimes especificos para combustiveis (monofasico), servicos financeiros, seguros, planos de saude, operacoes imobiliarias, cooperativas etc."},
{a:2024,r:"FCC-estilo-2024",q:"O Fundo de Desenvolvimento Regional, criado pela reforma:",o:["A) Foi extinto","B) Visa reduzir desigualdades regionais com recursos da Uniao","C) E custeado pelos municipios","D) So atende o Sul","E) Substitui o FPE"],g:"B",c:"A EC 132 criou o Fundo Nacional de Desenvolvimento Regional (FNDR), com aportes da Uniao, para reduzir desigualdades regionais apos o fim da guerra fiscal."},
{a:2023,r:"FCC/Fiscal-2023",q:"Durante a transicao, em 2026, a aliquota-teste de CBS e IBS:",o:["A) 1% cada","B) CBS 0,9% e IBS 0,1%","C) 5%","D) 12%","E) Zero"],g:"B",c:"Em 2026: aliquota-teste com CBS de 0,9% e IBS de 0,1% (compensaveis com PIS/COFINS), para calibrar o sistema."},
{a:2024,r:"FCC-estilo-2024",q:"O Imposto Seletivo NAO incidira sobre:",o:["A) Cigarros","B) Bebidas alcoolicas","C) Exportacoes","D) Veiculos poluentes","E) Bens prejudiciais a saude"],g:"C",c:"O IS NAO incide sobre exportacoes (imunidade). Incide sobre bens/servicos prejudiciais a saude e ao meio ambiente, como tabaco e alcool."},
{a:2024,r:"FCC-estilo-2024",q:"A nao-cumulatividade plena do IBS/CBS difere do ICMS atual porque:",o:["A) Veda totalmente o credito","B) Permite credito amplo, inclusive de bens de uso e consumo da atividade","C) So permite credito fisico","D) E cumulativa","E) Exige convenio"],g:"B",c:"Na reforma, a nao-cumulatividade e PLENA: credita-se de praticamente tudo que foi onerado (inclusive uso/consumo da atividade), exceto uso pessoal. Hoje o ICMS limita o credito de uso e consumo."},
{a:2024,r:"FCC/RT-2024",q:"Na reforma, o IBS e a CBS adotam o creditamento do tipo:",o:["A) Fisico","B) Financeiro amplo (credito sobre tudo que foi onerado, exceto uso/consumo pessoal)","C) Presumido obrigatorio","D) Cumulativo","E) Por estimativa"],g:"B",c:"IVA dual: credito FINANCEIRO amplo - credita-se de praticamente todas as aquisicoes onerosas, exceto bens/servicos de uso/consumo pessoal."},
{a:2024,r:"FCC-estilo-2024",q:"O Comite Gestor do IBS sera composto por representantes:",o:["A) Apenas da Uniao","B) Dos Estados, DF e Municipios","C) Do setor privado","D) Do Congresso","E) Do Banco Central"],g:"B",c:"O Comite Gestor do IBS e entidade publica sob regime especial, composta por representantes dos ESTADOS, DF e MUNICIPIOS, sem participacao da Uniao (que cuida da CBS)."},
{a:2024,r:"FCC-estilo-2024",q:"A cashback (devolucao) na reforma sera obrigatoria nas operacoes de:",o:["A) Veiculos","B) Energia eletrica e gas de botijao para familias de baixa renda","C) Importacao","D) Servicos financeiros","E) Combustiveis"],g:"B",c:"A LC preve cashback OBRIGATORIO em energia eletrica e gas de cozinha (botijao) para familias de baixa renda inscritas no CadUnico, reduzindo a regressividade."},
{a:2023,r:"FCC/Fiscal-2023",q:"Durante a transicao, o ICMS e o ISS serao extintos em:",o:["A) 2026","B) 2027","C) 2029","D) 2033","E) 2040"],g:"D",c:"O ICMS e o ISS serao reduzidos gradualmente de 2029 a 2032 e EXTINTOS em 2033, quando o IBS estara plenamente vigente."},
{a:2024,r:"FCC-estilo-2024",q:"A 'aliquota de referencia' do IBS e fixada por:",o:["A) Cada municipio livremente","B) Resolucao do Senado Federal, podendo o ente fixar a sua propria","C) Decreto do Presidente","D) Lei complementar federal apenas","E) Convenio CONFAZ"],g:"B",c:"A aliquota de REFERENCIA e fixada por Resolucao do Senado, para repor a arrecadacao; cada ente pode fixar aliquota propria por lei, somando-se a estadual e a municipal."},
{a:2024,r:"FCC-estilo-2024",q:"O Imposto Seletivo tambem incidira sobre a extracao de:",o:["A) Agua","B) Recursos minerais (ate 1% do valor de mercado)","C) Petroleo isento","D) Energia solar","E) Madeira de reflorestamento"],g:"B",c:"O IS incidira ainda sobre a EXTRACAO de bens minerais e petroleo, com aliquota maxima de 1% do valor de mercado do produto extraido."},
{a:2023,r:"FCC/Fiscal-2023",q:"A nao-cumulatividade na reforma e assegurada por:",o:["A) Credito presumido","B) Credito do imposto destacado e efetivamente recolhido nas etapas anteriores","C) Isencao","D) Reducao de base","E) Diferimento"],g:"B",c:"Na reforma, o credito depende do efetivo recolhimento do imposto nas etapas anteriores (split payment ajuda a garantir isso), assegurando a nao-cumulatividade plena."},
{a:2024,r:"FCC-estilo-2024",q:"Os entes que perderem arrecadacao com o fim da guerra fiscal serao compensados pelo:",o:["A) FPE","B) Fundo de Compensacao de Beneficios Fiscais e pelo FNDR","C) Bolsa Familia","D) Tesouro municipal","E) BNDES"],g:"B",c:"A reforma criou o Fundo de Compensacao de Beneficios Fiscais (ate 2032, para honrar incentivos de ICMS ja concedidos) e o Fundo Nacional de Desenvolvimento Regional (FNDR)."},
{a:2023,r:"FCC/Fiscal-2023",q:"O principio da TRANSPARENCIA tributaria na EC 132 implica que:",o:["A) O tributo fica oculto no preco","B) O contribuinte deve poder identificar o valor do IBS/CBS na operacao","C) Nao ha divulgacao","D) So o Fisco conhece o valor","E) O tributo e secreto"],g:"B",c:"A EC 132 consagra a TRANSPARENCIA: o imposto sobre consumo deve ser visivel ao consumidor (destacado), permitindo-lhe conhecer a carga tributaria da operacao."},
{a:2024,r:"FCC-estilo-2024",q:"Sobre a Zona Franca de Manaus, a reforma tributaria:",o:["A) Extinguiu seus beneficios","B) Manteve o tratamento diferenciado e favorecido","C) Ignorou","D) Transferiu para o Nordeste","E) Reduziu pela metade"],g:"B",c:"A EC 132 preservou o tratamento tributario DIFERENCIADO E FAVORECIDO da Zona Franca de Manaus, com instrumentos para manter sua competitividade."},
],
"DTR-3":[
{a:2023,r:"FCC/SEFAZ-2023",q:"Na LC 87/96, o credito do ICMS sobre ATIVO PERMANENTE:",o:["A) E integral no mes","B) E a razao de 1/48 por mes","C) Nao gera credito","D) So para industria","E) Em qualquer prazo"],g:"B",c:"LC 87/96 art. 20 par.5: ativo permanente -> credito a razao de 1/48 por mes (4 anos)."},
{a:2022,r:"FCC/Fiscal-2022",q:"Os convenios CONFAZ (LC 24/75) sao aprovados por:",o:["A) Maioria simples","B) Unanimidade dos estados presentes","C) 2/3 dos estados","D) Decisao do STF","E) Maioria absoluta"],g:"B",c:"LC 24/75: convenios de ICMS exigem UNANIMIDADE dos presentes (minimo 4/5). Um estado pode vetar."},
{a:2021,r:"FCC/SEFAZ-2021",q:"No Simples Nacional (LC 123/2006), o ICMS-ST:",o:["A) Entra no DAS","B) E recolhido separadamente, fora do DAS","C) E isento","D) Tem aliquota zero","E) E facultativo"],g:"B",c:"ICMS-ST NAO entra no DAS: recolhido SEPARADAMENTE. O DAS reune os demais tributos do Simples em guia unica."},
{a:2020,r:"FCC/Adm-2020",q:"A nao-cumulatividade do ICMS (LC 87/96) permite:",o:["A) Credito so na industria","B) Compensar o imposto devido com o cobrado nas etapas anteriores","C) Credito de uso e consumo ja","D) Credito ilimitado","E) Nenhum credito"],g:"B",c:"Nao-cumulatividade: compensa-se o ICMS devido com o montante cobrado nas operacoes anteriores. Uso e consumo: vedado ate 2033."},
{a:2019,r:"FCC/RS-2019",q:"As aliquotas interestaduais de ICMS sao:",o:["A) Sempre 18%","B) 7% ou 12% conforme a regiao de destino","C) 25%","D) Definidas por cada estado","E) Zero"],g:"B",c:"Aliquotas interestaduais: 7% (Sul/Sudeste -> Norte/Nordeste/CO/ES) e 12% (demais). Fixadas por Resolucao do Senado."},
{a:2023,r:"FCC/TRT-2023",q:"A LC 116/2003 trata do:",o:["A) ICMS","B) ISS (Imposto Sobre Servicos) - competencia municipal","C) IPVA","D) ITCD","E) IPI"],g:"B",c:"LC 116/2003: normas gerais do ISSQN, competencia MUNICIPAL. Lista anexa define os servicos tributaveis pelo ISS."},
{a:2022,r:"FCC/Fiscal-2022",q:"O DIFAL (EC 87/2015) e cobrado:",o:["A) So nas importacoes","B) Na operacao interestadual destinada a consumidor final","C) Em todas as vendas internas","D) So no Simples","E) Nunca"],g:"B",c:"DIFAL: diferencial de aliquota nas operacoes interestaduais destinadas a consumidor final (contribuinte ou nao do imposto)."},
{a:2021,r:"FCC/SEFAZ-2021",q:"A LC 160/2017 tratou de:",o:["A) Criar o IBS","B) Remissao/convalidacao de beneficios de ICMS concedidos sem convenio","C) Extinguir o ICMS","D) Aumentar aliquotas","E) Criar o Simples"],g:"B",c:"LC 160/2017: permitiu a remissao e convalidacao de beneficios fiscais de ICMS concedidos sem convenio (guerra fiscal pretérita)."},
{a:2020,r:"FCC/Adm-2020",q:"No Simples Nacional, os limites de receita sao (anual):",o:["A) MEI 81 mil, ME 360 mil, EPP 4,8 milhoes","B) MEI 60 mil, ME 300 mil, EPP 3,6 milhoes","C) MEI 100 mil, ME 500 mil, EPP 5 milhoes","D) Sem limite","E) ME 1 milhao"],g:"A",c:"LC 123: MEI ate 81 mil/ano, ME ate 360 mil, EPP ate 4,8 milhoes. Acima -> exclusao do regime."},
{a:2019,r:"FCC/RS-2019",q:"A LC 105/2001 trata:",o:["A) Do Simples Nacional","B) Do sigilo bancario e seu acesso pelo Fisco","C) Do ISS","D) Do IPVA","E) Da reforma tributaria"],g:"B",c:"LC 105/2001: dispoe sobre o sigilo das operacoes financeiras e o acesso de dados bancarios pela administracao tributaria."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na LC 87/96, o ICMS NAO incide sobre:",o:["A) Energia eletrica","B) Operacoes que destinem mercadorias ao exterior (exportacao)","C) Comunicacao onerosa","D) Transporte interestadual","E) Importacao"],g:"B",c:"Art. 3, II LC 87/96: nao incide sobre exportacoes (imunidade do art. 155, par.2, X, 'a' CF), assegurado o credito das operacoes anteriores."},
{a:2023,r:"FCC/Fiscal-2023",q:"O local da operacao para cobranca do ICMS, em regra, e:",o:["A) O do destino","B) O do estabelecimento onde se encontre a mercadoria no momento do fato gerador","C) O do consumidor","D) O da sede da empresa","E) O do transportador"],g:"B",c:"Art. 11 LC 87/96: em regra, o local da operacao e o do estabelecimento onde a mercadoria se encontra no momento da ocorrencia do fato gerador (origem)."},
{a:2022,r:"FCC/SEFAZ-2022",q:"A base de calculo do ICMS na importacao inclui:",o:["A) Apenas o valor da mercadoria","B) Valor da mercadoria + II + IPI + IOF + despesas aduaneiras + o proprio ICMS","C) So o frete","D) Somente o II","E) Valor FOB sem tributos"],g:"B",c:"BC do ICMS-importacao: valor da mercadoria + Imposto de Importacao + IPI + IOF + demais despesas aduaneiras + o proprio ICMS (calculo por dentro)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A LC 24/75 exige convenio para:",o:["A) Aumentar aliquota interna","B) Conceder isencoes, incentivos e beneficios fiscais de ICMS","C) Criar obrigacao acessoria","D) Definir contribuinte","E) Fixar prazo de recolhimento"],g:"B",c:"LC 24/75: isencoes, reducoes de base, creditos presumidos e demais beneficios de ICMS dependem de CONVENIO aprovado no CONFAZ (unanimidade)."},
{a:2023,r:"FCC/Fiscal-2023",q:"No Simples Nacional, NAO podem optar empresas que:",o:["A) Faturem ate 4,8 milhoes","B) Exerçam atividade de banco, financeira ou que tenham socio PJ","C) Sejam MEI","D) Sejam comercio","E) Prestem servico permitido"],g:"B",c:"Art. 17 LC 123: vedacoes - instituicoes financeiras, empresas com socio PJ, com filial no exterior, que prestem certos servicos, debito com o INSS/Fazenda etc."},
{a:2022,r:"FCC/SEFAZ-2022",q:"A substituicao tributaria 'para frente' tem respaldo:",o:["A) Apenas legal","B) Constitucional (art. 150, par.7 CF), com restituicao se o FG presumido nao ocorrer","C) Vedada pelo STF","D) So por convenio","E) Apenas para combustiveis"],g:"B",c:"Art. 150, par.7 CF: autoriza a ST progressiva, assegurando a restituicao da quantia paga se o fato gerador presumido nao se realizar. STF (RE 593.849): cabe restituicao tambem se a base efetiva for menor."},
{a:2024,r:"FCC/SEFAZ-2024",q:"No DIFAL para consumidor final NAO contribuinte (EC 87/15), o imposto cabe:",o:["A) Integralmente a origem","B) Ao estado de DESTINO, recolhido pelo remetente","C) Ao municipio","D) A Uniao","E) Ao transportador"],g:"B",c:"EC 87/2015: na venda interestadual a consumidor final nao contribuinte, o DIFAL cabe ao estado de DESTINO e e recolhido pelo remetente (LC 190/2022)."},
{a:2023,r:"FCC/Fiscal-2023",q:"O ICMS sobre combustiveis, apos a LC 192/2022, e:",o:["A) Cumulativo","B) Monofasico, com aliquotas uniformes nacionais definidas por convenio","C) Isento","D) Progressivo","E) Cobrado em todas as etapas"],g:"B",c:"LC 192/2022: ICMS MONOFASICO sobre combustiveis (incide uma unica vez), com aliquotas ad rem uniformes em todo o pais, definidas pelo CONFAZ."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Na LC 87/96, o creditamento do ICMS sobre energia eletrica e permitido quando:",o:["A) Sempre, para qualquer uso","B) Consumida no processo de industrializacao ou em operacao de saida/exportacao","C) Nunca","D) So no comercio","E) So uso residencial"],g:"B",c:"LC 87/96 art. 33, II: o credito de energia eletrica e admitido quando consumida no PROCESSO DE INDUSTRIALIZACAO ou na proporcao de operacoes de saida/exportacao tributadas."},
{a:2023,r:"FCC/Fiscal-2023",q:"A imunidade do ICMS na exportacao assegura ao exportador:",o:["A) Perda do credito","B) A manutencao e o aproveitamento dos creditos das operacoes anteriores","C) Aliquota majorada","D) Substituicao tributaria","E) Diferimento"],g:"B",c:"Art. 155, par.2, X, 'a' CF + LC 87/96: a exportacao e imune, mas ASSEGURA-SE a manutencao do credito relativo as entradas (nao-estorno)."},
{a:2022,r:"FCC/SEFAZ-2022",q:"O fato gerador do ICMS no fornecimento de alimentacao em bares e restaurantes:",o:["A) Nao incide","B) Incide ICMS sobre o valor total (mercadoria + servico)","C) Incide so ISS","D) E imune","E) So sobre a bebida"],g:"B",c:"Sumula 163 STJ: o fornecimento de mercadorias com servico em bares/restaurantes sujeita-se ao ICMS sobre o VALOR TOTAL da operacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A LC 24/75 estabelece que a concessao de beneficio sem convenio gera:",o:["A) Validade plena","B) Nulidade do ato e ineficacia do credito fiscal respectivo","C) Apenas advertencia","D) Multa ao contribuinte","E) Suspensao do CONFAZ"],g:"B",c:"LC 24/75 art. 8: a inobservancia (beneficio sem convenio) acarreta a NULIDADE do ato e a ineficacia do credito fiscal atribuido, alem da exigibilidade do imposto nao pago."},
{a:2023,r:"FCC/Fiscal-2023",q:"No Simples Nacional, a tributacao e:",o:["A) Por dentro de cada tributo isolado","B) Unificada em documento unico (DAS) com aliquotas progressivas por faixa de receita","C) Isenta","D) Fixa em 6%","E) Por estimativa anual"],g:"B",c:"Simples Nacional: recolhimento UNIFICADO via DAS, com aliquotas efetivas PROGRESSIVAS conforme a faixa de receita bruta acumulada (anexos I a V)."},
{a:2022,r:"FCC/SEFAZ-2022",q:"A alíquota interestadual de 4% no ICMS aplica-se a:",o:["A) Todas as operacoes","B) Bens importados ou com conteudo de importacao superior a 40% (Resolucao SF 13/2012)","C) Servicos","D) Energia","E) Combustiveis"],g:"B",c:"Resolucao do Senado 13/2012: aliquota interestadual de 4% para bens/mercadorias IMPORTADOS ou com conteudo de importacao > 40% (combate a guerra dos portos)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O contribuinte do ICMS na importacao e:",o:["A) Sempre o vendedor estrangeiro","B) A pessoa, fisica ou juridica, que importa, ainda que sem habitualidade","C) O transportador","D) A Uniao","E) O despachante"],g:"B",c:"LC 87/96 art. 4, PU: e contribuinte na importacao quem importa mercadorias do exterior, AINDA QUE SEM HABITUALIDADE ou intuito comercial (inclusive PF)."},
{a:2023,r:"FCC/Fiscal-2023",q:"No diferimento do ICMS:",o:["A) Antecipa-se o pagamento","B) Posterga-se o lancamento/pagamento para etapa futura, atribuindo a responsabilidade a outro contribuinte","C) Isenta-se a operacao","D) Reduz-se a base","E) Dobra-se a aliquota"],g:"B",c:"DIFERIMENTO (ST 'para tras'): adia-se o momento do recolhimento para etapa posterior da cadeia, transferindo a responsabilidade (ex: produtor rural -> industria)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A LC 116/2003 define que o ISS, em regra, e devido no:",o:["A) Local do tomador","B) Local do estabelecimento prestador (com excecoes da lista)","C) Domicilio do cliente","D) Local da sede da empresa sempre","E) Municipio da capital"],g:"B",c:"LC 116/2003 art. 3: em REGRA o ISS e devido no local do ESTABELECIMENTO PRESTADOR; ha excecoes (ex: construcao civil, limpeza) em que e devido no local da prestacao."},
{a:2023,r:"FCC/Fiscal-2023",q:"O Simples Nacional e administrado por:",o:["A) Cada estado isoladamente","B) Comite Gestor do Simples Nacional (Uniao, Estados e Municipios)","C) Apenas a Receita Federal","D) CONFAZ","E) Municipios"],g:"B",c:"O Simples Nacional e gerido pelo COMITE GESTOR DO SIMPLES NACIONAL (CGSN), com representantes da Uniao (RFB), Estados/DF e Municipios."},
],
"LTE-1":[
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O 'ICMS por dentro' significa que:",o:["A) Calcula-se excluindo o tributo","B) O ICMS integra a propria base de calculo","C) Incide so na industria","D) E recolhido antes da NF","E) Substitui tributos municipais"],g:"B",c:"ICMS por dentro: BC=valor sem ICMS/(1-aliquota). Ex: 82/0,82=100 -> ICMS=18. Aliquota efetiva (21,95%) > nominal (18%)."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"A substituicao tributaria PROGRESSIVA no ICMS-CE:",o:["A) Responsabiliza o adquirente pelas etapas anteriores","B) Atribui ao fabricante/importador o ICMS das etapas subsequentes","C) E inconstitucional","D) Dispensa NF","E) So para essenciais"],g:"B",c:"ST progressiva (para frente): substituto (fabricante/importador) recolhe o ICMS das etapas futuras (MVA/pauta). FG presumido nao ocorrido -> restituicao."},
{a:2021,r:"FCC/SEFAZ-CE-2021",q:"O ITCD do Ceara (Lei 15.812/2015) incide sobre:",o:["A) Transmissao onerosa de imoveis","B) Transmissao causa mortis e doacao de quaisquer bens","C) Circulacao de mercadorias","D) Servicos","E) Propriedade de veiculos"],g:"B",c:"ITCD-CE: causa mortis (heranca) e doacao de quaisquer bens/direitos. Competencia estadual. Aliquotas progressivas; maxima 8%."},
{a:2020,r:"FCC/SEFAZ-CE-2020",q:"O FECOP do Ceara (LC 37/2003) consiste em:",o:["A) Fundo previdenciario","B) Adicional de ICMS de ate 2% sobre superfluos para combate a pobreza","C) Taxa de importacao","D) Contribuicao de melhoria","E) Fundo de equalizacao"],g:"B",c:"FECOP: Fundo Estadual de Combate a Pobreza, adicional de ICMS de ate 2% sobre produtos superfluos. Base: art. 82 ADCT."},
{a:2019,r:"FCC/SEFAZ-CE-2019",q:"O IPVA-CE (Lei 12.023/1992) tem como fato gerador:",o:["A) Transmissao do veiculo","B) Propriedade de veiculo automotor em 1 de janeiro","C) Circulacao em rodovias","D) Licenciamento","E) Importacao"],g:"B",c:"IPVA: propriedade de veiculo automotor em 1 de janeiro. Base de calculo: valor venal. Aliquotas diferenciadas por tipo de veiculo."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O contribuinte do ICMS-CE e:",o:["A) So a industria","B) Quem realiza operacoes de circulacao com habitualidade ou volume","C) So o consumidor final","D) Apenas importadores","E) So atacadistas"],g:"B",c:"Contribuinte: quem realiza, com habitualidade ou em volume que caracterize intuito comercial, operacoes de circulacao de mercadorias ou prestacoes."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"Na nao-cumulatividade do ICMS-CE, o credito de uso e consumo:",o:["A) E permitido desde ja","B) Esta vedado ate 2033","C) E integral","D) E de 1/48","E) Nunca existira"],g:"B",c:"Material de uso e consumo: credito VEDADO ate 2033 (LC 87/96 art. 33, aplicada no CE). Ativo permanente: 1/48 por mes."},
{a:2021,r:"FCC/SEFAZ-CE-2021",q:"O diferimento (ST regressiva) no ICMS-CE:",o:["A) Antecipa o imposto","B) Posterga o recolhimento para etapa posterior","C) Isenta o produto","D) Dobra a aliquota","E) Dispensa a NF"],g:"B",c:"DIFERIMENTO (ST regressiva/para tras): posterga o recolhimento do ICMS para etapa posterior da cadeia (ex: produtor rural)."},
{a:2020,r:"FCC/SEFAZ-CE-2020",q:"A base de calculo do ITCD-CE e:",o:["A) O valor venal do bem ou direito transmitido","B) O valor de aquisicao historico","C) O dobro do IPTU","D) A renda do herdeiro","E) O valor simbolico"],g:"A",c:"ITCD: base de calculo = valor venal (de mercado) do bem ou direito transmitido por heranca ou doacao."},
{a:2019,r:"FCC/SEFAZ-CE-2019",q:"O RICMS-CE foi aprovado pelo:",o:["A) Decreto 33.327/2019","B) Lei federal 5.172/66","C) LC 87/96","D) EC 132/2023","E) Lei 12.023/92"],g:"A",c:"O RICMS-CE atual e o Decreto 33.327/2019, que regulamenta o ICMS no Ceara (consolidado com a Lei 18.665/2023)."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"No RICMS-CE, considera-se ocorrido o fato gerador na:",o:["A) Emissao do pedido","B) Saida da mercadoria do estabelecimento do contribuinte","C) Entrega ao consumidor","D) Inscricao estadual","E) Assinatura do contrato"],g:"B",c:"O FG do ICMS ocorre, entre outras hipoteses, na SAIDA da mercadoria do estabelecimento, ainda que para outro do mesmo titular (com ressalvas da jurisprudencia - Sumula 166 STJ para mesma titularidade)."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"A aliquota interna geral do ICMS no Ceara, apos as alteracoes recentes, situa-se em torno de:",o:["A) 7%","B) 12%","C) 18% a 20%","D) 25%","E) 30%"],g:"C",c:"A aliquota interna padrao do ICMS-CE foi ajustada para a faixa de 18% a 20% (a banca cobra a aplicacao; confira a aliquota vigente no RICMS-CE atual)."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"O contribuinte substituto, na ST do ICMS-CE, e responsavel por:",o:["A) Recolher so o seu imposto","B) Reter e recolher o ICMS das operacoes subsequentes (ST para frente)","C) Nao recolher nada","D) Pagar so o DIFAL","E) Apenas emitir nota"],g:"B",c:"Na ST progressiva, o substituto (industria/importador) retem e recolhe o ICMS devido nas etapas seguintes da cadeia, com base na MVA/pauta."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"A escrituracao fiscal digital (EFD) no Ceara tem por finalidade:",o:["A) Substituir o pagamento","B) Prestar informacoes fiscais e apurar o ICMS em arquivo digital","C) Isentar o contribuinte","D) Eliminar a nota fiscal","E) Apenas controle interno da empresa"],g:"B",c:"A EFD (SPED Fiscal) e a escrituracao digital dos livros e documentos fiscais, usada para apurar o ICMS e prestar informacoes ao Fisco estadual."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O credito acumulado de ICMS no Ceara pode, em regra:",o:["A) Nunca ser transferido","B) Ser transferido a outros estabelecimentos ou utilizado conforme a legislacao estadual","C) Ser convertido em dinheiro automaticamente","D) Ser doado","E) Ser usado para pagar IPVA"],g:"B",c:"O credito acumulado (ex: exportador) pode ser transferido/utilizado nos termos do RICMS-CE, observados os limites e a homologacao do Fisco."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"A nota fiscal eletronica (NF-e) no Ceara:",o:["A) E facultativa para todos","B) E obrigatoria e autorizada pela SEFAZ antes da circulacao","C) Substitui a apuracao","D) Dispensa a EFD","E) So vale para servicos"],g:"B",c:"A NF-e e documento fiscal eletronico obrigatorio, autorizado pela SEFAZ (protocolo de autorizacao) antes da circulacao da mercadoria."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"O regime de antecipacao do ICMS no Ceara aplica-se tipicamente a:",o:["A) Exportacoes","B) Entradas interestaduais de mercadorias para revenda","C) Servicos municipais","D) Operacoes isentas","E) Vendas a consumidor final local"],g:"B",c:"A antecipacao tributaria recai sobre entradas interestaduais (cobra-se o ICMS antecipadamente na entrada), conforme o RICMS-CE, podendo ou nao encerrar a tributacao."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O FECOP no Ceara destina-se a:",o:["A) Custeio da maquina administrativa","B) Acoes e programas de combate a pobreza e inclusao social","C) Pagamento de servidores","D) Obras viarias","E) Fundo previdenciario"],g:"B",c:"O FECOP (adicional de ate 2% no ICMS de produtos superfluos) e vinculado a programas de combate a pobreza e inclusao social (art. 82 ADCT / LC estadual)."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"No calculo do ICMS 'por dentro', se a mercadoria custa R$164 sem ICMS e a aliquota e 18%, a base e:",o:["A) R$164","B) R$200 (164/0,82)","C) R$193,52","D) R$180","E) R$196,80"],g:"B",c:"ICMS por dentro: BC = valor sem ICMS / (1 - aliquota) = 164/0,82 = 200. ICMS = 200 x 18% = 36."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"No RICMS-CE, a margem de valor agregado (MVA) e usada para:",o:["A) Calcular o IPVA","B) Definir a base de calculo presumida na substituicao tributaria","C) Reduzir a aliquota","D) Isentar produtos","E) Apurar o ITCD"],g:"B",c:"A MVA (ou IVA-ST) e o percentual aplicado para estimar a BASE DE CALCULO PRESUMIDA das operacoes subsequentes na substituicao tributaria 'para frente'."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"O ITCD cearense incide sobre doacao e, no caso de bens imoveis, e devido ao estado:",o:["A) Do domicilio do doador","B) Da situacao do bem imovel","C) Do donatario","D) Onde o ITCD foi pago","E) Da capital"],g:"B",c:"Na doacao/transmissao de BENS IMOVEIS, o ITCD e devido ao Estado da SITUACAO do bem (art. 155, par.1, I CF). Bens moveis: domicilio do doador (doacao) ou do inventario."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"A antecipacao tributaria do ICMS-CE, quando 'com encerramento de fase':",o:["A) Gera nova cobranca na saida","B) Encerra a tributacao, dispensando recolhimento na operacao subsequente","C) Isenta o produto","D) Difere o pagamento","E) Aumenta a aliquota"],g:"B",c:"Na antecipacao COM encerramento de fase (similar a ST), o recolhimento na entrada ENCERRA a tributacao, nao havendo novo debito na saida subsequente."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O IPVA-CE e devido proporcionalmente quando:",o:["A) O veiculo e zero-km adquirido durante o ano","B) Sempre integral","C) Nunca","D) So para usados","E) Apenas em janeiro"],g:"A",c:"Para veiculo NOVO (zero-km) adquirido ao longo do exercicio, o IPVA-CE e devido PROPORCIONALMENTE aos meses restantes, contados da aquisicao."},
{a:2022,r:"FCC/SEFAZ-CE-2022",q:"A inscricao no Cadastro Geral da Fazenda (CGF) do Ceara e:",o:["A) Facultativa","B) Obrigatoria para quem realiza operacoes sujeitas ao ICMS","C) So para industrias","D) Dispensada para o Simples","E) Anual e onerosa"],g:"B",c:"A inscricao no CGF e OBRIGATORIA para os contribuintes que realizam operacoes/prestacoes sujeitas ao ICMS no Ceara, identificando-os perante o Fisco."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"A diferenca entre aliquota interna e interestadual (DIFAL) no CE, para consumidor final contribuinte:",o:["A) Cabe a origem","B) E recolhida pelo proprio adquirente (contribuinte) ao Ceara","C) Nao existe","D) Cabe a Uniao","E) E isenta"],g:"B",c:"No DIFAL para consumidor final CONTRIBUINTE do ICMS, o proprio adquirente apura e recolhe a diferenca de aliquota ao estado de destino (Ceara)."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O regime de estimativa do ICMS-CE aplica-se a:",o:["A) Grandes industrias","B) Contribuintes de pequeno porte cuja apuracao normal seja dificil, com valor fixado pelo Fisco","C) Exportadores","D) Substitutos tributarios","E) Importadores"],g:"B",c:"O regime de ESTIMATIVA fixa um valor de ICMS a recolher para contribuintes em que a apuracao normal seja inviavel/dificil, conforme criterios da SEFAZ-CE."},
{a:2024,r:"FCC/SEFAZ-CE-2024",q:"A nota fiscal de consumidor eletronica (NFC-e) no Ceara destina-se a:",o:["A) Operacoes interestaduais","B) Vendas no varejo a consumidor final, substituindo o cupom fiscal","C) Exportacoes","D) Servicos municipais","E) Transferencias"],g:"B",c:"A NFC-e e o documento fiscal eletronico para vendas a CONSUMIDOR FINAL no varejo presencial, substituindo o antigo cupom fiscal (ECF)."},
{a:2023,r:"FCC/SEFAZ-CE-2023",q:"O lancamento do ICMS-CE, em regra, e do tipo:",o:["A) De oficio","B) Por homologacao (o contribuinte apura e antecipa o pagamento)","C) Por declaracao","D) Por arbitramento sempre","E) Misto"],g:"B",c:"O ICMS, inclusive no Ceara, e tributo sujeito a lancamento por HOMOLOGACAO: o contribuinte apura e recolhe antecipadamente, cabendo ao Fisco homologar (ou lancar de oficio se houver falta)."},
],
"FLD-1":[
{a:2023,r:"FCC/TI-2023",q:"A clausula HAVING em SQL:",o:["A) Filtra linhas antes do agrupamento","B) Filtra grupos apos o GROUP BY","C) Ordena resultados","D) Define colunas","E) Substitui o WHERE em linhas"],g:"B",c:"HAVING filtra GRUPOS apos GROUP BY (usa SUM, COUNT, AVG). WHERE filtra LINHAS antes, sem funcoes de agregacao."},
{a:2022,r:"FCC/Analista-2022",q:"O Data Lakehouse combina:",o:["A) So dados relacionais","B) Flexibilidade do Data Lake com ACID e performance do Data Warehouse","C) So tempo real","D) Banco operacional e Data Mart","E) Nuvem e on-premises"],g:"B",c:"Lakehouse: une dados brutos do Data Lake + transacoes ACID + performance analitica do DW (ex: Delta Lake, Iceberg)."},
{a:2021,r:"FCC/TI-2021",q:"A base legal da LGPD para o Fisco tratar dados de fiscalizacao e:",o:["A) Consentimento","B) Legitimo interesse","C) Cumprimento de obrigacao legal/regulatoria","D) Execucao de contrato","E) Protecao da vida"],g:"C",c:"Art. 7, II LGPD: cumprimento de obrigacao legal ou regulatoria. A fiscalizacao tributaria e obrigacao legal (CTN art. 194), dispensa consentimento."},
{a:2020,r:"FCC/TI-2020",q:"O processo ETL realiza:",o:["A) So encriptacao","B) Extracao de multiplas fontes, transformacao e carga em repositorio","C) Backups","D) Monitoramento de qualidade so","E) Indexacao"],g:"B",c:"ETL: Extract (coleta), Transform (limpeza/padronizacao), Load (carga no DW/Lakehouse). ELT inverte transform e load (cloud)."},
{a:2019,r:"FCC/Analista-2019",q:"O LEFT JOIN retorna:",o:["A) So correspondencias em ambas","B) Todos os registros da esquerda + correspondentes da direita (NULL se nao)","C) Produto cartesiano","D) So a direita","E) Apenas duplicatas"],g:"B",c:"LEFT JOIN: todos da tabela esquerda + correspondentes da direita (NULL onde nao ha). INNER: so correspondencias; CROSS: produto cartesiano."},
{a:2023,r:"FCC/TI-2023",q:"Em um Data Warehouse, o esquema e tipicamente:",o:["A) Schema-on-read","B) Schema-on-write (dados curados na entrada)","C) Sem esquema","D) Apenas NoSQL","E) Grafo"],g:"B",c:"DW: schema-on-WRITE (estrutura definida na carga, dados curados). Data Lake: schema-on-READ (estrutura na leitura, dados brutos)."},
{a:2022,r:"FCC/Analista-2022",q:"O encarregado de dados (DPO) na LGPD:",o:["A) E o titular dos dados","B) E o canal entre controlador, titulares e a ANPD","C) E o operador","D) Define a base legal sozinho","E) Audita o sistema"],g:"B",c:"DPO (encarregado): canal de comunicacao entre o controlador, os titulares e a ANPD (Autoridade Nacional de Protecao de Dados)."},
{a:2021,r:"FCC/TI-2021",q:"Dados semiestruturados sao representados por formatos como:",o:["A) Tabelas relacionais","B) JSON e XML","C) Imagens puras","D) Texto livre","E) Video"],g:"B",c:"Semiestruturados: JSON, XML (tem marcadores/tags mas nao esquema rigido). Estruturados=tabelas; nao estruturados=texto/imagem/video."},
{a:2020,r:"FCC/TI-2020",q:"A triade CIA da seguranca da informacao significa:",o:["A) Controle, Integracao, Auditoria","B) Confidencialidade, Integridade, Disponibilidade","C) Criptografia, Identidade, Acesso","D) Custo, Impacto, Analise","E) Cloud, IA, Analytics"],g:"B",c:"CIA: Confidencialidade (sigilo), Integridade (nao adulteracao), Disponibilidade (acesso quando necessario)."},
{a:2019,r:"FCC/Analista-2019",q:"A ordem de execucao logica de uma consulta SQL inicia por:",o:["A) SELECT","B) FROM","C) WHERE","D) ORDER BY","E) GROUP BY"],g:"B",c:"Ordem de execucao: FROM -> JOIN -> WHERE -> GROUP BY -> HAVING -> SELECT -> ORDER BY -> LIMIT. SELECT vem depois do agrupamento."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Em SQL, para contar registros por categoria usa-se:",o:["A) WHERE COUNT","B) GROUP BY com a funcao COUNT()","C) ORDER BY","D) DISTINCT apenas","E) HAVING sem GROUP BY"],g:"B",c:"Agregacao por categoria: GROUP BY categoria + COUNT(*). O HAVING filtra os grupos resultantes; o WHERE filtra linhas antes."},
{a:2023,r:"FCC/Analista-2023",q:"Em um Data Warehouse, o esquema ESTRELA (star schema) tem:",o:["A) Varias tabelas fato normalizadas","B) Uma tabela fato central ligada a tabelas dimensao desnormalizadas","C) So tabelas dimensao","D) Estrutura sem fatos","E) Apenas chaves primarias"],g:"B",c:"Star schema: uma tabela FATO central (metricas) cercada por tabelas DIMENSAO desnormalizadas. O floco de neve (snowflake) normaliza as dimensoes."},
{a:2022,r:"FCC/TI-2022",q:"Na LGPD, dados sensiveis incluem:",o:["A) Nome e endereco","B) Origem racial, conviccao religiosa, saude, dado genetico/biometrico","C) CPF apenas","D) E-mail","E) Telefone"],g:"B",c:"Dados SENSIVEIS (art. 5, II): origem racial/etnica, conviccao religiosa, opiniao politica, saude, vida sexual, dado genetico ou biometrico. Tem protecao reforcada."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O aprendizado de maquina SUPERVISIONADO caracteriza-se por:",o:["A) Dados sem rotulo","B) Treinar com dados rotulados (entrada e saida conhecidas)","C) Nao usar dados","D) Apenas agrupar","E) Aprendizado por reforco"],g:"B",c:"Aprendizado SUPERVISIONADO: usa dados ROTULADOS (X->Y conhecidos), ex: classificacao e regressao. NAO SUPERVISIONADO: sem rotulos (clusterizacao)."},
{a:2023,r:"FCC/Analista-2023",q:"O comando SQL para remover duplicatas no resultado e:",o:["A) DELETE","B) DISTINCT","C) DROP","D) TRUNCATE","E) GROUP"],g:"B",c:"SELECT DISTINCT retorna apenas linhas unicas (remove duplicatas do resultado). DELETE/DROP/TRUNCATE alteram dados/estrutura."},
{a:2022,r:"FCC/TI-2022",q:"Big Data e usualmente descrito pelos V's, entre eles:",o:["A) Valor, Visao, Verdade","B) Volume, Velocidade, Variedade (e Veracidade, Valor)","C) Vetor, Versao","D) Visual, Virtual","E) Verbo, Voz"],g:"B",c:"Os V's do Big Data: VOLUME (quantidade), VELOCIDADE (geracao/processamento), VARIEDADE (formatos), VERACIDADE (confiabilidade) e VALOR."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O encarregado (DPO) pela LGPD tem como atribuicao:",o:["A) Vender dados","B) Ser canal entre controlador, titulares e a ANPD, orientando sobre praticas","C) Definir o lucro","D) Auditar contas","E) Aprovar a LOA"],g:"B",c:"O encarregado/DPO (art. 41): aceita reclamacoes dos titulares, comunica-se com a ANPD e orienta a organizacao sobre protecao de dados."},
{a:2023,r:"FCC/Analista-2023",q:"Numa consulta com JOIN, a clausula ON define:",o:["A) A ordenacao","B) A condicao de relacionamento entre as tabelas","C) O agrupamento","D) O filtro de grupos","E) As colunas exibidas"],g:"B",c:"ON especifica a CONDICAO de juncao (ex: a.id = b.id) que relaciona as tabelas no JOIN."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Em SQL, a subconsulta (subquery) e:",o:["A) Uma tabela fisica","B) Uma consulta aninhada dentro de outra (ex: no WHERE ou FROM)","C) Um indice","D) Uma chave estrangeira","E) Um gatilho"],g:"B",c:"SUBQUERY (subconsulta): consulta SELECT aninhada dentro de outra (no WHERE, FROM ou SELECT), usada para filtrar/derivar dados a partir de outro resultado."},
{a:2023,r:"FCC/Analista-2023",q:"Na modelagem dimensional, a tabela FATO armazena tipicamente:",o:["A) Descricoes textuais","B) Metricas/medidas numericas e chaves para as dimensoes","C) So chaves primarias","D) Atributos descritivos","E) Hierarquias"],g:"B",c:"A tabela FATO contem as MEDIDAS numericas do negocio (vendas, valores) e as chaves estrangeiras que apontam para as tabelas DIMENSAO (descritivas)."},
{a:2022,r:"FCC/TI-2022",q:"Os agentes de tratamento na LGPD sao:",o:["A) Titular e ANPD","B) Controlador e operador","C) Encarregado e titular","D) ANPD e operador","E) So o controlador"],g:"B",c:"Agentes de tratamento (LGPD): CONTROLADOR (decide sobre o tratamento) e OPERADOR (realiza o tratamento em nome do controlador). O encarregado (DPO) e o canal de comunicacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A clausula WHERE NAO pode conter:",o:["A) Comparacoes","B) Funcoes de agregacao como SUM e COUNT (estas vao no HAVING)","C) AND/OR","D) LIKE","E) BETWEEN"],g:"B",c:"Funcoes de AGREGACAO (SUM, COUNT, AVG, MAX, MIN) nao podem ser usadas no WHERE (que filtra linhas antes do agrupamento); devem ir no HAVING (apos GROUP BY)."},
{a:2023,r:"FCC/Analista-2023",q:"O processo de transformar dado bruto em formato adequado para analise chama-se:",o:["A) Backup","B) Data wrangling / preparacao de dados (limpeza e transformacao)","C) Mineracao","D) Indexacao","E) Replicacao"],g:"B",c:"DATA WRANGLING (ou preparacao/limpeza): processo de limpar, estruturar e transformar dados brutos em formato adequado para analise (etapa que consome boa parte do projeto de dados)."},
{a:2022,r:"FCC/TI-2022",q:"Um data lake difere de um data warehouse por armazenar dados:",o:["A) So estruturados","B) Brutos em diversos formatos (estruturados e nao estruturados), schema-on-read","C) So numericos","D) Apenas processados","E) Em tabelas relacionais"],g:"B",c:"DATA LAKE: armazena grandes volumes de dados BRUTOS em qualquer formato (schema-on-read). DATA WAREHOUSE: dados estruturados e curados (schema-on-write) para BI."},
],
"FPB-1":[
{a:2023,r:"FCC/Fiscal-2023",q:"As tres funcoes do governo (Musgrave) sao:",o:["A) Arrecadar, fiscalizar, redistribuir","B) Alocativa, distributiva, estabilizadora","C) Regulatoria, tributaria, redistributiva","D) Planejar, executar, controlar","E) Producao, monopolio, externalidade"],g:"B",c:"Musgrave: ALOCATIVA (falhas de mercado), DISTRIBUTIVA (desigualdade), ESTABILIZADORA (emprego/precos/crescimento)."},
{a:2022,r:"FCC/Fiscal-2022",q:"Os bens publicos PUROS caracterizam-se por:",o:["A) Rivalidade e exclusao","B) Nao rivalidade e nao exclusao (free rider)","C) Rivalidade e nao exclusao","D) Nao rivalidade e exclusao","E) Alta rivalidade"],g:"B",c:"Bem publico puro: NAO RIVAL + NAO EXCLUDENTE -> free rider -> mercado falha -> Estado prove. Ex: defesa nacional, iluminacao publica."},
{a:2021,r:"FCC/TCE-2021",q:"O superavit primario indica que:",o:["A) Pagou todos os juros sem deficit","B) Receitas nao financeiras > despesas nao financeiras, antes dos juros","C) A divida total caiu","D) O nominal e positivo","E) Nao houve nova divida"],g:"B",c:"Superavit PRIMARIO: esforco fiscal antes dos juros. Pode coexistir com deficit nominal (se os juros superarem o superavit)."},
{a:2020,r:"FCC/Econ-2020",q:"A externalidade NEGATIVA gera falha porque:",o:["A) Produz pouco","B) Custo social > privado; mercado produz em excesso","C) Empresas nao lucram","D) E bem publico","E) Exige subsidio"],g:"B",c:"Externalidade negativa: custo social > privado -> producao acima do otimo. Solucao: imposto pigouviano (poluidor-pagador)."},
{a:2019,r:"FCC/Econ-2019",q:"A NFSP nominal e:",o:["A) Primario - juros reais","B) Deficit primario + juros nominais","C) Receitas - despesas","D) Variacao da divida - correcao","E) Operacional + cambio"],g:"B",c:"NFSP nominal = deficit primario + juros nominais (= -resultado primario + juros). Mede a variacao da divida liquida do setor publico."},
{a:2023,r:"FCC/Fiscal-2023",q:"A funcao DISTRIBUTIVA do governo atua por meio de:",o:["A) Controle da inflacao","B) Impostos progressivos, transferencias e subsidios","C) Provisao de defesa nacional","D) Politica monetaria","E) Regulacao de monopolios"],g:"B",c:"Funcao DISTRIBUTIVA: reduzir desigualdade via impostos progressivos, transferencias (programas sociais) e subsidios."},
{a:2022,r:"FCC/Fiscal-2022",q:"A externalidade POSITIVA (ex: vacinacao):",o:["A) Gera producao em excesso","B) Gera producao abaixo do otimo; solucao: subsidio","C) E um bem privado puro","D) Exige imposto","E) Cria monopolio"],g:"B",c:"Externalidade positiva: beneficio social > privado -> producao ABAIXO do otimo. Solucao: subsidio ou provisao publica."},
{a:2021,r:"FCC/TCE-2021",q:"O resultado NOMINAL do setor publico:",o:["A) Exclui os juros","B) Inclui os juros nominais (primario - juros)","C) E sempre superavitario","D) Ignora a divida","E) Mede so o PIB"],g:"B",c:"NOMINAL = primario - juros nominais. Reflete a variacao total da divida. PRIMARIO exclui os juros (mede esforco fiscal)."},
{a:2020,r:"FCC/Econ-2020",q:"O monopolio natural justifica intervencao porque:",o:["A) Ha muitos concorrentes","B) Custos decrescentes tornam ineficiente a duplicacao -> regulacao","C) E bem publico","D) Gera externalidade positiva","E) Tem demanda elastica"],g:"B",c:"Monopolio natural: custos medios decrescentes (uma so firma atende com menor custo). Estado regula (preco/qualidade) para evitar abuso."},
{a:2019,r:"FCC/Econ-2019",q:"O criterio do BENEFICIO na tributacao defende que:",o:["A) Paga mais quem tem mais renda","B) Paga quem se beneficia do gasto publico, na proporcao do beneficio","C) Todos pagam igual","D) So empresas pagam","E) Tributa-se o consumo"],g:"B",c:"Criterio do BENEFICIO: o tributo deve ser pago por quem se beneficia do servico publico (ex: taxas, contribuicao de melhoria). Alternativa: capacidade contributiva."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A funcao ESTABILIZADORA do governo busca:",o:["A) Reduzir desigualdade","B) Manter pleno emprego, estabilidade de precos e crescimento","C) Prover bens publicos","D) Corrigir externalidades","E) Cobrar tributos"],g:"B",c:"Funcao ESTABILIZADORA (Musgrave): atuar sobre o nivel de emprego, precos e crescimento via politicas fiscal e monetaria (anticiclicas)."},
{a:2023,r:"FCC/Fiscal-2023",q:"Um imposto e REGRESSIVO quando:",o:["A) Aumenta com a renda","B) Pesa proporcionalmente mais sobre quem tem menor renda","C) E proporcional","D) So atinge ricos","E) E progressivo"],g:"B",c:"Imposto REGRESSIVO: a carga relativa e MAIOR para os de menor renda (tipico de tributos sobre consumo). Progressivo: aliquota cresce com a base."},
{a:2022,r:"FCC/PGE-2022",q:"A 'tragedia dos comuns' ilustra a falha de:",o:["A) Bens privados","B) Recursos comuns (rivais e nao excludentes) sobreexplorados","C) Monopolio","D) Bens publicos puros","E) Informacao perfeita"],g:"B",c:"Tragedia dos comuns: recursos COMUNS (rivais, mas nao excludentes - ex: pesca, pastagem) tendem a ser superexplorados, pois o custo e coletivo e o beneficio individual."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O principio da capacidade contributiva sustenta a:",o:["A) Tributacao pelo beneficio","B) Tributacao conforme a possibilidade economica do contribuinte (progressividade)","C) Aliquota unica","D) Isencao geral","E) Tributo fixo"],g:"B",c:"Capacidade contributiva (art. 145, par.1 CF): cada um contribui conforme sua capacidade economica, fundamentando a progressividade e a pessoalidade dos impostos."},
{a:2023,r:"FCC/Fiscal-2023",q:"A divida publica BRUTA difere da liquida porque a liquida:",o:["A) Inclui mais passivos","B) Deduz os ativos financeiros (creditos) do governo","C) Ignora a divida externa","D) E sempre maior","E) Exclui a divida interna"],g:"B",c:"Divida LIQUIDA = divida bruta - ativos financeiros do setor publico (reservas, creditos). A BRUTA considera apenas os passivos."},
{a:2022,r:"FCC/PGE-2022",q:"A senhoriagem refere-se a:",o:["A) Imposto sobre renda","B) Receita do governo decorrente da emissao de moeda","C) Divida externa","D) Transferencia a estados","E) Tarifa publica"],g:"B",c:"SENHORIAGEM: ganho do governo ao emitir moeda (diferenca entre o valor de face e o custo de producao); em excesso, gera inflacao (imposto inflacionario)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Bens MERITORIOS (meritory goods) sao aqueles que:",o:["A) O mercado prove em excesso","B) O Estado incentiva por serem socialmente desejaveis (ex: educacao, saude)","C) Sao puramente privados","D) Geram externalidade negativa","E) Nao tem demanda"],g:"B",c:"Bens MERITORIOS: o Estado estimula seu consumo por gerarem beneficios sociais (educacao, saude, cultura), ainda que os individuos os subvalorizem."},
{a:2023,r:"FCC/Fiscal-2023",q:"O resultado operacional do setor publico exclui, em relacao ao nominal:",o:["A) Os juros reais","B) A correcao monetaria/atualizacao da divida","C) As receitas","D) As despesas primarias","E) Os investimentos"],g:"B",c:"Resultado OPERACIONAL = nominal excluida a correcao monetaria (atualizacao cambial/inflacionaria) da divida. Mede o esforco real sem o efeito inflacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A funcao ALOCATIVA do governo justifica-se principalmente por:",o:["A) Desigualdade de renda","B) Falhas de mercado (bens publicos, externalidades, monopolios, assimetria)","C) Inflacao","D) Desemprego","E) Cambio"],g:"B",c:"Funcao ALOCATIVA: o Estado intervem para corrigir FALHAS DE MERCADO - bens publicos, externalidades, monopolios naturais e assimetria de informacao."},
{a:2023,r:"FCC/Fiscal-2023",q:"Um sistema tributario progressivo contribui para a funcao:",o:["A) Alocativa","B) Distributiva (reduz desigualdade)","C) Estabilizadora","D) Reguladora","E) Cambial"],g:"B",c:"A PROGRESSIVIDADE (quem ganha mais paga proporcionalmente mais) serve a funcao DISTRIBUTIVA, reduzindo a desigualdade de renda."},
{a:2022,r:"FCC/PGE-2022",q:"O 'imposto inflacionario' refere-se a:",o:["A) IR sobre ganhos","B) Perda do poder de compra da moeda em poder do publico devido a inflacao","C) ICMS","D) Tarifa publica","E) Contribuicao social"],g:"B",c:"IMPOSTO INFLACIONARIO: a inflacao corroi o valor da moeda retida pelo publico, transferindo recursos reais ao governo emissor (ligado a senhoriagem)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"O equilibrio orcamentario intertemporal preconiza que:",o:["A) O orcamento deve fechar todo ano","B) Deficits presentes implicam superavits futuros (restricao orcamentaria do governo no tempo)","C) Nunca havera deficit","D) A divida e irrelevante","E) Gastos sao ilimitados"],g:"B",c:"Restricao orcamentaria INTERTEMPORAL: deficits hoje (mais divida) exigem superavits primarios futuros para manter a solvencia; o governo nao pode rolar divida indefinidamente sem ajuste."},
{a:2023,r:"FCC/Fiscal-2023",q:"Externalidade negativa de producao gera:",o:["A) Custo social menor que o privado","B) Custo social maior que o privado, com producao acima do otimo","C) Subsidio","D) Bem publico","E) Producao otima"],g:"B",c:"Externalidade NEGATIVA (ex: poluicao): custo SOCIAL > custo PRIVADO, levando a producao ACIMA do nivel socialmente otimo. Correcao: imposto de Pigou."},
{a:2022,r:"FCC/PGE-2022",q:"A teoria da tributacao otima busca:",o:["A) Maximizar a carga","B) Arrecadar o necessario minimizando as distorcoes (peso morto) e respeitando a equidade","C) Eliminar tributos","D) Tributar so o consumo","E) Aliquota zero"],g:"B",c:"Tributacao OTIMA: arrecadar a receita necessaria com o MENOR custo de eficiencia (peso morto) possivel, conciliando eficiencia e equidade (trade-off)."},
{a:2024,r:"FCC/SEFAZ-2024",q:"A regra de ouro das financas publicas estabelece que o endividamento deve financiar:",o:["A) Despesas correntes","B) Despesas de capital (investimentos), nao o custeio","C) Folha de pagamento","D) Juros","E) Qualquer despesa"],g:"B",c:"REGRA DE OURO: as operacoes de credito (divida) nao podem exceder as despesas de CAPITAL - o endividamento financia investimento, nao custeio corrente."},
{a:2023,r:"FCC/Fiscal-2023",q:"O criterio do beneficio na tributacao associa o tributo ao:",o:["A) Patrimonio","B) Beneficio que o contribuinte recebe do gasto publico (ex: taxas, pedagio)","C) Lucro","D) Consumo","E) Numero de filhos"],g:"B",c:"Criterio do BENEFICIO: paga mais quem se beneficia mais do servico publico (taxas, contribuicao de melhoria, pedagio). Alternativa a capacidade contributiva."},
{a:2022,r:"FCC/PGE-2022",q:"A descentralizacao fiscal (federalismo fiscal) trata de:",o:["A) Centralizar tributos na Uniao","B) Distribuir competencias tributarias e encargos entre os niveis de governo","C) Eliminar estados","D) Unificar o orcamento","E) Privatizar a arrecadacao"],g:"B",c:"FEDERALISMO FISCAL: reparticao de competencias tributarias, encargos e transferencias entre Uniao, Estados e Municipios, buscando equilibrio entre autonomia e cooperacao."},
{a:2024,r:"FCC/SEFAZ-2024",q:"Bens semipublicos (ou de clube) caracterizam-se por:",o:["A) Nao-rivalidade e nao-exclusao","B) Nao-rivalidade ate certo ponto, mas com possibilidade de exclusao","C) Rivalidade total","D) Serem gratuitos","E) Ausencia de demanda"],g:"B",c:"Bens de CLUBE (semipublicos): ha possibilidade de EXCLUSAO (pode-se cobrar/barrar) e a nao-rivalidade vale ate o ponto de congestionamento (ex: TV por assinatura, rodovia com pedagio)."},
],
};
